from app import single_instance as _single_instance
_SINGLE_INSTANCE = _single_instance.acquire(
    is_pool_worker=_IS_POOL_WORKER,
    wait_seconds=(_single_instance.RESTART_WAIT_SECONDS if os.environ.get("FM_RESTART_WAIT_PORT") else 0.0),
    # Изолированный тест берёт СВОЙ замок (проверено в e2e_isolation: он обязан отличаться от
    # рабочего) — иначе тестовый экземпляр конкурировал бы с работающей программой владельца.
    mutex_name=(_E2E.mutex_name if _E2E is not None else _single_instance.MUTEX_NAME))
if not _SINGLE_INSTANCE.ok:
    if _SINGLE_INSTANCE.status == _single_instance.WAIT_TIMEOUT:
        _si_msg = ("Перезапуск не выполнен: прежняя копия 3DIWELL Farm Manager не завершилась за %d секунд.\n"
                   "Закройте её через значок в системном трее и запустите программу заново."
                   % int(_single_instance.RESTART_WAIT_SECONDS))
        _si_code = 1
    else:
        _si_msg = ("3DIWELL Farm Manager уже запущен.\n"
                   "Откройте существующее окно программы через значок в системном трее.")
        _si_code = 0
    try:
        print(_si_msg)          # запуск из исходников: сообщение видно в консоли
    except Exception:
        pass
    if getattr(sys, "frozen", False):
        _single_instance.message_box("3DIWELL Farm Manager", _si_msg)   # сборка: консоль спрятана в трей
    sys.exit(_si_code)          # штатный выход без traceback; НИ ОДНА база не открыта

def _import_pool_workers():
    """Сколько ядер под разбор: ~70% от доступных, минимум 1, потолок 32."""
    try:
        n = os.cpu_count() or 2
    except Exception:
        n = 2
    return max(1, min(int(round(n * 0.7)), 32))

_IMPORT_POOL = None
_IMPORT_POOL_OFF = False

def _get_import_pool():
    """Лениво создаёт пул процессов. При сбое — отключает его (дальше работаем потоками)."""
    global _IMPORT_POOL, _IMPORT_POOL_OFF
    if _IMPORT_POOL_OFF:
        return None
    if _IMPORT_POOL is None:
        try:
            ctx = _mp.get_context("spawn")   # одинаково и безопасно на Windows и Linux
            _IMPORT_POOL = _ProcessPoolExecutor(max_workers=_import_pool_workers(), mp_context=ctx)
        except Exception:
            try: log.warning("[import] failed to create process pool: %s", _exc_brief())
            except Exception: pass
            _IMPORT_POOL_OFF = True
            _IMPORT_POOL = None
    return _IMPORT_POOL

def _drop_import_pool():
    """Отключить пул на остаток сессии (после сбоя) и аккуратно погасить."""
    global _IMPORT_POOL, _IMPORT_POOL_OFF
    _IMPORT_POOL_OFF = True
    if _IMPORT_POOL is not None:
        try: _IMPORT_POOL.shutdown(wait=False, cancel_futures=True)
        except Exception: pass
        _IMPORT_POOL = None

_atexit.register(lambda: _IMPORT_POOL.shutdown(wait=False, cancel_futures=True) if _IMPORT_POOL is not None else None)
