@app.post("/api/project-runs/{run_id}/items/{item_id}/feed-plan/select")
async def whole_print_feed_select(run_id: str, item_id: str, req: Request):
    """Явный выбор кандидата оператором. Материалу/цвету/статусу из тела НЕ доверяем — сервер
    пересчитывает кандидата заново и ищет его ТОЛЬКО по фактическим printer/slot/spool."""
    d = await _json_body(req)
