async def pickpaths_project2_files(project_id: str, req: Request):
    """Добавить НЕСКОЛЬКО файлов (по путям из нашего Проводника) в существующий проект.
    Alpha 2.801: файлы КОПИРУЮТСЯ в managed-папку проекта (stored_path первичный), USB не нужен.
    Alpha 2.802: папка — из ЕДИНОГО резолвера (одна папка на проект)."""
    _pr = _get_project(project_id)
    if not _pr:
        return {"status": "error", "reason": "project not found"}
    raw = [p for p in ((await _json_body(req)).get("paths") or []) if isinstance(p, str)]
    paths = [p for p in raw if os.path.isfile(p) and _proj_file_ok(os.path.basename(p))]
    await asyncio.to_thread(_reconcile_owner_files, "project", project_id, _pr.get("name"))
    _pdir = await asyncio.to_thread(resolve_managed_owner_directory, "project", project_id, _pr.get("name"))
    added = []
    for p in paths:
        try:
            dest, _sha, _sz = await asyncio.to_thread(_import_copy_managed, p, _pdir, os.path.basename(p))
        except Exception as e:
            log.warning("[PROJ2 pick-paths] managed copy failed for %r: %s", os.path.basename(p), str(e)[:80])
            continue
        r = await asyncio.to_thread(add_file_to_project, project_id, os.path.basename(dest), "", dest)
        if r:
            added.append(r)
    return {"status": "ok", "added": added}

@app.post("/api/projects2/import-files")
async def import_files_as_project(req: Request):
    """Импорт файлов (.gcode/.gcode.3mf/.stl/.3mf) как НОВОГО проекта: создаём проект с авто-именем
    «Импорт DD.MM.YYYY» (при коллизии (1),(2),…) и привязываем оригиналы по пути (без копий).
    Имена деталей: для сликнутых — детект как обычно; для моделей — по имени файла."""
    data = await _json_body(req)
    raw = [p for p in (data.get("paths") or []) if isinstance(p, str)]
    paths = [p for p in raw if os.path.isfile(p) and _proj_file_ok(os.path.basename(p))]
    if not paths:
        return {"status": "error", "reason": "no valid files"}
    try:
        proj = create_project(_unique_import_project_name())
    except ProjectNameError as e:
        return _project_name_error_response(e)
    if not proj:
        return {"status": "error", "reason": "could not create project"}
    pid = proj["id"]
    # Alpha 2.802: у нового проекта папка создаётся ЕДИНЫМ резолвером — человекочитаемая,
    # со стабильным id в имени (два одноимённых проекта не делят одну папку).
    _pdir = resolve_managed_owner_directory("project", pid, proj.get("name"))
    added = []
    for p in paths:
        # Alpha 2.801: копируем в managed-папку нового проекта (stored_path первичный), USB не нужен.
        try:
            dest, _sha, _sz = _import_copy_managed(p, _pdir, os.path.basename(p))
        except Exception as e:
            log.warning("[PROJ2 import-files] managed copy failed for %r: %s", os.path.basename(p), str(e)[:80])
            continue
        r = add_file_to_project(pid, os.path.basename(dest), stored_path=dest)
        if r:
            added.append(r)
    return {"status": "ok", "project_id": pid, "name": proj["name"], "added": added}

