@app.post("/api/projects2/{project_id}/parts/{part_id}/rework")
async def request_part_rework(project_id: str, part_id: str, req: Request):
    """Запрос на перепечатку детали (брак при сборке). add=N — добавить к плану перепечатки;
    clear=true — отменить открытый запрос (rework_qty := rework_done). Основной счётчик не трогаем."""
    data = await _json_body(req)
    with lock_p, _rollback_sqlite_on_error(conn_p, "request_part_rework"):
        row = conn_p.execute("SELECT rework_qty, rework_done FROM project_parts WHERE id=? AND project_id=? AND is_deleted=0", (part_id, project_id)).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "not found"}, status_code=404)
        if data.get("clear"):
            conn_p.execute("UPDATE project_parts SET rework_qty=rework_done, updated_at=CURRENT_TIMESTAMP WHERE id=? AND project_id=?", (part_id, project_id))
        else:
            try:
                add = max(0, int(data.get("add") if data.get("add") is not None else (data.get("qty") or 0)))
            except Exception:
                add = 0
            if add:
                conn_p.execute("UPDATE project_parts SET rework_qty=rework_qty+?, updated_at=CURRENT_TIMESTAMP WHERE id=? AND project_id=?", (add, part_id, project_id))
        new = conn_p.execute("SELECT rework_qty, rework_done FROM project_parts WHERE id=? AND project_id=?", (part_id, project_id)).fetchone()
        conn_p.commit()
    return {"ok": True, "rework_qty": int(new["rework_qty"] or 0), "rework_done": int(new["rework_done"] or 0)}

