EXPORT_COLS = ["project_name", "due_date", "part_name", "required_qty", "printed_qty", "status", "notes", "gcode_file"]

@app.get("/api/projects/export")
def export_projects(project: str = ""):
    """Роут: экспорт проектов и деталей в архив."""
    with lock_p:
        if project:
            rows = [dict(r) for r in conn_p.execute("SELECT * FROM parts_catalog WHERE is_deleted=0 AND project_name=? ORDER BY order_idx", (project,)).fetchall()]
        else:
            rows = [dict(r) for r in conn_p.execute("SELECT * FROM parts_catalog WHERE is_deleted=0 ORDER BY project_name, order_idx").fetchall()]
    safe = re.sub(r'[^A-Za-z0-9_-]+', '_', project) if project else "all_projects"
    ts = time.strftime("%Y%m%d_%H%M%S")
    if HAS_XLSX:
        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Projects"
        ws.append([c.upper() for c in EXPORT_COLS])
        for r in rows:
            ws.append([r.get(c, "") for c in EXPORT_COLS])
        for i, c in enumerate(EXPORT_COLS, 1):
            ws.column_dimensions[openpyxl.utils.get_column_letter(i)].width = max(14, len(c) + 4)
        buf = io.BytesIO()
        wb.save(buf)
        return Response(content=buf.getvalue(), media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", headers={"Content-Disposition": f'attachment; filename="archive_{safe}_{ts}.xlsx"'})
    else:
        buf = io.StringIO()
        w = csv.writer(buf)
        w.writerow([c.upper() for c in EXPORT_COLS])
        for r in rows:
            w.writerow([r.get(c, "") for c in EXPORT_COLS])
        return Response(content=buf.getvalue(), media_type="text/csv", headers={"Content-Disposition": f'attachment; filename="archive_{safe}_{ts}.csv"'})

def _import_archive_bytes(raw, filename):
    """Импорт АРХИВА деталей (xlsx или CSV с заголовком part_name,...) из «сырых» байт.
    Общий код для загрузки файла и импорта по пути (из встроенного файлового менеджера)."""
    records = []
    name = (filename or "").lower()
    try:
        if name.endswith(".xlsx") and HAS_XLSX:
            wb = openpyxl.load_workbook(io.BytesIO(raw), read_only=True, data_only=True)
            ws = wb.active
            header = None
            for row in ws.iter_rows(values_only=True):
                if header is None:
                    header = [str(c).strip().lower() if c is not None else "" for c in row]
                    continue
                records.append({header[i]: row[i] for i in range(len(header)) if i < len(row)})
        else:
            text = raw.decode("utf-8", errors="ignore")
            rd = csv.DictReader(io.StringIO(text))
            for row in rd:
                records.append({(k or "").strip().lower(): v for k, v in row.items()})
    except Exception as e:
        return {"status": "error", "reason": str(e)}

    added = 0
    with lock_p:
        base = conn_p.execute("SELECT COALESCE(MAX(order_idx),0)+1 AS n FROM parts_catalog").fetchone()["n"]
        for rec in records:
            pname = str(rec.get("part_name", "") or "").strip()
            if not pname:
                continue
            def gi(k, d=0):
                """Безопасное чтение поля из импортируемой записи (хелпер)."""
                try: return int(float(rec.get(k, d) or d))
                except Exception: return d
            conn_p.execute(
                "INSERT INTO parts_catalog (part_name, required_qty, printed_qty, status, project_name, due_date, is_deleted, order_idx, preview_base64, notes, gcode_file) VALUES (?,?,?,?,?,?,0,?,?,?,?) ON CONFLICT(part_name) DO UPDATE SET required_qty=excluded.required_qty, printed_qty=excluded.printed_qty, status=excluded.status, project_name=excluded.project_name, due_date=excluded.due_date, is_deleted=0, notes=excluded.notes, gcode_file=excluded.gcode_file",
                (pname, gi("required_qty", 1), gi("printed_qty", 0), str(rec.get("status", "pending") or "pending"), str(rec.get("project_name", "Imported") or "Imported"), str(rec.get("due_date", "") or ""), base + added, "", str(rec.get("notes", "") or ""), str(rec.get("gcode_file", "") or ""))
            )
            added += 1
        conn_p.commit()
    return {"status": "ok", "imported": added}

@app.post("/api/projects/import")
async def import_projects(file: UploadFile = File(...)):
    """Роут: импорт проектов и деталей из архива (загрузка файла). .json/.xlsx/.csv с привязками файлов —
    round-trip архив Проектов 2.0; иначе — старый плоский архив склада."""
    raw = await file.read()
    fn = file.filename or ""
    low = fn.lower()
    if low.endswith(".json"):
        try:
            return _import_projects2_archive(json.loads(raw.decode("utf-8", errors="ignore")))
        except Exception as e:
            return {"status": "error", "reason": "bad json: " + str(e)}
    if low.endswith(".xlsx") or low.endswith(".csv"):
        recs = _parse_table_records(raw, fn)
        if recs and _is_projects2_table(recs):
            return _import_projects2_archive(_archive_table_to_obj(recs))
    return _import_archive_bytes(raw, fn)

@app.post("/api/import-path")
def import_path(data: Dict[str, Any]):
    """Роут: импорт плана/архива из файла НА ДИСКЕ по пути (для встроенного файлового
    менеджера — без копирования и без системного диалога). План или архив определяется
    по расширению и по заголовку первой строки CSV."""
    path = (data or {}).get("path", "") or ""
    if not _fs_policy.check_client_path(path).allow:   # Alpha 2.789: форма пути — до чтения файла
        return {"status": "error", "reason": "file not found"}
    if not path or not os.path.isfile(path):
        return {"status": "error", "reason": "file not found"}
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except Exception as e:
        return {"status": "error", "reason": str(e)}
    if path.lower().endswith(".json"):
        try:
            return _import_projects2_archive(json.loads(raw.decode("utf-8", errors="ignore")))
        except Exception as e:
            return {"status": "error", "reason": "bad json: " + str(e)}
    low = path.lower()
    if low.endswith(".xlsx") or low.endswith(".csv"):
        recs = _parse_table_records(raw, path)
        if recs and _is_projects2_table(recs):
            return _import_projects2_archive(_archive_table_to_obj(recs))
        if low.endswith(".xlsx"):
            return _import_archive_bytes(raw, path)
    try: first = raw.decode("utf-8", errors="ignore").splitlines()[0].lower()
    except Exception: first = ""
    if ("part_name" in first) or ("project_name" in first):
        return _import_archive_bytes(raw, path)
    return _import_plan_text(raw.decode("utf-8", errors="ignore"))

@app.post("/api/staging/delete")
def staging_delete(data: Dict[str, Any]):
    """Роут: удалить файл из Quick Tasks."""
    fname = os.path.basename(str(data.get("filename", "")))
    if not fname:
        return {"status": "error"}
    with lock_p, _rollback_sqlite_on_error(conn_p, "staging_delete"):
        row = conn_p.execute("SELECT src_path FROM staging_files WHERE filename=?", (fname,)).fetchone()
        linked = bool((row["src_path"] if row else "") or "")
        conn_p.execute("DELETE FROM staging_files WHERE filename=?", (fname,))
        conn_p.execute("DELETE FROM staging_part_counts WHERE filename=?", (fname,))
        conn_p.commit()
    # Привязанные оригиналы НИКОГДА не удаляем с диска — только убираем из списка.
    # Незалинкованная задача физически лежит в slicer_uploads (исторически могла быть и в temp_files);
    # удаляем из обеих — но только если на этот файл не ссылается ни один файл проекта.
    if not linked:
        try:
            cand = [os.path.join(UPLOAD_DIR, fname), os.path.join(TEMP_FILES_DIR, fname)]
            with lock_p:
                used = conn_p.execute(
                    "SELECT 1 FROM project_files WHERE src_path IN (?,?) OR stored_path IN (?,?) LIMIT 1",
                    (cand[0], cand[1], cand[0], cand[1])).fetchone()
                #  2.978: на этот же файл может ссылаться деталь из каталога (так их создаёт
                #  импорт плана: пишется gcode_file, а src_path остаётся пустым, и печать ищет
                #  файл по имени). Раньше проверялись только файлы проектов — файл стирался,
                #  и печать детали отвечала «файл не найден», хотя привязка выглядела целой.
                if not used:
                    used = conn_p.execute(
                        "SELECT 1 FROM parts_catalog WHERE is_deleted=0 AND "
                        "(src_path IN (?,?) OR (COALESCE(src_path,'')='' AND gcode_file=?)) LIMIT 1",
                        (cand[0], cand[1], fname)).fetchone()
            if not used:
                for fp in cand:
                    _unlink_in_managed(fp)
        except Exception:
            log.debug("[staging_delete] exception suppressed: %s", _exc_brief())
    _mesh_cache_purge(fname)   # удалить кэш-превью удалённого файла из папки кэша
    return {"status": "ok"}

@app.post("/api/part/attach-upload")
async def part_attach_upload(file: UploadFile = File(...)):
    """Роут: привязать загруженный файл к детали."""
    fname = os.path.basename(file.filename or "")
    if not fname or not fname.lower().endswith((".gcode", ".3mf")):
        return {"status": "error", "reason": "only .gcode/.3mf can be printed"}
    data = await file.read()
    # Уникальная копия по содержимому: одинаково названные g-коды (напр. plate_1.gcode из
    # разных проектов OrcaSlicer) не затирают друг друга и имеют РАЗНЫЙ предпросмотр и печать.
    try:
        sub = hashlib.md5(data).hexdigest()[:12]
        ddir = os.path.join(TEMP_FILES_DIR, "attach", sub)
        os.makedirs(ddir, exist_ok=True)
        full = os.path.join(ddir, fname)
        with open(full, "wb") as f:
            f.write(data)
    except Exception:
        return {"status": "error"}
    _prev = ""
    try:
        _png = _extract_local_png(full, fname)
        if _png:
            _prev = base64.b64encode(_png).decode("ascii")
    except Exception:
        _prev = ""
    return {"status": "ok", "filename": fname, "src_path": full, "preview": _prev}

@app.post("/api/part/print")
async def part_print(data: Dict[str, Any]):
    """Роут: запуск печати детали на выбранном принтере."""
    printer_id = str(data.get("printer_id", ""))
    fname = os.path.basename(str(data.get("gcode_file", "")))
    _part = str(data.get("part_name", "") or "")
    if not printer_id or not fname:
        return {"status": "error"}
    fp = _staging_path(fname, _part or None)
    if not fp:
        return {"status": "error", "reason": "file not found"}
    with lock_pr:
        p = conn_pr.execute("SELECT * FROM printers WHERE id=?", (printer_id,)).fetchone()
        if not p: return {"status": "error"}
    # Alpha 2.741: удержание принтера — отказ ДО compat/хуков/print_source (никаких побочных
    # эффектов ради заведомого отказа). Атомарная проверка повторится в begin_direct/adopt ниже.
    _hb = _hold_block(printer_id)
    if _hb:
        return _hb if data.get("_from_queue") else JSONResponse(_hb, status_code=409)
    ptype, pip, pport, ptoken = p["type"], p["ip"], p["port"], p["token"]
    _ams_slot = data.get("ams_slot", None)
    _print_opts = data.get("print_opts", None)   # Alpha 2.687: опции запуска (только Bambu, whitelist)
    try:
        # 2.769: блокирующее чтение — вне event loop (см. _do_project2_file_print).
        fdata = await asyncio.to_thread(lambda: open(fp, "rb").read())
    except Exception:
        return {"status": "error"}
    # Защита: проверяем совместимость нарезки с принтером (модель из файла + число сопел) — для Bambu
    if ptype == "bambu" and not data.get("force"):
        ok, reason = _check_file_compatible(fdata, printer_id, fname)
        if not ok:
            return {"status": "incompatible", "reason": reason}
    #  08.10.2026 (обход фермы, R-008): уведомления склада («впритык», «катушка заменена») печать не
    #  останавливают — при прямом запуске они возвращаются полем notes, как у «Загрузить» (print_path).
    _adv = []
    if not data.get("force") and not data.get("skip_filament"):
        #  16.10.2026 (R-148, R-151): план подачи и хуки модулей — в потоке, как у print_path.
        _plan = await asyncio.to_thread(_launch_feed_plan, printer_id, ptype, _ams_slot, fdata, _print_opts)
        _blk = await asyncio.to_thread(lambda: _run_pre_print_hooks(printer_id, fdata, _ams_slot, fname,
                                                                    advice_out=_adv, plan=_plan))
        if _blk:
            return _blk
    _src = str(data.get("source", "")).lower()
    print_source[printer_id] = _src
    if _src == "plan" and _part:
        plan_part[printer_id] = _part
    else:
        plan_part.pop(printer_id, None)
    # Alpha 2.728: единый менеджер фоновой отправки (reservation + панель).
    _send = _mk_file_send(ptype, pip, pport, ptoken, printer_id, fname, fdata, _ams_slot, _print_opts)
    if data.get("_from_queue"):
        # staggered-очередь: адоптируем свою reservation (или берём свежую) и выполняем СИНХРОННО в потоке
        # очереди (run_tracked) — возвращаем результат отправки для durable-статуса; тайминг очереди не меняется.
        #  16.10.2026 (R-117): у строки очереди ожидания — свой слушатель исхода: если принтер принял
        #  файл, но печать так и не началась (сторож отправок, start_not_confirmed), строка уходит
        #  «требует внимания». Без него строка закрывалась «запущено», а печати не было.
        _on_res = _qw_start_unconfirmed(data.get("_qw_id")) if data.get("_qw_id") else None
        _r, _jid = await asyncio.get_running_loop().run_in_executor(
            None, _send_mgr.begin_or_adopt_tracked, printer_id, p["name"], fname, "queue", _send, _on_res, data.get("_send_job_id"))
        return _r or {"status": "ok"}
    ok, job_id, reason = _send_mgr.begin_direct(printer_id, p["name"], fname, "task", _send)
    _notes = [dict(a, printer_id=str(printer_id), printer_name=str(p["name"] or printer_id)) for a in _adv]
    return _send_accept_response(ok, job_id, reason, printer_id, ({"notes": _notes} if _notes else None))

def _c1_load_plate_compat(pid, p, data):
    """C1 (Alpha 2.728): СИНХРОННО загрузить 3mf (локальная копия → FTP-скачивание с принтера), определить
    плиту (param) и проверить совместимость нарезки. → (data3mf|None, plate_path, incompatible_response|None).
    Compat пропускается при data.force. Вынесено из _bambu_start_print, чтобы p_cmd делал проверку ДО
    reservation/job и возвращал прежний confirm-required ответ (никаких команд принтеру до подтверждения)."""
    _val = data.val.lstrip("/")
    _pp = "Metadata/plate_1.gcode"
    _data3mf = None
    # 1) пробуем локальную копию
    try:
        _lp = os.path.join(TEMP_FILES_DIR, os.path.basename(_val))
        if os.path.exists(_lp):
            with open(_lp, "rb") as _f: _data3mf = _f.read()
    except Exception:
        log.debug("[_c1_load_plate_compat] exception suppressed: %s", _exc_brief())
    # 2) если нет — скачиваем с принтера по FTP
    if _data3mf is None:
        _flk = _ftp_lock(p["ip"]); _flk.acquire()
        _ftp = None
        try:
            _ftp = ImplicitFTP_TLS()
            _ftp.connect(p["ip"], 990, timeout=20.0)
            _ftp.login("bblp", p["token"])
            _ftp.prot_p()
            _ftp.set_pasv(True)
            _buf = io.BytesIO()
            _ftp.retrbinary(f"RETR /{_val}", _buf.write)
            _ftp.quit()
            _data3mf = _buf.getvalue()
            log.debug(f"[BAMBU] Structure downloaded from printer: {_val} ({len(_data3mf)} bytes)")
        except Exception as _e:
            log.warning(f"[BAMBU] Failed to download {_val} to read structure: {_e}")
        finally:
            # Закрыть сокет на любом исходе (после ошибки — без QUIT), замок — последним.
            if _ftp is not None:
                try: _ftp.close()
                except Exception: pass
            _flk.release()
    # 3) читаем путь к пластине внутри 3mf
    if _data3mf:
        try:
            with zipfile.ZipFile(io.BytesIO(_data3mf)) as _z:
                _names = _z.namelist()
                _gc = [n for n in _names if n.endswith(".gcode")]
                _pl = [n for n in _gc if "plate_" in n.lower()]
                if _pl: _pp = sorted(_pl)[0]
                elif _gc: _pp = _gc[0]
                _has_md5 = any(n.endswith(".gcode.md5") for n in _names)
                _has_plate_json = any("plate_" in n and n.endswith(".json") for n in _names)
                log.debug(f"[BAMBU] gcode inside file: {_gc} -> param={_pp}")
                log.debug(f"[BAMBU] 3mf structure: {len(_names)} files total, md5={_has_md5}, plate_json={_has_plate_json}, metadata={[n for n in _names if n.startswith('Metadata/')][:12]}")
        except zipfile.BadZipFile:
            log.warning(f"[BAMBU] {_val} not ZIP/3mf - printing as is")
        except Exception as _e:
            log.debug(f"[BAMBU] failed to read 3mf structure {_val}: {_e}")
    # Защита: проверяем совместимость нарезки с принтером (при force — пропускаем)
    if _data3mf and not data.force:
        _ok, _reason = _check_file_compatible(_data3mf, pid, _val)
        if not _ok:
            log.debug(f"[BAMBU COMPAT] Block: {_reason}")
            return (_data3mf, _pp, {"status": "incompatible", "reason": _reason})
    return (_data3mf, _pp, None)

def _bambu_start_print(c, pid, p, data, _preload=None):
    """Запуск печати .3mf/.gcode на Bambu по MQTT (файл уже на принтере — C1).
    Поведение совпадает с прежним инлайн-кодом: для нового поколения команда шлётся с обоими кандидатами
    имени (как официальное приложение) — принтер выберет подходящее. Возвращает {"status":"ok"} либо
    {"status":"incompatible", "reason":...}. Alpha 2.728: _preload=(data3mf, plate_path) — загрузка+плита+compat
    уже выполнены СИНХРОННО в p_cmd (C1 precheck) → здесь только публикуем команду (без повторной загрузки)."""
    _val = data.val.lstrip("/")
    if _preload is not None:
        _data3mf, _pp = _preload
    else:
        _data3mf, _pp, _blk = _c1_load_plate_compat(pid, p, data)
        if _blk:
            return _blk
    # Слот AMS выбирает пользователь в интерфейсе (дропдаун ячейки). Alpha 2.723: формат источника —
    # единой точкой _bambu_resolve_ams (подтверждён перехватом Studio). На ЭТОМ пути null исторически
    # означает «внешняя катушка» (авто-маппинга из 3mf здесь никогда не было) → передаём явный -1.
    _slot_bsp = int(data.ams_slot) if (data.ams_slot is not None and data.ams_slot >= 0) else -1
    if _slot_bsp == -1:
        #  16.10.2026 (R-137): внешняя катушка — по самому файлу, как в Bambu Studio (FROM_SDCARD_VIEW
        #  берёт filament_map из файла): файл уже скачан для проверки совместимости (_data3mf). У
        #  двухсопельного сторона — по соплу в файле; не известна или файла нет — отказ ДО команды,
        #  а не «правая по умолчанию». Односопельный с однофиламентным файлом — прежние [-1]/[{255,0}].
        _ext_c1 = _bambu_ext_choice(pid, _data3mf, explicit=False)
        if not _ext_c1.get("ok"):
            log.info("[BAMBU AMS] %s: файл на принтере — внешняя катушка не выбрана: %s", pid, _ext_c1.get("why"))
            return {"status": "error", "reason": _ext_c1.get("why")}
        _use_ams, _ams_map, _ams_map2 = False, list(_ext_c1["v0"]), [dict(x) for x in _ext_c1["v1"]]
    else:
        _use_ams, _ams_map, _ams_map2 = _bambu_resolve_ams(pid, _slot_bsp, None)
    _subtask = os.path.splitext(os.path.basename(_val))[0]
    _bn = os.path.basename(_val)
    # Формат пути выбираем тем же правилом, что и при загрузке (двухсопельные = emmc,
    # односопельные = sdcard; ручной выбор/выученная схема — в приоритете).
    _print_cmds = []
    _sch0 = _bambu_scheme_order(pid)[0]
    if _sch0 == "emmc":
        _name_with = f"{_subtask}.gcode.3mf"   # "AA.gcode" -> "AA.gcode.gcode.3mf"
        _candidates = [_bn]                      # имя как есть на принтере
        if _name_with != _bn:
            _candidates.append(_name_with)       # + вариант с добавленным .gcode
        for _cand in _candidates:
            _print_cmds.append((f"brtc://emmc/{_cand}", _subtask))
    elif _sch0 == "ftp":
        _print_cmds.append((f"ftp:///{_bn}", _subtask))
    elif _sch0 == "mnt":
        _print_cmds.append((f"file:///mnt/sdcard/{_val}", _subtask))
    else:
        _print_cmds.append((f"file:///sdcard/{_val}", _subtask))
    #  2.978: ВТОРАЯ команда печати уже печатающему принтеру не уходит никогда. При схеме
    #  emmc кандидатов имени два («AA.gcode» и «AA.gcode.gcode.3mf»), и раньше обе команды
    #  публиковались подряд, без чтения ответа прошивки: первую H2D принимал и начинал
    #  готовиться, вторая попадала в уже стартующую печать — «Device is busy and cannot start
    #  new task [0500-4004]». Та же дисциплина, что на пути отправки файла (_bambu_send_project):
    #  ждём ответ прошивки, даём выдержку и шлём следующий вариант, только если принтер
    #  доказанно остался в покое.
    _topic = f"device/{bambu_serials.get(pid, pid)}/request"
    #  2.988: та же предполётная проверка, что и на пути отправки файла.
    _bambu_last_refusal.pop(pid, None)   # 16.10.2026 (R-114): причина — только этого запуска
    _busy0 = _bambu_busy_before_start(pid)
    if _busy0:
        log.warning("[BAMBU] %s: печать не запущена — %s", pid, _busy0)
        return {"status": "error", "reason": _bambu_refusal_reason(pid) or _busy0}
    _bambu_stage_mark(pid)          # 16.10.2026 (R-138): стадия ДО первой команды — база признака старта
    for _i, (_u, _sub) in enumerate(_print_cmds):
        if _i and _bambu_busy_now(pid):
            log.info("[BAMBU] %s: принтер занят — второй вариант имени не отправляем", pid)
            break
        _s0 = p_states.get(pid, {})
        try: _b_pe = int(_s0.get("print_error", 0) or 0)
        except Exception: _b_pe = 0
        _b_mce = str(_s0.get("mc_err", "0") or "0")
        try: _b_hms = int(_s0.get("hms_n", 0) or 0)
        except Exception: _b_hms = 0
        # Alpha 2.723: тот же подтверждённый формат полей, что и в _send_file_to_printer (без legacy flow_cal/vibration_cal).
        pl = {"print": {"sequence_id": "0", "command": "project_file", "param": _pp, "subtask_name": _sub, "project_id": "0", "profile_id": "0", "task_id": "0", "subtask_id": "0", "url": _u, "md5": "", "timelapse": False, "bed_type": "auto", "bed_leveling": True, "auto_bed_leveling": 1, "flow_cali": False, "extrude_cali_flag": 0, "extrude_cali_manual_mode": 0, "vibration_cali": False, "layer_inspect": False, "ams_mapping": _bambu_wire_mapping(_ams_map), "ams_mapping2": _ams_map2, "use_ams": _use_ams}}
        try:
            log.info("[BAMBU_PAYLOAD] printer=%s scheme=start_print payload=%s", pid, json.dumps(_sniff_sanitize(pl), ensure_ascii=False))
        except Exception:
            log.debug("[BAMBU_PAYLOAD] emit suppressed: %s", _exc_brief())
        _t_sent = time.monotonic()
        if not _bambu_publish(pid, _topic, json.dumps(pl)):
            log.debug(f"[BAMBU] {pid}: команда печати не отправлена (нет связи по MQTT)")
            return {"status": "error", "reason": "no connection to the printer"}
        log.debug(f"[BAMBU] start_print URL={_u} | param={_pp} | use_ams={_use_ams} | nozzle_count={p_states.get(pid, {}).get('nozzle_count', 1)}")
        _bambu_request_report(pid)   # 2.988: решаем по свежему состоянию, а не по плановому отчёту
        if _i + 1 >= len(_print_cmds):
            break                      # других вариантов имени нет — ждать нечего
        _res = _bambu_print_outcome(pid, _b_pe, _b_mce, _b_hms, since=_t_sent, first=(_i == 0))
        #  16.10.2026 (R-138, проверка пакета): 0500-4004 в ответ на ПЕРВУЮ команду — принтер занят своим
        #  заданием, печать не пошла (как в _bambu_send_project).
        if _res == "busy":
            _bambu_first_cmd_busy(pid, _b_pe, pe_now=_bstart.BUSY_CODE)
            return {"status": "error", "reason": _bambu_refusal_reason(pid) or "the printer is busy with another task"}
        if _res in ("ok", "timeout"):
            break
        if _bambu_wait_started(pid, 15.0):
            if _i == 0 and _bambu_first_cmd_busy(pid, _b_pe):
                return {"status": "error", "reason": _bambu_refusal_reason(pid) or "the printer is busy with another task"}
            log.info("[BAMBU] %s: принтер вышел из покоя — второй вариант имени не отправляем", pid)
            break
        log.info("[BAMBU] %s: имя '%s' принтер не принял (остался в покое), пробуем следующий вариант", pid, _u)
        try: _bambu_publish(pid, _topic, json.dumps({"print": {"sequence_id": "0", "command": "clean_print_error", "param": ""}}), attempts=2)
        except Exception:
            log.debug("[BAMBU start_print] exception suppressed: %s", _exc_brief())
        time.sleep(1.5)
    log.debug(f"[BAMBU AMS] ams_mapping={_ams_map} | selected slot={getattr(data, 'ams_slot', None)} | printer trays={p_states.get(pid, {}).get('ams_trays', [])}")
    return {"status": "ok"}

def _creality_ws_send(ip, obj, port=9999, timeout=6.0):
    """Минимальный WebSocket-клиент (RFC 6455, без внешних зависимостей) для
    родного управляющего сервиса Creality K1/K2/K2 Plus на :9999. Открывает
    соединение, шлёт одну JSON-команду вида {"method":"set","params":{...}} и
    закрывает его. Возвращает True при успешной отправке. Подмешиваем сабпротокол
    'wsslicer' для совместимости с официальным веб-клиентом принтера."""
    payload = json.dumps(obj, separators=(",", ":")).encode("utf-8")
    key = base64.b64encode(os.urandom(16)).decode()
    handshake = (
        "GET / HTTP/1.1\r\n"
        f"Host: {ip}:{port}\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        f"Sec-WebSocket-Key: {key}\r\n"
        "Sec-WebSocket-Protocol: wsslicer\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "\r\n"
    ).encode()
    s = None
    try:
        s = socket.create_connection((ip, port), timeout=timeout)
        s.settimeout(timeout)
        s.sendall(handshake)
        resp = b""
        while b"\r\n\r\n" not in resp:
            chunk = s.recv(1024)
            if not chunk:
                break
            resp += chunk
            if len(resp) > 65536:
                break
        first_line = resp.split(b"\r\n", 1)[0] if resp else b""
        if b" 101 " not in first_line:
            log.debug(f"[CREALITY WS] {ip}:{port} - no 101 Switching Protocols: {first_line!r}")
            return False
        mask = os.urandom(4)
        n = len(payload)
        frame = bytearray([0x81])
        if n < 126:
            frame.append(0x80 | n)
        elif n < 65536:
            frame.append(0x80 | 126); frame += struct.pack(">H", n)
        else:
            frame.append(0x80 | 127); frame += struct.pack(">Q", n)
        frame += mask
        frame += bytes(b ^ mask[i % 4] for i, b in enumerate(payload))
        s.sendall(bytes(frame))
        log.debug(f"[CREALITY WS] {ip}:{port} <- {obj}")
        try:
            s.recv(2048)   # дать кадру уйти и принять любой ответ (не обязательно)
        except Exception:
            log.debug("[_creality_ws_send] exception suppressed: %s", _exc_brief())
        return True
    except Exception as e:
        log.warning(f"[CREALITY WS] {ip}:{port} error: {type(e).__name__}: {e}")
        return False
    finally:
        try:
            if s: s.close()
        except Exception:
            log.debug("[_creality_ws_send] exception suppressed: %s", _exc_brief())

# ============================================================================
#  ОЧЕРЕДЬ ПОЭТАПНОГО ЗАПУСКА ПЕЧАТИ.
#  Одновременный старт 10-20 принтеров даёт скачок нагрузки на электросеть
#  (прогрев столов/сопел). Очередь разносит старты во времени на заданный
#  пользователем интервал. Живёт на СЕРВЕРЕ и продолжает стартовать задания,
#  даже если вкладка интерфейса закрыта/обновлена. Это планировщик отложенного
#  запуска: новой логики печати нет — каждый элемент в свой срок зовёт ту же
#  функцию печати, что и обычная кнопка (part_print / _do_project2_file_print).
# ----------------------------------------------------------------------------
print_queue = []                      # список ожидающих запусков (dict)
print_queue_lock = threading.Lock()
_print_queue_seq = 0                  # счётчик для уникальных id элементов
# Alpha 2.771 (Q-1): отправки, которые воркер УЖЕ извлёк из print_queue и прямо сейчас
# диспетчеризует. Защищается ТЕМ ЖЕ print_queue_lock и наполняется В ТОЙ ЖЕ критической секции,
# что и удаление элемента из очереди — поэтому между «элемент ушёл из очереди» и «элемент в
# диспетчеризации» нет ни одного окна, в котором watchdog мог бы счесть его брошенным.
_queue_dispatching_send_job_ids = set()

def _queue_active_send_job_ids():
    """Снимок send_job_id, за которые очередь ЕЩЁ отвечает: ждущие в print_queue + диспетчеризуемые.
    ПОРЯДОК БЛОКИРОВОК: print_queue_lock берётся и ПОЛНОСТЬЮ отпускается здесь, наружу уходит
    неизменяемое множество. Менеджер отправок получает готовый набор и только после этого берёт
    свой _lock — обратный порядок (_send_mgr._lock → print_queue_lock) не возникает нигде."""
    with print_queue_lock:
        ids = {q.get("send_job_id") for q in print_queue if q.get("send_job_id")}
        ids |= set(_queue_dispatching_send_job_ids)
    return frozenset(ids)

def _print_queue_public():
    """Снимок очереди для интерфейса: id, принтер, имя и сколько секунд до старта (eta)."""
    now = time.time()
    with print_queue_lock:
        items = sorted(print_queue, key=lambda q: q["due_ts"])
        return [{"id": q["id"], "printer_id": q["printer_id"], "printer_name": q.get("printer_name") or q["printer_id"],
                 "eta": max(0, int(round(q["due_ts"] - now)))} for q in items]

async def _start_queued_print(q):
    """Запустить один отложенный элемент очереди тем же механизмом, что и обычная печать.
    ФАЗА 2 (Alpha 2.624): возвращает (ok, err, status) — воркер зеркалит это в статус
    print_launch_queue, а по status видно, дошло ли дело до принтера (16.09.2026).
    Сам механизм запуска и тайминг НЕ изменены."""
    try:
        if q.get("flow") == "project":
            r = await _do_project2_file_print(q.get("project_id"), q.get("file_id"), q.get("printer_id"), ams_slot=q.get("ams_slot"), skip_filament=True,
                                              print_opts=q.get("print_opts"),   # Alpha 2.723: опции из элемента очереди (старые элементы без ключа → None → дефолты)
                                              _from_queue=True, _send_job_id=q.get("send_job_id"))   # Alpha 2.728: адопт reservation очереди (старые элементы без ключа → свежий reserve)
        else:
            r = await part_print({"printer_id": q.get("printer_id"), "gcode_file": q.get("gcode_file"),
                                  "source": q.get("source") or "quick", "part_name": q.get("part_name"), "ams_slot": q.get("ams_slot"),
                                  "skip_filament": bool(q.get("skip_filament")),   # Alpha 2.850: решение владельца из окна «Материал закончился»
                                  "print_opts": q.get("print_opts"),   # Alpha 2.723: то же для quick-потока
                                  "_qw_id": q.get("qw_id") or "",      # 16.10.2026 (R-117): строка очереди ожидания
                                  "_from_queue": True, "_send_job_id": q.get("send_job_id")})   # Alpha 2.728: адопт reservation очереди
        # Alpha 2.848 — БЕЛЫЙ список вместо чёрного. Прежде успехом считалось всё, кроме 'error' и
        # 'incompatible', поэтому ЛЮБОЙ блокирующий ответ хука печати проходил как успешный запуск.
        # Так 17.08.2026 отказ склада 'low_filament' записался в журнал как «start X11: ok», в очередь —
        # как «отправлено», reservation не вернулась (worker считал отправку состоявшейся) и через
        # секунду её снял watchdog: владелец увидел «orphan queue reservation released» вместо
        # «не хватает материала», а принтер не печатал. Успех подтверждают ОБА потока очереди
        # (quick и project) одинаково — status == 'ok'; всё остальное (error, incompatible,
        # low_filament, printer_held, printer_send_busy и любой будущий отказ) = неудача, после
        # которой worker возвращает reservation и пишет причину в durable-строку.
        ok = isinstance(r, dict) and str(r.get("status") or "").strip().lower() == "ok"
        err = "" if ok else str((isinstance(r, dict) and (r.get("reason") or r.get("status"))) or "fail")
        #  16.09.2026: отдаём ещё и СТАТУС ответа. По нему видно, дошло ли дело до принтера:
        #  'incompatible' и 'low_filament' — отказ ДО отправки, и строку очереди ожидания можно
        #  честно вернуть владельцу; по тексту причины эти случаи не различить.
        _status = str((isinstance(r, dict) and r.get("status")) or "").strip().lower()
        #  16.10.2026 (R-117): отправка сама сказала, что ничего не ушло ('sent': False — нет связи, файл не
        #  лёг на принтер, принтер отверг команду и остался в покое). По тексту причины это не различить:
        #  тексты у марок свои и меняются, поэтому — отдельным признаком.
        if not ok and isinstance(r, dict) and r.get("sent") is False:
            _status = "not_sent"
        log.info("[PRINT-QUEUE] start %s (%s): %s" % (q.get("printer_name") or q.get("printer_id"), q.get("printer_id"),
                 "ok" if ok else (err or "fail")))
        return ok, err, _status
    except Exception:
        _e = _exc_brief()
        log.warning("[PRINT-QUEUE] start failed on %s: %s" % (q.get("printer_id"), _e))
        return False, _e, "exception"

def _plq_set_status(durable_id, status, last_error=None, inc_attempts=False, only_if=None):
    """ФАЗА 2 (Alpha 2.624) — зеркалирование статуса элемента в print_launch_queue.
    Воркер ведёт запуск из ПАМЯТИ (print_queue) как и раньше; строка БД — только ОТРАЖЕНИЕ статуса
    (pending→launching→sent/failed; отмена → canceled) для будущего восстановления. Best-effort:
    ошибка обновления НЕ влияет на печать (пишем в лог). last_error=None → колонку не трогаем;
    '' → очистить; строка → записать. only_if — обновлять лишь если текущий статус равен ему (защита от гонок).
    durable_id пустой (напр. запись фазы 1 не удалась) — тихо пропускаем.
    ЭТО НЕ восстановление: старые 'pending'-строки на старте НЕ обрабатываются (см. следующие Alpha)."""
    if not durable_id:
        return
    try:
        ts = time.time()
        sets = ["status=?", "updated_at=?"]
        vals = [str(status), ts]
        if inc_attempts:
            sets.append("attempts=attempts+1")
        if last_error is not None:
            sets.append("last_error=?"); vals.append(str(last_error)[:500])
        where = "id=?"; vals.append(str(durable_id))
        if only_if is not None:
            where += " AND status=?"; vals.append(str(only_if))
        with lock_pr:
            conn_pr.execute("UPDATE print_launch_queue SET %s WHERE %s" % (", ".join(sets), where), vals)
            conn_pr.commit()
    except Exception:
        log.error("[PRINT-QUEUE] статус БД '%s' для %s не обновлён: %s (печать не затронута)" % (status, durable_id, _exc_brief()))

#  ── 16.09.2026: строка очереди ОЖИДАНИЯ живёт до ответа очереди запусков (слово владельца «да») ──
#  Раньше строка помечалась «запущено» в момент постановки в очередь. Если дальше принтер отказывал,
#  склад блокировал запуск или запуск отменяли, строка уходила из списка молча — файл приходилось
#  добавлять заново, и заметить это было трудно. Теперь она держится в 'launching', а исход
#  проставляется здесь. Помощники живут ВНУТРИ блока очереди намеренно: этот блок исполняется
#  дословно в tools/test_queue_reservation_release.py, и функция снаружи оставила бы его без имени.
#
#  ДОКАЗАННО НЕ ОТПРАВЛЯЛИ — то же правило, что у точечного запуска (_definite): отказ произошёл до
#  передачи файла. Такую строку возвращаем в ОЖИДАНИЕ с причиной. Всё остальное — 'attention'
#  («проверьте принтер»): команда могла уйти, и автоматический возврат дал бы вторую деталь.
#
#  16.10.2026 (R-117): главный признак — 'sent': False в ответе отправки (статус 'not_sent', см.
#  _start_queued_print). Список текстов ниже остался запасным: им отвечают ранние отказы самого
#  запуска (удержание, занятость, нет файла). «already running» из списка убран: так менеджер
#  отправок отвечает и тогда, когда задание уже исполняет кто-то другой, — «не отправлено» это не
#  доказывает, и строка идёт «требует внимания».
_QW_SENT_NOT_STARTED = ("printer_send_busy", "printer_held", "printer_busy", "no printer", "file not found",
                        "file missing on disk", "printer not found", "read failed",
                        "queue launch not started")


def _qw_finish(qw_id, state, note):
    """Проставить строке очереди ожидания исход запуска. Fail-open: ошибка записи на печать не влияет.
    Пишем ТОЛЬКО строку, которая всё ещё ждёт исхода ('launching'): чужое состояние (владелец убрал
    строку, программа перезапустилась) не перетираем."""
    if not qw_id:
        return
    try:
        with lock_pr:
            #  16.09.2026: исход принимается и для строки, помеченной «требует внимания» —
            #  перезапуск программы помечает так строку, чей запуск потом продолжили из окна
            #  восстановления, и её настоящий исход обязан её закрыть.
            conn_pr.execute("UPDATE queue_wait SET state=?, note=?, updated_at=? "
                            "WHERE id=? AND state IN ('launching','attention')",
                            (str(state), str(note or "")[:300], time.time(), str(qw_id)))
            conn_pr.commit()
    except Exception:
        log.error("[QUEUE-WAIT] исход строки %s не записан: %s (печать не затронута)"
                  % (qw_id, _exc_brief()))


def _qw_launch_outcome(q, ok, err, status=""):
    """Исход запуска элемента очереди -> состояние строки ожидания (см. правило выше)."""
    qw = str((q or {}).get("qw_id") or "")
    if not qw:
        return
    name = str((q or {}).get("printer_name") or (q or {}).get("printer_id") or "")
    if ok:
        _qw_auto_ok(qw)
        _qw_auto_inflight.discard(qw)
        _qw_finish(qw, "done", "запущено на " + name)
        return
    reason = str(err or "").strip()
    st = str(status or "").strip().lower()
    if st in ("incompatible", "low_filament", "not_sent") or reason in _QW_SENT_NOT_STARTED:
        #  16.10.2026 (R-117): пометка — КОДОМ «not_started:<причина>»: строку читают русский и английский
        #  интерфейс, и причину показывают словами (queueNoteText), а не сырым кодом.
        _qw_finish(qw, "waiting", "not_started:" + (reason or (st if st and st != "not_sent" else "")))
        #  16.09.2026: неудача засчитывается здесь, по НАСТОЯЩЕМУ исходу отправки — и ТОЛЬКО
        #  для запусков, которые начал АВТОМАТ. Ручные попытки владельца не считаем: он
        #  нажимает сам и сам видит причину.
        if qw in _qw_auto_inflight:
            _qw_auto_inflight.discard(qw)
            _qw_auto_bump(qw, reason)
        return
    _qw_auto_inflight.discard(qw)
    #  16.10.2026 (R-117, разбор пакета): и эта пометка — КОДОМ «interrupted:<причина>»: причину вроде
    #  «already running» интерфейс показывает словами на языке владельца (queueNoteText).
    _qw_finish(qw, "attention", "interrupted:" + reason)


def _qw_start_unconfirmed(qw_id):
    """Слушатель исхода отправки для строки очереди ожидания. 16.10.2026 (R-117).

    Принтер принял файл и команду, а печать не началась (сторож отправок 45 секунд видел устойчивый
    покой — start_not_confirmed). Строка к этому времени уже закрыта «запущено», и владелец её
    больше не видел, хотя печати нет. Теперь она возвращается «требует внимания» с причиной. Сама
    она НЕ перезапускается: принтер мог ждать нажатия на своём экране, и повтор дал бы вторую
    деталь, — решает человек. Немедленные ошибки отправки сюда тоже приходят, но их исход уже
    записал воркер очереди (_qw_launch_outcome), поэтому здесь они не трогаются."""
    qw = str(qw_id or "")

    def _cb(result):
        if not qw or not isinstance(result, dict) or result.get("reason") != "start_not_confirmed":
            return
        try:
            with lock_pr:
                conn_pr.execute("UPDATE queue_wait SET state='attention', note=?, updated_at=? "
                                "WHERE id=? AND state='done'", ("start_not_confirmed", time.time(), qw))
                conn_pr.commit()
            log.warning("[QUEUE-WAIT] строка %s: принтер принял файл, но печать не началась — "
                        "строка требует внимания" % qw)
        except Exception:
            log.error("[QUEUE-WAIT] строку %s не удалось пометить «требует внимания»: %s" % (qw, _exc_brief()))
    return _cb


def _qw_recover_launching():
    """После перезапуска программы: строки, оставшиеся в 'launching', исход которых записать не
    успели. В ожидание их НЕ возвращаем — команда могла уйти на принтер, и повторный запуск дал бы
    вторую деталь. Помечаем «требует внимания», решает владелец."""
    keep = set()
    try:
        #  Запуск, который очередь запусков ещё намерена выполнить (ждёт подтверждения в окне
        #  восстановления или стоит в очереди), строку не трогает: её закроет настоящий исход.
        with lock_pr:
            rows = conn_pr.execute("SELECT payload FROM print_launch_queue WHERE status IN "
                                   "('pending','recovery_hold','launching')").fetchall()
        for r in rows:
            try:
                it = _jsonmod.loads(r["payload"] or "{}")
            except Exception:
                continue
            if isinstance(it, dict) and it.get("qw_id"):
                keep.add(str(it["qw_id"]))
    except Exception:
        log.debug("[QUEUE-WAIT] незакрытые запуски не прочитаны: %s", _exc_brief())
    try:
        _sql = ("UPDATE queue_wait SET state='attention', note=?, updated_at=? WHERE state='launching'")
        _args = ["запуск прерван перезапуском программы — проверьте принтер", time.time()]
        if keep:
            _sql += " AND id NOT IN (%s)" % ",".join("?" * len(keep))
            _args += sorted(keep)
        with lock_pr:
            cur = conn_pr.execute(_sql, _args)
            conn_pr.commit()
        n = cur.rowcount if (cur.rowcount and cur.rowcount > 0) else 0
        if n:
            log.info("[QUEUE-WAIT] после перезапуска строк требует внимания: %d" % n)
    except Exception:
        log.error("[QUEUE-WAIT] разбор прерванных строк не удался: %s" % _exc_brief())


_print_queue_recovered = False   # ФАЗА 4 (Alpha 2.626): восстановление очереди из БД делаем ОДИН раз за процесс
_PLQ_RECOVERY_GRACE = 25.0       # Alpha 2.629: фора после «Продолжить» — прошедшие due_ts не стартуют мгновенно (принтеры успевают подключиться)
_sending_now = None              # Alpha 2.630: пока воркер ОТПРАВЛЯЕТ queued-печать на принтер — {printer_id, printer_name, durable_id, job_ref, since}; иначе None. Только индикатор для интерфейса (staggered-загрузку идёт на сервере, клиентский fetch её не видит).

def _recovered_launch_ok(q):
    """ФАЗА 4 (Alpha 2.626): доп. проверки ПЕРЕД стартом ВОССТАНОВЛЕННОГО элемента (защита от двойной печати).
    True — безопасно запускать; False — НЕ запускать (внутри уже помечено 'recovery_attention' либо строка уже
    не наша). Для ОБЫЧНЫХ (не recovered) элементов НЕ вызывается — их поведение не меняется."""
    did = q.get("durable_id")
    if not did:
        return True
    try:
        with lock_pr:
            row = conn_pr.execute("SELECT status, recovery_eligible FROM print_launch_queue WHERE id=?", (str(did),)).fetchone()
    except Exception:
        log.error("[PRINT-QUEUE] recovery precheck read failed for %s: %s (не запускаем)" % (did, _exc_brief()))
        return False
    if not row or row["status"] != "pending" or int(row["recovery_eligible"] or 0) != 1:
        return False   # отменена/уже не pending/не eligible — тихо пропускаем (не наш запуск)
    # Живой статус принтера: запускаем ТОЛЬКО если он ЯВНО свободен (IDLE). Печатает/PREPARE/пауза/офлайн/
    # неизвестно/только что закончил — риск дубля (мог уже печатать этот файл) → «требует внимания», НЕ запускаем.
    st = str(((p_states.get(q.get("printer_id")) or {}).get("status")) or "").upper()
    if st == "IDLE":
        return True
    _plq_set_status(did, "recovery_attention",
                    last_error=("recovery skipped: printer not idle (%s) — verify before re-launch" % (st or "unknown")),
                    only_if="pending")
    return False

def _print_queue_recover():
    """ФАЗА 5 / Alpha E (Alpha 2.629) — восстановление БОЛЬШЕ НЕ авто-запускает, а УДЕРЖИВАЕТ до подтверждения.
    Берём ТОЛЬКО status='pending' AND recovery_eligible=1 (легаси/stale/чужие НЕ трогаем — см. карантин фазы 3)
    и переводим их в 'recovery_hold' (в in-memory print_queue НЕ кладём → воркер их не видит → НИЧЕГО не стартует).
    'launching'+eligible от прошлого краха → 'recovery_attention' (как и раньше, без слепого перезапуска).
    Фронтенд по GET /api/print-queue/recovery-notice покажет модалку; пользователь решает:
    «Продолжить» (POST /recovery/continue: hold→pending + инъекция в очередь, запуск тем же воркером с IDLE-сверкой)
    или «Отменить» (POST /recovery/cancel: hold→canceled). Идемпотентно за процесс. Только UPDATE своей таблицы
    (без DROP/DELETE/ALTER/миграций; строки не удаляем); печать/тайминг не трогаем."""
    global _print_queue_recovered
    if _print_queue_recovered:
        return
    _print_queue_recovered = True
    now = time.time()
    n_hold = n_attention = 0
    try:
        with lock_pr:
            # Alpha 2.772 (A-4): две связанные записи + один commit. Внутренний except делает
            # rollback ПОД ТЕМ ЖЕ lock и ДО его освобождения — иначе незавершённая транзакция
            # общего соединения досталась бы следующему коду и была бы зафиксирована ЕГО commit'ом
            # (получилось бы «половина восстановления сохранилась»). Исходное исключение
            # перевыбрасывается: политика ошибки во внешнем except остаётся прежней.
            try:
                cur = conn_pr.execute("UPDATE print_launch_queue SET status='recovery_attention', updated_at=?, "
                                      "last_error='launch interrupted by restart — verify printer before re-launch' "
                                      "WHERE status='launching' AND COALESCE(recovery_eligible,0)=1", (now,))
                n_attention = cur.rowcount if (cur.rowcount and cur.rowcount > 0) else 0
                # eligible-pending → УДЕРЖАНИЕ (recovery_hold): НЕ авто-запуск, ждём решения пользователя.
                cur2 = conn_pr.execute("UPDATE print_launch_queue SET status='recovery_hold', updated_at=? "
                                       "WHERE status='pending' AND recovery_eligible=1", (now,))
                n_hold = cur2.rowcount if (cur2.rowcount and cur2.rowcount > 0) else 0
                conn_pr.commit()
            except Exception:
                try:
                    conn_pr.rollback()
                except Exception:
                    log.error("[PRINT-QUEUE] SQLite rollback failed (recovery hold): %s" % _exc_brief())
                raise
    except Exception:
        log.error("[PRINT-QUEUE] recovery hold failed: %s (обычная очередь не затронута)" % _exc_brief())
        return
    if n_hold or n_attention:
        log.info("[PRINT-QUEUE] recovery: удержано до подтверждения=%d, launching→внимание=%d — очередь НЕ запущена (ждём решения пользователя)"
                 % (n_hold, n_attention))

async def _print_queue_worker():
    """Планировщик: раз в секунду стартует НЕ БОЛЕЕ одного подошедшего по времени задания
    (одно за тик — гарантия выдержанного интервала между стартами даже при задержках)."""
    global _sending_now
    while True:
        q = None
        try:
            now = time.time()
            with print_queue_lock:
                ready = [x for x in print_queue if x["due_ts"] <= now]
                if ready:
                    q = min(ready, key=lambda x: x["due_ts"])
                    print_queue.remove(q)
                    # Alpha 2.771: в ТОЙ ЖЕ критической секции помечаем отправку как «диспетчеризуется» —
                    # так между уходом из очереди и началом обработки нет окна для watchdog.
                    if q.get("send_job_id"):
                        _queue_dispatching_send_job_ids.add(q["send_job_id"])
        except Exception:
            log.debug("[PRINT-QUEUE] worker tick error: %s", _exc_brief())
        if q is not None:
            _sjid = q.get("send_job_id")
            _dispatched = False   # True — отправка ДОШЛА до send-worker и принята им; reservation держит менеджер
            _why = ""
            try:
                # ФАЗА 4 (Alpha 2.626): для ВОССТАНОВЛЕННОГО элемента — доп. проверки перед стартом (сверка БД
                # pending+eligible и живого статуса принтера); небезопасно → помечено «внимание» и НЕ запускаем.
                # Для обычных (новых) элементов путь ПРЕЖНИЙ — поведение и тайминг печати не меняются.
                if q.get("recovered") and not _recovered_launch_ok(q):
                    _why = "recovery precheck rejected"   # durable-статус уже выставлен внутри проверки
                    _qw_finish(str(q.get("qw_id") or ""), "attention",
                               "после перезапуска запуск не подтверждён — проверьте принтер")
                else:
                    # ФАЗА 2 (Alpha 2.624): зеркалим статус в print_launch_queue ВОКРУГ запуска.
                    # Источник истины и тайминг — ПРЕЖНИЕ (in-memory print_queue); строка БД — только отражение.
                    _plq_set_status(q.get("durable_id"), "launching", inc_attempts=True)
                    # Alpha 2.630: пометка «сейчас идёт отправка на принтер» — интерфейс покажет статус во время
                    # (долгой) загрузки файла воркером (staggered-путь клиентский fetch не видит). Тайминг/порядок не меняем.
                    _sending_now = {"printer_id": q.get("printer_id"),
                                    "printer_name": q.get("printer_name") or q.get("printer_id"),
                                    "durable_id": q.get("durable_id"),
                                    "job_ref": str(q.get("gcode_file") or q.get("part_name") or ""),
                                    "since": time.time()}
                    try:
                        _ok, _err, _st = await _start_queued_print(q)
                        _dispatched = bool(_ok)
                        if not _ok:
                            _why = str(_err or "launch failed")
                        _plq_set_status(q.get("durable_id"), "sent" if _ok else "failed", last_error=("" if _ok else _err))
                        _qw_launch_outcome(q, _ok, _err, _st)   # 16.09.2026: исход строки очереди ожидания
                    finally:
                        _sending_now = None   # снять индикатор при успехе, ошибке И любом исключении/отмене
            except Exception:
                _why = "worker exception"
                log.error("[PRINT-QUEUE] обработка элемента прервана исключением: %s (очередь продолжает работу)" % _exc_brief())
                _qw_launch_outcome(q, False, "сбой очереди запусков", "exception")
            finally:
                # Alpha 2.771 (Q-1) — КОРЕНЬ ДЕФЕКТА: элемент УЖЕ снят с очереди. Если отправка не была
                # принята send-worker'ом, её reservation обязана вернуться, иначе принтер останется
                # «занят» до перезапуска программы (прежде здесь стоял немой `pass`).
                # Фактическое состояние job разбирает сам cancel_reserved: job терминальный (worker уже
                # сделал release) или worker ещё жив → False и никакого вмешательства. Освободить ЧУЖУЮ
                # reservation невозможно — release идёт только если _resv[printer] == этот job_id.
                if _sjid and not _dispatched:
                    _released = _send_mgr.cancel_reserved(_sjid, "queue launch not started")
                    log.info("[PRINT-QUEUE] запуск не состоялся: printer=%s send_job=%s durable=%s причина=%s reservation_освобождена=%s"
                             % (q.get("printer_id"), _sjid, q.get("durable_id") or "-", _why or "-", _released))
                if _sjid:
                    with print_queue_lock:
                        _queue_dispatching_send_job_ids.discard(_sjid)
        await asyncio.sleep(1.0)

@app.get("/api/print-queue")
def api_print_queue_get():
    """Текущее содержимое очереди поэтапного запуска (для отображения и отсчёта в интерфейсе).
    Alpha 2.630: 'sending' — что воркер отправляет ПРЯМО СЕЙЧАС (или None) для индикатора «Отправка на принтер…»."""
    return {"queue": _print_queue_public(), "sending": _sending_now, "now": time.time()}

#  ============================================================================
#  Alpha 2.920 — ОЧЕРЕДЬ ОЖИДАНИЯ И ПОДБОР ПРИНТЕРА
#
#  ЗАКАЗ ВЛАДЕЛЬЦА (28.08.2026): по правой кнопке на файле — «Добавить в очередь»; программа
#  сама ищет подходящий принтер (свободный, с нужным материалом, которому РАЗРЕШЕНО запускать
#  из очереди) и печатает.
#
#  РЕШЕНИЯ ВЛАДЕЛЬЦА, ЗАФИКСИРОВАННЫЕ ЗДЕСЬ:
#    * первый этап — С ПОДТВЕРЖДЕНИЕМ: сервер только НАХОДИТ принтер и говорит об этом; сам
#      старт делает владелец нажатием. Полный автомат — следующий этап, отдельным решением;
#    * материал файла определить не удалось -> строка ЖДЁТ владельца, ничего не запускается;
#    * хранение в базе разрешено прямо (таблица queue_wait, столбец printers.queue_allowed).
#
#  ЧЕГО ЗДЕСЬ НЕТ НАМЕРЕННО: своего механизма запуска печати. Найденный принтер уходит в
#  СУЩЕСТВУЮЩУЮ очередь запусков (/api/print-queue/enqueue) со всеми её проверками склада,
#  резервированием принтера, интервалом и восстановлением после перезапуска.
#  ============================================================================
def _qw_printer_name(pid):
    """Имя принтера по идентификатору — через существующий помощник строки принтера."""
    r = _pf_printer_row(pid)
    try:
        return (r["name"] if r else "") or str(pid or "")
    except Exception:
        return str(pid or "")


def _qw_row(r):
    """Строка ожидания из базы -> словарь для интерфейса."""
    return {"id": r["id"], "gcode_file": r["gcode_file"], "source": r["source"],
            "part_name": r["part_name"], "material": r["material"],
            "state": r["state"], "note": r["note"], "created_at": r["created_at"]}


#  ── 15.09.2026: подбор переписан после проверки «очередь не видит материал» ─────────────────
#  Слово владельца: складского учёта на ферме нет, материал указан только на самом принтере и
#  совпадает с файлом, а очередь пишет «у свободных принтеров нет нужного материала». Склад тут
#  ни при чём — проверка нашла другие причины:
#    * внешняя катушка Bambu в подборе не участвовала вовсе, а сама разбиралась не из того места
#      отчёта (см. _bambu_ext_slots);
#    * от файла требовались ВСЕ материалы проекта, а не те, что печатает нарезанная плита: проект,
#      синхронизированный с AMS, объявляет материалы всех слотов;
#    * «программа не видит материал принтера» и «нужного материала нет» были одной причиной.
#  Теперь подбор проверяет то же, что потом сделает запуск: какая плита уйдёт в печать, из какого
#  источника пойдёт материал, подходит ли файл принтеру и свободен ли принтер на самом деле, — и
#  по каждому разрешённому принтеру говорит, почему он подходит или нет. Материал по-прежнему
#  сверяется буквально (_orch.norm_material): «PLA-S» не равен «PLA», решать за владельца нельзя.
_QW_FILE_CACHE_MAX = 256
_QW_GCODE_HEAD = 262144
_QW_GCODE_TAIL = 524288
_QW_CAND_MAX = 6
_QW_PLATE_RE = re.compile(r"plate_(\d+)\.gcode$", re.IGNORECASE)
_qw_file_cache = {}                      # путь -> ((mtime_ns, size), сведения о файле)
_qw_file_lock = threading.Lock()         # очередь опрашивают несколько компьютеров фермы разом
#  16.10.2026 (R-137, R-115): «left_spool» больше не выдаётся — с левой внешней катушки H2D очередь
#  запускает, если файл нарезан под левое сопло. Новые вердикты: ext_wrong_side — материал на внешней
#  катушке другой стороны; ext_side_unknown — в файле не видно сопла; dual_nozzle_unverified —
#  двухсопельный принтер подходит по AMS, но сопла в файле не видно: только ручной запуск.
_QW_MISMATCH = ("material_mismatch", "printer_empty", "ext_multi", "ext_wrong_side", "ext_side_unknown",
                "ams_unmapped", "slot_mismatch", "slot_unknown")
#  16.10.2026 (R-141): owner_check — FlashForge без станции материалов: материал по сети не виден,
#  однофиламентный файл предлагается ТОЛЬКО на ручной «Запустить» с просьбой проверить катушку.
#  16.10.2026 (R-141, разбор пакета): ff_station и single_nozzle_multi — FlashForge, которому файл из
#  очереди не подходит (станция материалов; одно сопло, а филаментов несколько): в итоге строки —
#  «принтеры не подходят к файлу», как incompatible (_QW_UNFIT).
_QW_UNFIT = ("incompatible", "ff_station", "single_nozzle_multi")
_QW_VERDICT_ORDER = {"ready": 0, "dual_nozzle_unverified": 1, "owner_check": 1, "material_unknown_on_printer": 1,
                     "material_mismatch": 2, "printer_empty": 2, "ext_multi": 2, "ext_wrong_side": 2,
                     "ext_side_unknown": 2, "ams_unmapped": 2,
                     "slot_mismatch": 2, "slot_unknown": 2, "incompatible": 3, "ff_station": 3,
                     "single_nozzle_multi": 3, "reserved": 4,
                     "in_queue": 4, "printing": 5, "working_stage": 5, "not_free": 5, "offline": 6}
#  Сырые состояния, после которых на столе может остаться деталь: печать закончена или отменена. Статус
#  карточки после отмены у Bambu и Klipper показывает IDLE (см. _user_stopped, _cancel_latch), поэтому
#  смотрим сырой статус прошивки.
_QW_BED_RAW = {"bambu": ("FINISH", "FAILED"), "klipper": ("complete", "cancelled", "error"),
               "flashforge": ("completed", "complete", "cancel", "cancelled", "error"),
               "creality": ("complete", "cancelled", "error"),
               "demo": ("finish", "cancelled")}


def _qw_blank_info(state):
    """Сведения о файле без требований: file_missing / not_printable / unreadable / ok."""
    return {"state": state, "fmt": "", "need": [], "fils": [], "file_map": None, "declared": 0,
            "source": "", "why": "", "target": {}, "sides": [], "extruders": None}


def _3mf_plate_used(fdata):
    """Какие филаменты проекта печатает плита, которую отправит запуск Bambu. Только чтение.

    -> {"ok", "idx": [индексы от 0], "types": {индекс: тип из slice_info}, "used_g": {индекс: граммы},
        "source", "why"}
    Плита выбирается ТЕМ ЖЕ правилом, что в _send_file_to_printer: первая по sorted() среди
    Metadata/plate_N.gcode (plate_10 раньше plate_2) — сверяется ровно та плита, что уйдёт в печать.
    Использованные филаменты — из slice_info.config именно этой плиты: Bambu Studio пишет туда
    только филаменты, реально ушедшие в печать (bbs_3mf.cpp, slice_filaments_info). Нет slice_info
    вовсе — source=project, и вызывающий берёт все филаменты проекта: это надмножество, с ним
    принтер может не найтись, но неверный не назначится.

    16.10.2026 (R-016): филамент с used_g, который ЕСТЬ и не больше нуля, плита не расходует и в
    требования не попадает (так же Bambuddy, filament_requirements.py: «slot present in the slicer
    config but not consumed by this plate»). Нет атрибута — филамент берётся, как раньше. Граммы
    плиты по номеру филамента отдаются в used_g (R-136: Bambu Studio пишет в G-code только вес
    использованных филаментов, без нулей, и по позиции в той строке номер филамента не восстановить)."""
    out = {"ok": False, "idx": [], "types": {}, "used_g": {}, "source": "", "why": ""}
    try:
        with zipfile.ZipFile(io.BytesIO(fdata)) as z:
            names = z.namelist()
            gcodes = [n for n in names if n.endswith(".gcode")]
            plates = [n for n in gcodes if "plate_" in n.lower()]
            if not gcodes:
                out["why"] = "not_sliced"
                return out
            plate_no = None
            if plates:
                m = _QW_PLATE_RE.search(sorted(plates)[0])
                plate_no = int(m.group(1)) if m else None
            si_raw = (z.read(_REQ_SLICE_INFO).decode("utf-8", "ignore")
                      if _REQ_SLICE_INFO in names else None)
    except Exception:
        out["why"] = "unreadable"
        return out
    if si_raw is None:
        out.update({"ok": True, "source": "project"})
        return out
    try:
        nodes = list(ET.fromstring(si_raw).iter("plate"))
    except Exception:
        out["why"] = "unreadable"
        return out
    target = None
    for pl in nodes:
        num = None
        for md in pl.findall("metadata"):
            if (md.get("key") or "").strip().lower() == "index":
                try:
                    num = int(str(md.get("value")).strip())
                except Exception:
                    num = None
                break
        if plate_no is not None and num == plate_no:
            target = pl
            break
    if target is None and plate_no is None and len(nodes) == 1:
        target = nodes[0]
    if target is None:
        out["why"] = "plate_not_described"
        return out
    idx, types, used = [], {}, {}
    for fl in target.findall("filament"):
        try:
            i = int(fl.get("id")) - 1
        except Exception:
            continue
        if i < 0 or i in types:
            continue
        _g = None
        if fl.get("used_g") is not None:
            try:
                _g = float(str(fl.get("used_g")).strip())
            except Exception:
                _g = None
            if _g is not None and _g <= 0:
                continue                     # R-016: плита этот филамент не расходует
        idx.append(i)
        types[i] = str(fl.get("type") or "").strip()
        if _g is not None:
            used[i] = _g
    if not idx:
        out["why"] = "plate_without_filaments"
        return out
    out.update({"ok": True, "idx": sorted(idx), "types": types, "used_g": used, "source": "plate"})
    return out


def _3mf_side_values(v):
    """filament_maps / filament_map -> [1|2|None]: 1 — левое сопло, 2 — правое; прочее — не знаем."""
    if isinstance(v, (list, tuple)):
        items = list(v)
    else:
        items = str(v or "").replace(",", " ").split()
    out = []
    for x in items:
        try:
            n = int(str(x).strip())
        except Exception:
            n = None
        out.append(n if n in (1, 2) else None)
    return out


def _3mf_filament_sides(fdata):
    """К какому соплу плита привязала каждый филамент проекта (двухсопельные H2D). Только чтение.

    16.10.2026 (R-006). -> {"ok", "maps": [1|2|None по филаментам проекта], "extruders", "source"}
    1 — левое сопло, 2 — правое (Bambu Studio, filament_map). Источники по порядку: slice_info.config
    той плиты, что уйдёт в печать (<plate> metadata «filament_maps», значения через пробел — Studio
    bbs_3mf.cpp, _add_slice_info_config_file_to_archive), затем model_settings.config той же плиты
    (plater_id), затем project_settings.config «filament_map». Плита — то же правило, что у отправки
    (первая по sorted() среди plate_N.gcode). extruders — число сопел файла (nozzle_diameter в
    project_settings). Подбор слота учитывает сопло, только когда файл на два сопла и сопло известно;
    ничего не прочитали — ok=False, и подбор по соплу не ограничивает (не угадываем)."""
    out = {"ok": False, "maps": [], "extruders": None, "source": ""}
    try:
        with zipfile.ZipFile(io.BytesIO(fdata)) as z:
            names = z.namelist()
            plates = [n for n in names if n.endswith(".gcode") and "plate_" in n.lower()]
            plate_no = None
            if plates:
                m = _QW_PLATE_RE.search(sorted(plates)[0])
                plate_no = int(m.group(1)) if m else None
            def _rd(name):
                return z.read(name).decode("utf-8", "ignore") if name in names else None
            si_raw, ms_raw = _rd(_REQ_SLICE_INFO), _rd("Metadata/model_settings.config")
            ps_raw = _rd(_REQ_PROJECT_SETTINGS)
    except Exception:
        return out
    ps = None
    try:
        ps = json.loads(ps_raw) if ps_raw else None
    except Exception:
        ps = None
    if isinstance(ps, dict) and isinstance(ps.get("nozzle_diameter"), list):
        out["extruders"] = len(ps.get("nozzle_diameter")) or None

    def _plate_maps(raw, num_keys):
        try:
            nodes = list(ET.fromstring(raw).iter("plate"))
        except Exception:
            return None
        target = None
        for pl in nodes:
            num = None
            for md in pl.findall("metadata"):
                if (md.get("key") or "").strip().lower() in num_keys:
                    try:
                        num = int(str(md.get("value")).strip())
                    except Exception:
                        num = None
                    break
            if plate_no is not None and num == plate_no:
                target = pl
                break
        if target is None and plate_no is None and len(nodes) == 1:
            target = nodes[0]
        if target is None:
            return None
        for md in target.findall("metadata"):
            if (md.get("key") or "").strip().lower() == "filament_maps":
                return _3mf_side_values(md.get("value"))
        return None

    maps, src = None, ""
    for _src, _get in (("slice_info", lambda: _plate_maps(si_raw, ("index",)) if si_raw else None),
                       ("model_settings", lambda: _plate_maps(ms_raw, ("plater_id",)) if ms_raw else None),
                       ("project_settings", lambda: (_3mf_side_values(ps.get("filament_map"))
                                                     if isinstance(ps, dict) and ps.get("filament_map") is not None
                                                     else None))):
        _m = _get()
        if _m and any(x in (1, 2) for x in _m):
            maps, src = _m, _src
            break
    if not maps:
        return out
    if out["extruders"] is None and 2 in maps:
        out["extruders"] = 2
    out.update({"ok": True, "maps": maps, "source": src})
    return out


def _qw_3mf_info(fdata):
    """Что нарезанный .3mf потребует от принтера при запуске. Только чтение байтов файла.

    Материал филамента берётся из _3mf_filament_requirements — из того же списка, с которым
    сверяет слоты подбор запуска (_bambu_auto_slot_map), иначе очередь и запуск могли бы назвать
    один филамент по-разному. Тип из slice_info — только если там пусто."""
    info = _qw_blank_info("ok")
    info["fmt"] = "3mf"
    if not _is_3mf_printable(fdata):
        info["state"] = "not_printable"
        return info
    fils = list((_3mf_filament_requirements(fdata) or {}).get("filaments") or [])
    #  16.10.2026 (R-006): зеркало раскладки получает всё, что сравнивает подбор запуска: опорный ли
    #  филамент, его filament_id и сопло (H2D), — иначе очередь и запуск разложили бы файл по-разному.
    _sides = _3mf_filament_sides(fdata)
    info["fils"] = _bslot.with_sides(
        [{"material": (f or {}).get("material"), "color_hex": (f or {}).get("color_hex"),
          "is_support": bool((f or {}).get("is_support")), "filament_id": (f or {}).get("filament_id")}
         for f in fils], _sides)
    #  16.10.2026 (R-137, R-115): сопло каждого филамента (1 левое, 2 правое, None — не видно) и число
    #  сопел файла — по ним очередь выбирает внешнюю катушку H2D той же стороной, что и запуск.
    info["sides"] = [(f or {}).get("side") for f in info["fils"]]
    info["extruders"] = (_sides or {}).get("extruders")
    try:
        use, fmap = _bambu_ams_mapping(fdata)
    except Exception:
        use, fmap = False, []
    if use and fmap:
        info["file_map"] = [int(x) for x in fmap]
        info["declared"] = len(fmap)
    pu = _3mf_plate_used(fdata)
    info["why"] = pu.get("why") or ""
    if pu.get("ok"):
        idx = pu["idx"] if pu.get("source") == "plate" else list(range(len(fils)))
        need = []
        for i in idx:
            mat = (fils[i] or {}).get("material") if i < len(fils) else None
            mat = str(mat or (pu.get("types") or {}).get(i) or "").strip()
            if not mat:
                need = []
                info["why"] = "material_not_named"
                break
            need.append({"idx": i, "material": mat,
                         "color": ((fils[i] or {}).get("color_hex") if i < len(fils) else None)})
        info["need"] = need
        info["source"] = (pu.get("source") or "") if need else ""
    try:
        t = detect_target(fdata, "file.3mf") or {}
        info["target"] = {"model": t.get("model"), "model_raw": t.get("model_raw"),
                          "extruders": t.get("extruders")}
    except Exception:
        log.debug("[QUEUE-WAIT] target not read: %s", _exc_brief())
    return info


def _qw_gcode_info(data, whole):
    """Что требует плоский g-code: материал и ячейка каждого филамента, ушедшего в печать.

    Слайсеры на основе Bambu Studio и Orca (в том числе Creality Print владельца) пишут в файл
    «; filament_type = PETG;PETG» — материалы всех филаментов проекта — и «; filament used [g] =
    3.66, 0.00» — расход по каждому (файлы владельца для K2 Plus, 04.09.2026). В печать ушли
    филаменты с ненулевым расходом; номер филамента — это и номер ячейки CFS (строка T<n>, см.
    app/gcode_tool_slot.py). Строки расхода нет — берётся единственная строка T<n>, но только если
    файл прочитан целиком: в середине большого файла могут быть другие смены инструмента.
    Всё неоднозначное -> требований нет (материал файла неизвестен)."""
    info = _qw_blank_info("ok")
    info["fmt"] = "gcode"
    meta = _gts.read_meta(data)
    types = [str(x or "").strip() for x in (meta.get("types") or [])]
    used = None
    for key in ("; filament used [g] = ", "; filament used [mm] = "):
        if (meta.get("used") or {}).get(key):
            used = meta["used"][key]
            break
    tools = sorted({t["index"] for t in _gts.find_tool_lines(data)})
    slots = None
    if used:
        nums = []
        for v in used:
            v = str(v or "").strip()
            try:
                nums.append(float(v) if v else 0.0)
            except Exception:
                nums = None
                break
        slots = [i for i, x in enumerate(nums) if x > 0] if nums is not None else None
        #  Номер филамента считается ячейкой, только если файл сам выбирает её строкой T<n>. Без такой
        #  строки принтер печатает из заправленной сейчас ячейки, и материал «в ячейке по номеру» ничего
        #  не доказывает. Строки T<n> не совпадают с расходом — противоречие, тоже не угадываем.
        if slots and sorted(set(tools)) != sorted(set(slots)):
            info["why"] = "tool_conflict" if tools else "no_tool_line"
            slots = None
    elif whole and len(tools) == 1:
        slots = tools
    #  16.10.2026 (R-016, R-118): цвет филамента — из «; filament_colour = #RRGGBB;…» того же блока
    #  настроек слайсера (Orca/Creality Print пишут его рядом с filament_type). Нужен, чтобы показать
    #  «цвет отличается» и чтобы автозапуск брал только точный цвет. Нет строки — цвет неизвестен.
    colours = [str(x or "").strip() for x in (meta.get("colours") or [])]
    need = []
    for i in (slots or []):
        mat = types[i] if i < len(types) else ""
        if not mat:
            need = []
            info["why"] = "material_not_named"
            break
        need.append({"idx": i, "material": mat, "color": (colours[i] if i < len(colours) and colours[i] else None)})
    info["need"] = need
    info["source"] = "gcode" if need else ""
    if not need and not info["why"]:
        info["why"] = "gcode_not_declared"
    try:
        t = detect_target(data, "file.gcode") or {}
        info["target"] = {"model": t.get("model"), "model_raw": t.get("model_raw"),
                          "extruders": t.get("extruders")}
    except Exception:
        log.debug("[QUEUE-WAIT] target not read: %s", _exc_brief())
    return info


def _qw_file_info(fname, part_name="", fresh=False):
    """Сведения о файле строки очереди -> (info, байты .3mf или None).

    Очередь опрашивается каждые ~12 секунд с каждого компьютера фермы, поэтому сведения хранятся
    по времени изменения и размеру файла: перенарезанный файл виден при следующем опросе, а
    неизменный заново не читается. fresh=True читает файл в любом случае и отдаёт байты .3mf —
    так делает запуск: решение принимается по тому, что уйдёт на принтер."""
    try:
        path = _staging_path(fname, part_name or None)
        if not path or not os.path.isfile(path):
            return _qw_blank_info("file_missing"), None
        st = os.stat(path)
        key = (st.st_mtime_ns, st.st_size)
        if not fresh:
            with _qw_file_lock:
                c = _qw_file_cache.get(path)
            if c and c[0] == key:
                return c[1], None
        low = str(path).lower()
        fdata = None
        if low.endswith(".3mf"):
            with open(path, "rb") as f:
                fdata = f.read()
            info = _qw_3mf_info(fdata)
        elif low.endswith(".gcode"):
            whole = st.st_size <= _QW_GCODE_HEAD + _QW_GCODE_TAIL
            with open(path, "rb") as f:
                if whole:
                    chunk = f.read()
                else:
                    head = f.read(_QW_GCODE_HEAD)
                    f.seek(st.st_size - _QW_GCODE_TAIL)
                    tail = f.read(_QW_GCODE_TAIL)
                    #  Обрывки строк на стыке отбрасываются: половинка строки могла бы
                    #  прикинуться строкой выбора ячейки T<n>.
                    chunk = head[:head.rfind(b"\n") + 1] + tail[tail.find(b"\n") + 1:]
            info = _qw_gcode_info(chunk, whole)
        else:
            info = _qw_blank_info("not_printable")
        with _qw_file_lock:
            if path not in _qw_file_cache and len(_qw_file_cache) >= _QW_FILE_CACHE_MAX:
                _qw_file_cache.pop(next(iter(_qw_file_cache)), None)
            _qw_file_cache[path] = (key, info)
        return info, fdata
    except Exception:
        log.debug("[QUEUE-WAIT] file info failed: %s", _exc_brief())
        return _qw_blank_info("unreadable"), None


def _qw_mats(info):
    """Материалы файла для показа: без повторов, заглавными, в порядке филаментов."""
    out = []
    for n in (info or {}).get("need") or []:
        m = str(n.get("material") or "").strip().upper()
        if m and m not in out:
            out.append(m)
    return out


def _qw_ctx():
    """Общий снимок для подбора по всем строкам одного запроса: парк с разрешениями, очередь
    запусков, занятые отправкой, порог «скоро кончится». Один запрос к базе на весь опрос, а не
    по запросу на принтер и строку: принтеров на ферме сотни."""
    ctx = {"fleet": {}, "allowed": set(), "taken": set(), "reserved": set(), "low_pct": 15,
           "feed": {}, "busy": {}, "rel": {}}
    try:
        with lock_pr:
            rows = conn_pr.execute("SELECT id, name, type, model, COALESCE(queue_allowed,0) AS qa "
                                   "FROM printers").fetchall()
        for r in rows:
            pid = r["id"]
            ctx["fleet"][pid] = {"id": pid, "name": r["name"] or pid, "type": r["type"],
                                 "model": _printer_model_code(pid) or _normalize_model(r["model"]),
                                 "noz": (p_states.get(pid, {}) or {}).get("nozzle_count")}
            if int(r["qa"] or 0) == 1:
                ctx["allowed"].add(pid)
    except Exception:
        log.debug("[QUEUE-WAIT] fleet read failed: %s", _exc_brief())
    with print_queue_lock:
        ctx["taken"] = {q["printer_id"] for q in print_queue}
    #  16.09.2026: принтер с НЕЗАКРЫТОЙ строкой в долговременной очереди запусков тоже занят.
    #  Это не то же самое, что очередь в памяти: после перезапуска программы прерванные запуски
    #  лежат в recovery_hold / recovery_attention и ждут человека, а в память не попадают —
    #  подбор считал такой принтер свободным. Для владельца это выглядело бы как «очередь сама
    #  отправила вторую печать на принтер, где первая не разобрана».
    try:
        with lock_pr:
            _dq = conn_pr.execute(
                "SELECT DISTINCT printer_id FROM print_launch_queue WHERE status IN "
                "('pending','launching','recovery_hold')").fetchall()
        #  16.09.2026: recovery_attention сюда НЕ входит намеренно. Выхода из этого статуса в
        #  программе нет, и принтер пропадал из подбора навсегда — вместе с ручным запуском.
        #  Такие строки видны владельцу отдельно, в окне разбора прерванных запусков.
        ctx["taken"] |= {str(_r["printer_id"]) for _r in _dq if _r["printer_id"]}
    except Exception:
        log.debug("[QUEUE-WAIT] durable queue read failed: %s", _exc_brief())
    try:
        ctx["reserved"] = set(_send_mgr.reserved_ids())
    except Exception:
        log.debug("[QUEUE-WAIT] send manager check failed: %s", _exc_brief())
    ctx["low_pct"] = _ams_low_pct()
    return ctx


def _qw_busy_verdict(pid, ptype, ctx):
    """Свободен ли принтер на самом деле. -> '' (свободен) или код, почему нет.

    Статус карточки намеренно искажён: после «Стоп» Bambu рисуется свободным, пока принтер ещё
    отрабатывает отмену (у P2S до 3-4 минут, см. _user_stopped). Поэтому кроме статуса смотрим
    сырой статус прошивки и стадию, чем принтер занят прямо сейчас (_send_working_stage).
    16.10.2026 (R-138): стадия и смена филамента — тем же правилом, что у запуска (_bambu_stage_busy)."""
    if pid in ctx["taken"]:
        return "in_queue"
    _status, fresh = _send_printer_status(pid)
    if not fresh:
        return "offline"
    st = p_states.get(pid) or {}
    status = str(st.get("status") or "").upper()
    if status not in ("IDLE", "READY", "FINISH"):
        return "printing" if status in ("RUNNING", "PREPARE", "PAUSED", "PAUSE", "SLICING") else "not_free"
    raw = str(st.get("status_raw") or "")
    if raw in _ACTIVE_RAW.get(ptype, ()):
        return "printing"
    #  Стадия работы (stg_cur) — тот же признак, по которому запуск Bambu откажется слать команду
    #  (_bambu_busy_before_start, _bambu_busy_now). Правило у очереди и запуска обязано быть одним:
    #  предложи очередь принтер, который запуск сочтёт занятым, — строка ушла бы из очереди, а печать
    #  не началась. Отдельный вердикт с номером стадии: видно, что именно сообщает принтер (в открытой
    #  интеграции ha-bambulab есть поправка «стадия 0 у простаивающего принтера» — если так ведёт себя
    #  прошивка на ферме, это покажет строка очереди, и чинить надо и запуск, и очередь вместе).
    if _send_working_stage(pid):
        return "working_stage"
    try:
        if pid in ctx["reserved"] or _send_mgr.get_hold(pid):
            return "reserved"
    except Exception:
        log.debug("[QUEUE-WAIT] send manager check failed: %s", _exc_brief())
    return ""


def _qw_busy_words(pid):
    """Чем занят принтер Bambu — словами для строки очереди (вердикт working_stage). -> {"ru", "en"} или None.

    16.10.2026 (R-138, проверка пакета). Вердикт working_stage после R-138 бывает и от смены филамента
    в AMS, и от смены стадии после нашей команды, а строка очереди писала «выполняет подготовку
    (стадия 255)» — не ту причину. Причина — та же, что у запуска (_bambu_busy_reason: стадия названа
    по-русски), без «принтер» в начале: в списке она стоит после имени принтера."""
    try:
        r = _bambu_busy_reason(pid)
    except Exception:
        log.debug("[QUEUE-WAIT] busy reason failed: %s", _exc_brief())
        return None
    if not r or not r.get("ru"):
        return None
    ru, en = str(r.get("ru") or ""), str(r.get("en") or "")
    for _pre in ("принтер занят — ", "принтер "):
        if ru.startswith(_pre):
            ru = ru[len(_pre):]
            break
    for _pre in ("the printer is busy: it ", "the printer "):
        if en.startswith(_pre):
            en = en[len(_pre):]
            break
    return {"ru": ru, "en": en}


def _qw_printer_feed(pid, ptype):
    """Что принтер сообщает о заправленном материале. -> (reports, have)

    reports — у принтера есть телеметрия подачи, пусть даже всё пусто (сверять есть с чем);
    have — [{"where": ams|ext|ext_left|cfs, "slot", "label", "material", "named"}]: только позиции
    с материалом. Bambu — слоты AMS и обе внешние катушки; Klipper — ячейки CFS (у K2); FlashForge
    и прочие о материале не сообщают — сверять нечем, и это называется прямо."""
    st = p_states.get(pid) or {}
    have, reports = [], False
    if ptype == "bambu":
        trays = st.get("ams_trays") or []
        reports = bool(trays)
        for t in trays:
            if not isinstance(t, dict):
                continue
            #  16.10.2026 (R-139): датчик подачи лотка не видит — материала в слоте нет, что бы ни
            #  осталось в поле типа от прошлой катушки.
            if t.get("present") is False:
                continue
            m = _reported_material_norm(t.get("type"))
            try:
                idx = int(t.get("index"))
            except Exception:
                continue
            if m:
                have.append({"where": "ams", "slot": idx, "label": "", "material": m, "named": True})
        ext = st.get("ext_trays") or {}
        #  16.10.2026 (R-137): левая внешняя (254) — только у двухсопельного. У односопельного «254»
        #  в отчёте второй катушкой не бывает (у P1P так приходит id основной) — её не показываем.
        try:
            _dual = int(st.get("nozzle_count") or 1) >= 2
        except Exception:
            _dual = False
        for sid, where in ((_BAMBU_EXT_MAIN, "ext"), (_BAMBU_EXT_DEPUTY, "ext_left")):
            if where == "ext_left" and not _dual:
                continue
            e = ext.get(sid)
            if not isinstance(e, dict):
                continue
            reports = True
            m = _reported_material_norm(e.get("tray_type"))
            if m:
                have.append({"where": where, "slot": None, "label": "", "material": m, "named": True})
    elif ptype == "klipper":
        trays = st.get("cfs_trays") or []
        reports = bool(trays)
        for t in trays:
            if not isinstance(t, dict):
                continue
            m = _reported_material_norm(t.get("type"))
            try:
                idx = int(t.get("index"))
            except Exception:
                continue
            if m:
                code = str(t.get("code") or "").strip()
                #  Имя материала CFS даёт сам принтер (same_material). Не назвал — в поле лежит код
                #  «000003», и сравнивать его с «PETG» из файла нельзя.
                have.append({"where": "cfs", "slot": idx, "label": str(t.get("label") or ""),
                             "material": m, "named": not (code and m == code)})
    return reports, have


def _qw_feed(pid, ptype, ctx):
    """_qw_printer_feed один раз на принтер за опрос: от строки очереди он не зависит."""
    memo = ctx.setdefault("feed", {})
    if pid not in memo:
        memo[pid] = _qw_printer_feed(pid, ptype)
    return memo[pid]


def _qw_auto_slot_mirror(trays, fils, file_map, low_pct, rel_cache=None, plate_idx=None):
    """Зеркало _bambu_auto_slot_map для опроса очереди: та же раскладка филаментов файла по слотам
    AMS, но по уже прочитанным требованиям, без чтения файла каждые 12 секунд. Решение о запуске
    принимает не зеркало: api_queue_wait_start перепроверяет раскладку самим подбором запуска.
    16.10.2026 (R-006): раскладка ОДНА — app/bambu_slot_match.assign, её же зовёт подбор запуска,
    поэтому второй копии, которую надо держать в согласии, больше нет (tools/test_queue_wait.py
    по-прежнему сверяет обе на одних данных).
    rel_cache — сравнения цветов за один опрос: на ферме одни и те же катушки повторяются.
    plate_idx — филаменты, которые печатает плита (R-136): остальным слот не раздаётся (-1)."""
    try:
        return _bslot.assign(trays, fils, file_map, low_pct, _orch, _tray_remain,
                             plate_idx=plate_idx, rel_cache=rel_cache)[0]
    except Exception:
        return [int(x) for x in file_map]


def _qw_ams_label(t, idx):
    """Подпись слота AMS так же, как в интерфейсе: «AMS 1·2» (блок и слот с единицы), «AMS HT»."""
    try:
        unit = int(t.get("unit")) if t.get("unit") is not None else int(idx) // 4
        tray = int(t.get("tray")) if t.get("tray") is not None else int(idx) % 4
    except Exception:
        return "AMS"
    if unit >= 128:
        return "AMS HT" + ("" if unit == 128 else " %d" % (unit - 127))
    return "AMS %d·%d" % (unit + 1, tray + 1)


def _qw_slot_detail(n, where, slot, label, file_color, slot_color, file_fid="", slot_fid="", rel_cache=None):
    """Куда пойдёт филамент файла и совпадает ли цвет. 16.10.2026 (R-016, R-118, R-115).

    rel — отношение цвета файла и катушки (_orch.color_relation: exact / close / mismatch / unknown).
    variant — у катушки и у файла известен номер филамента (tray_info_idx / filament_id: GFA00 Basic,
    GFA01 Matte …), и он разный: это другой вариант того же материала. Ручной запуск это не
    запрещает — только показывает; автозапуск такую строку не берёт."""
    ck = (file_color, slot_color)
    if rel_cache is not None and ck in rel_cache:
        rel = rel_cache[ck][0]
    else:
        rel, _dist = _orch.color_relation(file_color, slot_color)
        if rel_cache is not None:
            rel_cache[ck] = (rel, _dist)
    ff = str(file_fid or "").strip().upper()
    sf = str(slot_fid or "").strip().upper()
    return {"idx": n.get("idx"), "material": str(n.get("material") or ""), "where": where, "slot": slot,
            "label": label, "file_color": _orch.norm_hex(file_color) or "",
            "slot_color": _orch.norm_hex(slot_color) or "", "rel": rel,
            "variant": bool(ff and sf and ff != sf), "file_fid": ff, "slot_fid": sf}


def _qw_bambu_ams_proof(pid, info, fdata, low_pct, rel_cache=None, detail=None):
    """Уйдёт ли печать из AMS именно с нужным материалом. Запуск «Авто» раскладывает файл по слотам
    (_bambu_resolve_ams -> _bambu_auto_slot_map); здесь проверяется ИТОГ этой раскладки для каждого
    филамента, который печатает плита. Есть байты файла (запуск) — зовётся сам подбор запуска; нет
    (опрос очереди) — его зеркало. Без AMS, без карты филаментов файла — не доказано.
    detail — список, куда при успехе кладётся, в какой слот пойдёт каждый филамент (_qw_slot_detail)."""
    trays = list((p_states.get(pid) or {}).get("ams_trays") or [])
    fmap = info.get("file_map")
    need = info.get("need") or []
    if not trays or not fmap or not need:
        return False
    #  16.10.2026 (R-139, R-006): лоток без датчика подачи (present False) материала не даёт, а
    #  материалы сравниваются ТЕМ ЖЕ правилом, что у раскладки (опорные — как в Bambu Studio).
    _fils = info.get("fils") or []

    def _want(n):
        _i = n.get("idx")
        _f = _fils[_i] if (isinstance(_i, int) and 0 <= _i < len(_fils) and isinstance(_fils[_i], dict)) else {}
        return _orch.norm_material(_bslot.fila_type(n.get("material"), bool(_f.get("is_support")),
                                                    _f.get("filament_id")))

    def _have(t):
        if not isinstance(t, dict) or t.get("present") is False:
            return ""
        return _orch.norm_material(_bslot.fila_type(_reported_material_norm(t.get("type")), False,
                                                    t.get("tray_info_idx")))
    present = {_have(t) for t in trays} - {""}
    if not all(_want(n) in present for n in need):
        return False                       # нужного материала в AMS нет вовсе — раскладывать нечего
    if fdata is not None:
        out = _bambu_auto_slot_map(pid, fdata, fmap) or list(fmap)
    else:
        out = _qw_auto_slot_mirror(trays, info.get("fils") or [], fmap, low_pct, rel_cache,
                                   ([n.get("idx") for n in need] if info.get("source") == "plate" else None))
    by_idx = {}
    for t in trays:
        try:
            by_idx[int(t.get("index"))] = t
        except Exception:
            continue
    #  16.10.2026 (R-006, проверка пакета): у двухсопельного слот обязан быть на СВОЁМ сопле. Подбор, не
    #  найдя слота своего сопла, оставляет филаменту слот из файла — а тот бывает на чужом; такую карту
    #  Bambu Studio не строит, принтер на ней встаёт. Материал совпадает — но это не «готово»: строка
    #  получит «материал есть в AMS, но не в тех слотах», и автозапуск её не возьмёт. Как и у запуска
    #  (_bambu_cross_nozzle): односопельный и сторона/сопло не известны — не ограничиваем.
    try:
        _dual = int((p_states.get(pid) or {}).get("nozzle_count") or 1) >= 2
    except Exception:
        _dual = False
    rows = []
    for n in need:
        i = n.get("idx")
        if not isinstance(i, int) or i < 0 or i >= len(out):
            return False
        t = by_idx.get(int(out[i])) or {}
        mat = _have(t)
        if not mat or mat != _want(n):
            return False
        if _dual:
            _side = _fils[i].get("side") if (i < len(_fils) and isinstance(_fils[i], dict)) else None
            if not _bslot.side_ok(_side, t.get("extruder")):
                return False
        _f = _fils[i] if (0 <= i < len(_fils) and isinstance(_fils[i], dict)) else {}
        _d = _qw_slot_detail(n, "ams", int(out[i]), _qw_ams_label(t, int(out[i])),
                             n.get("color") or _f.get("color_hex"), t.get("color_raw") or t.get("color"),
                             _f.get("filament_id"), t.get("tray_info_idx"), rel_cache)
        #  R-118: «по датчику» — лоток подтверждён датчиком подачи (tray_exist_bits), а не только типом.
        _d["sensor"] = t.get("present") is True
        rows.append(_d)
    if detail is not None:
        detail.extend(rows)
    return True


def _qw_bambu_verdict(pid, info, fdata, ctx):
    """Материал для Bambu: откуда пойдёт печать и лежит ли там нужное. -> (verdict, feed)."""
    reports, have = _qw_feed(pid, "bambu", ctx)
    need = info.get("need") or []
    want = {_orch.norm_material(n.get("material")) for n in need}
    try:
        dual = int((p_states.get(pid) or {}).get("nozzle_count") or 1) >= 2
    except Exception:
        dual = False
    sides = info.get("sides") or []

    def _side(n):
        """Сопло филамента плиты по файлу (1 левое, 2 правое) — только у файла на два сопла."""
        i = n.get("idx")
        if info.get("extruders") != 2 or not isinstance(i, int) or not (0 <= i < len(sides)):
            return None
        return sides[i] if sides[i] in (1, 2) else None
    #  16.10.2026 (R-016, R-118): feed["slots"] — куда пойдёт каждый филамент и совпадает ли цвет
    #  (_qw_slot_detail). По нему строка и окно запуска пишут «цвет отличается», а автозапуск берёт
    #  только точный цвет.
    _slots = []
    if _qw_bambu_ams_proof(pid, info, fdata, ctx.get("low_pct", 15), ctx.setdefault("rel", {}), _slots):
        #  16.10.2026 (R-115): двухсопельный принтер, а в файле не видно, каким соплом печатает плита, —
        #  раскладку по AMS сопоставить с соплами нечем. Автозапуск такую строку не берёт; запустить
        #  вручную можно, окно подтверждения об этом предупредит.
        if dual and not all(_side(n) for n in need):
            return "dual_nozzle_unverified", {"kind": "ams", "unverified": True, "slots": _slots}
        return "ready", {"kind": "ams", "slots": _slots}
    main = [h for h in have if h["where"] == "ext"]
    left = [h for h in have if h["where"] == "ext_left"]
    _ext = (p_states.get(pid) or {}).get("ext_trays") or {}

    def _ext_slots(sid, where):
        """Подробность для внешней катушки: цвет на экране принтера против цвета файла."""
        e = _ext.get(sid) if isinstance(_ext, dict) else None
        e = e if isinstance(e, dict) else {}
        _i = need[0].get("idx")
        _fl = info.get("fils") or []
        _f = _fl[_i] if (isinstance(_i, int) and 0 <= _i < len(_fl) and isinstance(_fl[_i], dict)) else {}
        return [_qw_slot_detail(need[0], where, None, "", need[0].get("color") or _f.get("color_hex"),
                                e.get("tray_color"), _f.get("filament_id"), e.get("tray_info_idx"),
                                ctx.setdefault("rel", {}))]
    if len(want) == 1:
        w = next(iter(want))
        m_ok = bool(main) and _orch.norm_material(main[0]["material"]) == w
        l_ok = dual and bool(left) and _orch.norm_material(left[0]["material"]) == w
        if m_ok or l_ok:
            #  16.10.2026 (R-137): внешняя катушка одна на сопло — плита обязана печатать ОДИН филамент
            #  (проект может объявлять больше — запуск дополнит команду «не назначен» для остальных).
            if len(need) != 1:
                return "ext_multi", None
            if not dual:
                return "ready", {"kind": "external", "slots": _ext_slots(_BAMBU_EXT_MAIN, "ext")}
            #  Двухсопельный: катушка той стороны, под чьё сопло нарезан файл (1 — левая 254,
            #  2 — правая 255), ровно как соберёт команду запуск (_bambu_ext_choice).
            sd = _side(need[0])
            if sd is None:
                return "ext_side_unknown", None
            if sd == 1:
                return (("ready", {"kind": "external", "ext": 254,
                                   "slots": _ext_slots(_BAMBU_EXT_DEPUTY, "ext_left")}) if l_ok
                        else ("ext_wrong_side", {"kind": "external", "have_side": "right"}))
            return (("ready", {"kind": "external", "ext": 255, "slots": _ext_slots(_BAMBU_EXT_MAIN, "ext")}) if m_ok
                    else ("ext_wrong_side", {"kind": "external", "have_side": "left"}))
    if not reports:
        return "material_unknown_on_printer", None
    if not have:
        return "printer_empty", None
    in_ams = {_orch.norm_material(h["material"]) for h in have if h["where"] == "ams"}
    if want and want <= in_ams:
        return "ams_unmapped", None
    return "material_mismatch", None


def _qw_klipper_verdict(pid, info, ctx=None):
    """Материал для Klipper-принтера. Сверять можно только ячейки CFS у Creality K2: печать идёт из
    той ячейки, номер которой стоит в файле (T<n>), поэтому нужный материал обязан лежать именно в
    ней, а не где-нибудь в коробе. Без CFS принтер о материале не сообщает."""
    ctx = ctx if ctx is not None else {}
    reports, have = _qw_feed(pid, "klipper", ctx)
    if not reports:
        return "material_unknown_on_printer", None
    by_slot = {h["slot"]: h for h in have}
    mismatch = unknown = False
    #  16.10.2026 (R-016, R-118): цвет ячейки против цвета файла — для строки очереди и автозапуска.
    _trays = {}
    for _t in ((p_states.get(pid) or {}).get("cfs_trays") or []):
        try:
            _trays[int(_t.get("index"))] = _t
        except Exception:
            continue
    slots = []
    for n in info.get("need") or []:
        i = n.get("idx")
        if not isinstance(i, int):
            return "slot_unknown", None
        h = by_slot.get(i)
        if h is None:
            mismatch = True                     # ячейки нет или она пуста
        elif not h.get("named"):
            unknown = True                      # принтер назвал материал кодом, а не именем
        elif _orch.norm_material(h["material"]) != _orch.norm_material(n.get("material")):
            mismatch = True
        else:
            slots.append(_qw_slot_detail(n, "cfs", i, "CFS " + (h.get("label") or _gts.slot_label(i)),
                                         n.get("color"), (_trays.get(i) or {}).get("color"),
                                         rel_cache=ctx.setdefault("rel", {})))
    if mismatch:
        return "slot_mismatch", None
    if unknown:
        return "material_unknown_on_printer", None
    return "ready", {"kind": "cfs", "slots": slots}


def _qw_material_verdict(pid, ptype, info, fdata, ctx):
    """Вердикт по материалу для свободного и подходящего к файлу принтера. -> (verdict, feed)."""
    if ptype == "demo":
        #  Виртуальный принтер печатает по часам, а не филаментом (см. _compatible_pids_for):
        #  материал ему подходит любой — владелец проверяет на нём механизмы программы.
        return "ready", {"kind": "demo"}
    if ptype == "bambu":
        return _qw_bambu_verdict(pid, info, fdata, ctx)
    if ptype == "klipper":
        return _qw_klipper_verdict(pid, info, ctx)
    if ptype == "flashforge":
        return _qw_flashforge_verdict(pid, info)
    return "material_unknown_on_printer", None


def _qw_flashforge_verdict(pid, info):
    """Материал для FlashForge. 16.10.2026 (R-141).

    Заправленный материал FlashForge по сети не сообщает: поле rightFilamentType в /detail заполнено
    только во время печати и называет материал ЗАДАНИЯ (образец Adventurer 5M 3.2.7 в ff-5mp-hass#4,
    FlashNetwork.h и клиент Orca-Flashforge показывает его лишь на панели идущей печати). Поэтому
    материал здесь — слово человека, как у внешней катушки Bambu: однофиламентный файл предлагается
    только на ручной «Запустить», окно подтверждения просит проверить катушку, автозапуск такой
    принтер не берёт. Многофиламентный файл 5M/5M Pro не напечатают (одно сопло, станции нет).
    AD5X со станцией материалов (hasMatlStation) очередь не предлагает: печать из станции требует
    карты материалов в загрузке, а наша загрузка её не шлёт.
    16.10.2026 (разбор пакета): у обоих случаев — свои вердикты. Раньше станция шла как «материал не
    виден» (а станция свои ячейки сообщает и в покое), а файл на несколько филаментов — как «материал
    на внешней катушке» (у FlashForge внешней катушки в смысле Bambu нет):
      ff_station          — у принтера станция материалов, запуск из очереди с неё не поддерживается;
      single_nozzle_multi — одно сопло без станции, а в файле несколько филаментов."""
    if (p_states.get(pid) or {}).get("matl_station"):
        return "ff_station", None
    need = info.get("need") or []
    if len(need) != 1:
        return "single_nozzle_multi", None
    return "owner_check", {"kind": "unverified", "owner_check": True,
                           "slots": [_qw_slot_detail(need[0], "ext", None, "", need[0].get("color"), None)]}


def _qw_compatible(info, p):
    """Годится ли файл принтеру: формат (Bambu печатает .3mf, Klipper — g-code) и та же проверка
    модели и числа сопел, что у списка подходящих принтеров в задачах (_compatible_pids_for)."""
    ptype = str(p.get("type") or "").lower()
    if ptype == "demo":
        return True
    fmt = info.get("fmt")
    if (fmt == "3mf" and ptype in ("klipper", "creality")) or (fmt == "gcode" and ptype == "bambu"):
        return False
    tgt = info.get("target") or {}
    return p["id"] in _compatible_pids_for(tgt, tgt.get("extruders"), [p])


def _qw_match(info, fdata=None, ctx=None, prefer="", only=None):
    """Подбор принтера под файл строки очереди. -> {pid, name, reason, feed, finished, candidates, more}

    reason объясняет, почему ИМЕННО, а не «не получилось»:
      ready                    — принтер найден;
      file_missing             — файла нет на компьютере фермы;
      file_unreadable          — файл есть, но не читается (занят другой программой, не скачан с Диска);
      not_printable            — файл не нарезан;
      material_unknown         — материал файла не объявлен, строка ЖДЁТ владельца;
      not_allowed              — ни одному принтеру не разрешён запуск из очереди;
      printer_material_unknown — свободный подходящий принтер не сообщает материал;
      no_material              — свободные подходящие принтеры сообщают материал, но нужного нет
                                 там, откуда пойдёт печать;
      incompatible             — свободные принтеры есть, но файл нарезан не под них;
      busy                     — разрешённые принтеры заняты или не на связи.
    feed — откуда пойдёт печать ({"kind": ams|external|cfs|demo}); запуск обязан взять именно его.
    candidates — по каждому разрешённому принтеру (первые _QW_CAND_MAX): имя, вердикт и что он
    сообщает о материале. Среди подходящих принтер в чистом покое предпочитается закончившему или
    отменившему печать: на его столе может лежать деталь. prefer — принтер, который владелец уже
    подтвердил в окне запуска: пока он подходит, выбирается он.

    16.10.2026 (R-118): only — выбирать только из этих принтеров (автозапуск передаёт тех, у кого
    есть все три разрешения и живой жетон «Стол очищен»). Иначе подбор отдавал строку свободному
    принтеру без подтверждения, а подтверждённый так и стоял.
    16.10.2026 (R-141): запасной выбор (двухсопельный без сопел в файле, FlashForge с материалом
    «по слову человека») берётся, только когда готового принтера нет или его подтвердил владелец."""
    res = {"pid": "", "name": "", "reason": "", "feed": None, "finished": False,
           "candidates": [], "more": 0}
    info = info or {}
    state = info.get("state") or "file_missing"
    if state == "not_printable":
        res["reason"] = "not_printable"
        return res
    if state == "unreadable":
        res["reason"] = "file_unreadable"
        return res
    if state != "ok":
        res["reason"] = "file_missing"
        return res
    if not info.get("need"):
        res["reason"] = "material_unknown"
        return res
    ctx = ctx or _qw_ctx()
    allowed = [pid for pid in sorted(ctx["allowed"]) if pid in ctx["fleet"]
               and (only is None or pid in only)]
    if not allowed:
        res["reason"] = "not_allowed"
        return res
    cands, idle, finish, preferred = [], None, None, None
    #  16.10.2026 (R-115): двухсопельный без сопел в файле — запасной выбор, только ручной запуск.
    u_idle, u_finish, u_preferred = None, None, None
    for pid in allowed:
        p = ctx["fleet"][pid]
        ptype = str(p.get("type") or "").lower()
        _reports, have = _qw_feed(pid, ptype, ctx)
        c = {"id": pid, "name": p.get("name") or pid, "verdict": "", "finished": False,
             "status": str((p_states.get(pid) or {}).get("status") or "").upper(),
             "stage": _bstart._int_or_none((p_states.get(pid) or {}).get("stage")),
             "have": [{"where": h["where"], "label": h["label"], "material": h["material"]}
                      for h in have[:8]]}
        #  16.10.2026 (R-137): двухсопельный Bambu — интерфейс называет внешнюю 255 «правой».
        try:
            c["dual"] = ptype == "bambu" and int((p_states.get(pid) or {}).get("nozzle_count") or 1) >= 2
        except Exception:
            c["dual"] = False
        if pid not in ctx.setdefault("busy", {}):
            ctx["busy"][pid] = _qw_busy_verdict(pid, ptype, ctx)
        busy = ctx["busy"][pid]
        if busy:
            c["verdict"] = busy
            #  16.10.2026 (R-138, проверка пакета): чем именно занят Bambu — словами запуска, а не «стадия N».
            if busy == "working_stage" and ptype == "bambu":
                _bw = _qw_busy_words(pid)
                if _bw:
                    c["busy_ru"], c["busy_en"] = _bw["ru"], _bw["en"]
        elif not _qw_compatible(info, p):
            c["verdict"] = "incompatible"
        else:
            verdict, feed = _qw_material_verdict(pid, ptype, info, fdata, ctx)
            c["verdict"] = verdict
            if verdict == "ext_wrong_side":
                c["ext_side"] = (feed or {}).get("have_side") or ""
            if verdict in ("ready", "dual_nozzle_unverified", "owner_check"):
                raw = str((p_states.get(pid) or {}).get("status_raw") or "")
                c["finished"] = c["status"] == "FINISH" or raw in _QW_BED_RAW.get(ptype, ())
                pick = (pid, c["name"], feed, c["finished"])
                if verdict == "ready":
                    if pid == prefer:
                        preferred = pick
                    if c["finished"]:
                        finish = finish or pick
                    else:
                        idle = idle or pick
                else:
                    if pid == prefer:
                        u_preferred = pick
                    if c["finished"]:
                        u_finish = u_finish or pick
                    else:
                        u_idle = u_idle or pick
        cands.append(c)
    cands.sort(key=lambda x: (_QW_VERDICT_ORDER.get(x["verdict"], 9), str(x["name"])))
    res["candidates"] = cands[:_QW_CAND_MAX]
    res["more"] = max(0, len(cands) - _QW_CAND_MAX)
    #  16.10.2026 (R-141): принтер, который владелец подтвердил сам (prefer), идёт раньше чужого
    #  готового, даже если его материал проверяет человек: в окне он этот принтер и выбрал.
    pick = preferred or (None if u_preferred else (idle or finish))
    if not pick:
        pick = u_preferred or u_idle or u_finish
        res["unverified"] = bool(pick)
    if pick:
        res.update({"pid": pick[0], "name": pick[1], "reason": "ready", "feed": pick[2],
                    "finished": pick[3]})
        return res
    verdicts = {c["verdict"] for c in cands}
    if "material_unknown_on_printer" in verdicts:
        res["reason"] = "printer_material_unknown"
    elif verdicts & set(_QW_MISMATCH):
        res["reason"] = "no_material"
    elif verdicts & set(_QW_UNFIT):
        res["reason"] = "incompatible"
    else:
        res["reason"] = "busy"
    return res


def _qw_public(d, info, m):
    """Строка очереди для интерфейса: живые материалы файла и подбор с объяснением. Адресов,
    кодов доступа и серийных номеров здесь нет — только имена принтеров и материалы."""
    info = info or {}
    tgt = info.get("target") or {}
    stored = [x for x in str(d.get("material") or "").split(",") if x]
    d.update({
        #  Материал из базы — только запасной показ, если файла на этом компьютере нет.
        "material": ",".join(_qw_mats(info) if info.get("state") == "ok" else stored),
        "material_source": info.get("source") or "",
        "file_state": info.get("state") or "",
        "file_why": info.get("why") or "",
        "file_model": tgt.get("model_raw") or tgt.get("model") or "",
        "match_printer_id": m["pid"], "match_printer_name": m["name"],
        "match_reason": m["reason"], "match_feed": (m.get("feed") or {}).get("kind") or "",
        "match_finished": bool(m.get("finished")),
        #  16.10.2026 (R-137, R-115): какая внешняя катушка (254 левая, 255 правая у H2D) и подбор без
        #  проверки сопла (двухсопельный, сопло в файле не видно) — только ручной запуск.
        "match_ext": (m.get("feed") or {}).get("ext"),
        "match_unverified": bool(m.get("unverified")),
        #  16.10.2026 (R-016): куда пойдёт каждый филамент — слот или внешняя катушка, цвет файла и
        #  цвет катушки, их отношение и вариант материала. Только материалы и цвета, ничего о сети.
        "match_slots": [{k: s.get(k) for k in ("material", "where", "label", "file_color", "slot_color",
                                               "rel", "variant", "file_fid", "slot_fid")}
                        for s in ((m.get("feed") or {}).get("slots") or [])[:16]],
        "candidates": m["candidates"], "candidates_more": m["more"],
    })
    return d


#  ══ 16.09.2026: АВТОЗАПУСК ОЧЕРЕДИ ОЖИДАНИЯ ══════════════════════════════════════════════
#  Решение владельца: печать из очереди может уходить САМА, но только когда человек подтвердил,
#  что стол пуст. Доказать пустой стол иначе нечем: датчика занятости стола нет ни у одной
#  поддерживаемой марки (проверено по источникам 16.09.2026 — ни Bambu, ни Klipper, ни
#  FlashForge такого поля не сообщают). Подтверждение — ТОТ ЖЕ одноразовый жетон, что и у
#  «Печатать весь проект» (plate_clearances): второго механизма разрешения в программе нет.
#  Автомат не имеет своего пути печати: найдя строку, он отдаёт её в _qw_launch_claimed —
#  ровно тот код, который выполняет кнопка владельца, со всеми его проверками.
_QW_AUTO_TICK = 5.0            # как часто смотрим очередь
_QW_AUTO_FAILS_MAX = 3         # столько неудач подряд по одной строке — и она «требует внимания»
_qw_auto_fails = {}            # id строки -> сколько раз подряд запуск не состоялся
#  16.09.2026: строки, запуск которых начал АВТОМАТ и чей исход ещё не пришёл. Нужен, чтобы
#  правило «три неудачи подряд» не считало РУЧНЫЕ попытки владельца: он нажимает сам, причину
#  видит сам, и его строка не должна уходить «требует внимания» после трёх нажатий.
_qw_auto_inflight = set()
#  Когда автомат запускал в последний раз — чтобы выдерживать общефермовый интервал
#  поэтапного запуска (настройка stagger_sec). Одного запуска за проход мало: проход идёт
#  каждые пять секунд, а владелец мог попросить разносить старты на минуту и больше.
_qw_auto_last = [0.0]


def _qw_auto_enabled():
    """Включён ли автозапуск на ферме и каким принтерам он разрешён -> (вкл, множество id).
    Пустой список = никому. Отметка принтера queue_allowed согласием на автомат НЕ является:
    она давалась под обещание в интерфейсе «Печать начинается по вашему подтверждению»."""
    #  16.09.2026: читаем СВОЙ ключ напрямую. Общее чтение настроек фермы делает семь запросов
    #  к базе, а этот проход идёт каждые пять секунд — в том числе когда автозапуск выключен.
    try:
        with lock_p:
            row = conn_p.execute("SELECT value FROM app_settings WHERE key=?",
                                 ("farm_queue_auto_start",)).fetchone()
        val = "" if row is None else str(row["value"] if not isinstance(row, tuple) else row[0])
        if val != "1":
            return False, set()
        return True, {str(x) for x in (_farm_auto_start_read() or [])}
    except Exception:
        log.debug("[QUEUE-AUTO] settings read failed: %s", _exc_brief())
        return False, set()


def _qw_auto_gap():
    """Сколько секунд автомат обязан выждать между СВОИМИ запусками. 0 — интервал выключен.
    Настройка та же, что у поэтапного запуска пачкой: владелец задаёт её один раз на ферму."""
    try:
        with lock_p:
            rows = conn_p.execute(
                "SELECT key, value FROM app_settings WHERE key IN (?,?)",
                ("farm_stagger_on", "farm_stagger_sec")).fetchall()
        vals = {}
        for _r in rows:
            _k = _r["key"] if not isinstance(_r, tuple) else _r[0]
            _v = _r["value"] if not isinstance(_r, tuple) else _r[1]
            vals[str(_k)] = str(_v or "")
        if vals.get("farm_stagger_on") != "1":
            return 0.0
        return max(0.0, min(600.0, float(int(vals.get("farm_stagger_sec") or 0))))
    except Exception:
        log.debug("[QUEUE-AUTO] stagger read failed: %s", _exc_brief())
        return 0.0


def _qw_auto_mark(rid, state, note):
    """Пометить строку, которую автомат ЗАНЯЛ или вернул. Условие по состоянию обязательно:
    решение человека автомат не перетирает."""
    try:
        with lock_pr:
            conn_pr.execute("UPDATE queue_wait SET state=?, note=?, updated_at=? "
                            "WHERE id=? AND state IN ('waiting','starting')",
                            (state, note, time.time(), rid))
            conn_pr.commit()
    except Exception:
        log.debug("[QUEUE-AUTO] mark failed: %s", _exc_brief())


def _qw_auto_bump(rid, reason):
    """Неудача автозапуска по строке. Три подряд — строка уходит «требует внимания» с причиной.
    Считается именно ИСХОД: раньше счётчик обнулялся на постановке в очередь, и обещанные три
    неудачи не наступали никогда — строка молча пробовалась каждые пять секунд."""
    rid = str(rid or "")
    if not rid:
        return
    n = _qw_auto_fails.get(rid, 0) + 1
    _qw_auto_fails[rid] = n
    if n >= _QW_AUTO_FAILS_MAX:
        _qw_auto_fails.pop(rid, None)
        #  Причина хранится КОДОМ: строку очереди читает и русский, и английский интерфейс.
        _qw_auto_mark(rid, "attention", "auto_failed:" + str(reason or "")[:80])


def _qw_auto_ok(rid):
    """Запуск состоялся — счётчик неудач этой строки забываем."""
    _qw_auto_fails.pop(str(rid or ""), None)


#  16.10.2026 (R-008, R-118): склад отказал строке на этом принтере — следующий раз спрашиваем не
#  раньше чем через столько секунд. Проверка читает файл и зовёт хуки модулей, а проход идёт каждые
#  пять секунд: без паузы журнал фермы заполнялся бы одной и той же строкой.
_QW_AUTO_STOCK_RETRY_S = 60.0
_qw_auto_stock_low = {}        # (id строки, принтер) -> (когда склад отказал, код пометки)


def _qw_auto_needs_human(m):
    """Может ли АВТОМАТ взять подобранный принтер или строке нужен человек. 16.10.2026 (R-118).
    -> '' (можно) или код причины; строка получает пометку «auto_needs_human:<код>».

    Автозапуск — только при ДОКАЗАННОЙ подаче и ТОЧНОМ цвете каждого филамента: то же правило, что
    «готово» у плана «Печатать весь проект» (там настройка катушки и близкий цвет требуют согласия
    человека, R-116). Коды:
      owner_check    — FlashForge: материал по сети не виден, проверяет человек (R-141);
      dual_nozzle    — двухсопельный принтер, сопло в файле не видно (R-115);
      external       — внешняя катушка: материал выбран на экране принтера, датчика наличия нет;
      no_sensor      — слот AMS не подтверждён датчиком подачи (tray_exist_bits);
      variant        — другой вариант материала (GFA01 Matte вместо GFA00 Basic, R-115);
      color_mismatch / color_close / color_unknown — цвет совпадает не точно;
      feed_unproven  — откуда пойдёт печать, не доказано.
    Виртуальный принтер (demo) печатает по часам и материала не тратит — ему можно."""
    feed = m.get("feed") or {}
    kind = str(feed.get("kind") or "")
    if kind == "demo":
        return ""
    if kind == "unverified" or feed.get("owner_check"):
        return "owner_check"
    if m.get("unverified") or feed.get("unverified"):
        return "dual_nozzle"
    if kind == "external":
        return "external"
    slots = feed.get("slots") or []
    if kind not in ("ams", "cfs") or not slots:
        return "feed_unproven"
    if kind == "ams" and not all(s.get("sensor") is True for s in slots):
        return "no_sensor"
    if any(s.get("variant") for s in slots):
        return "variant"
    rels = [s.get("rel") for s in slots]
    if _orch.REL_MISMATCH in rels:
        return "color_mismatch"
    if _orch.REL_CLOSE in rels:
        return "color_close"
    if any(r != _orch.REL_EXACT for r in rels):
        return "color_unknown"
    return ""


def _qw_item(rid, r, pid, name, feed_kind, skip_filament=False):
    """Элемент очереди запусков для строки ожидания — один и тот же у кнопки, у автомата и у
    проверки склада перед тратой жетона (иначе склад проверял бы не то, что потом уйдёт)."""
    item = {"printer_id": pid, "printer_name": name or _qw_printer_name(pid), "flow": "quick",
            "gcode_file": r["gcode_file"], "source": r["source"] or "quick",
            "part_name": r["part_name"] or "", "qw_id": rid}
    if feed_kind == "external":
        #  Подбор доказал материал на внешней катушке — печатать нужно именно с неё. Без явного -1
        #  запуск «Авто» у принтера с AMS взял бы слоты AMS, где нужного материала нет.
        item["ams_slot"] = -1
    if skip_filament:
        #  16.10.2026 (R-008): решение владельца «Печатать всё равно» из окна «Материал закончился» —
        #  склад перед постановкой и при старте не переспрашивается (как у остальных путей запуска).
        item["skip_filament"] = True
    return item


def _qw_auto_note(r, note):
    """Пометка строки, которую автомат НЕ взял, — кодом. Пишется, только если изменилась: проход идёт
    каждые пять секунд, а строк в очереди может быть много."""
    if str(r.get("note") or "") != note:
        _qw_auto_mark(str(r["id"]), "waiting", note)


def _qw_auto_stock(r, pid, m):
    """Пропустит ли склад этот запуск — ДО траты жетона «Стол очищен». 16.10.2026 (R-008, R-118).
    -> '' (пропустит) или код пометки строки.

    Раньше жетон тратился до постановки, а склад отказывал уже при постановке: подтверждение
    человека пропадало, неудача засчитывалась, а владелец видел строку без причины. Проверка — та
    же, что делает очередь запусков при постановке (_enqueue_preflight), по тому же элементу. Fail-open,
    как и там: сбой самой проверки запуск не останавливает — постановка проверит ещё раз."""
    key = (str(r["id"]), pid)
    now = time.time()
    for _k in [k for k, t in _qw_auto_stock_low.items() if now - t[0] >= _QW_AUTO_STOCK_RETRY_S]:
        _qw_auto_stock_low.pop(_k, None)
    if key in _qw_auto_stock_low:
        #  16.10.2026 (разбор пакета): в паузе возвращается ТА ЖЕ причина, что дал склад: раньше
        #  запоминалось только время, и отказ «катушка не привязана» на втором проходе превращался в
        #  «не хватает материала».
        return _qw_auto_stock_low[key][1]
    item = _qw_item(str(r["id"]), r, pid, m.get("name"), (m.get("feed") or {}).get("kind") or "")
    try:
        _ok_items, blocked, _notes = _enqueue_preflight([item])
    except Exception:
        log.debug("[QUEUE-AUTO] stock check failed: %s", _exc_brief())
        return ""
    if not blocked:
        return ""
    _st = str((blocked[0] or {}).get("status") or "")
    code = "auto_low_filament" if _st == "low_filament" else "auto_needs_human:stock"
    _qw_auto_stock_low[key] = (now, code)
    log.info("[QUEUE-AUTO] %s -> %s: склад не пропускает запуск (%s) — подтверждение «Стол очищен» "
             "не тронуто" % (r["gcode_file"], m.get("name") or pid, _st or "block"))
    return code


def _qw_auto_tick():
    """Один проход автозапуска. Сам ничего не печатает и не резервирует.

    Правила — каждое закрывает щель, найденную разбором 16.09.2026:
      * выключатель фермы и список принтеров: согласие владельца, по умолчанию выключено;
      * строки «требует внимания» автомат НЕ трогает — их исход неясен, решает человек;
      * пока не разобраны запуски, прерванные перезапуском (recovery_hold), автомат молчит;
      * принтер обязан быть свободен по ТОМУ ЖЕ подбору, что и у кнопки, и разрешён к запуску
        из очереди (queue_allowed), и стоять в списке автозапуска;
      * жетон «Стол очищен» нужен ВСЕГДА (а не только после печати), и он тратится ДО
        отправки: потерянный жетон безопаснее лишней печати на занятый стол;
      * не больше одного старта за проход, и между своими запусками автомат выдерживает
        общефермовый интервал поэтапного запуска.
    16.10.2026 (R-118, R-008):
      * выбор идёт ТОЛЬКО среди принтеров, где есть все три разрешения и живой жетон; нет таких —
        проход заканчивается, не читая файлов;
      * автомат берёт принтер только с доказанной подачей и точным цветом (_qw_auto_needs_human);
        иначе строка ждёт ручного «Запустить» с пометкой, почему;
      * склад спрашивается ДО траты жетона: не пропускает на этом принтере — его жетон остаётся,
        и берётся следующий подтверждённый; не подошёл никто — строка ждёт с пометкой.
    """
    on, allowed_auto = _qw_auto_enabled()
    if not on or not allowed_auto:
        return
    _gap = _qw_auto_gap()
    if _gap and (time.time() - _qw_auto_last[0]) < _gap:
        return                      # интервал между стартами задан владельцем — выдерживаем
    try:
        with lock_pr:
            _held = conn_pr.execute("SELECT COUNT(*) AS c FROM print_launch_queue "
                                    "WHERE status='recovery_hold'").fetchone()["c"]
            rows = [dict(r) for r in conn_pr.execute(
                "SELECT * FROM queue_wait WHERE state='waiting' ORDER BY created_at").fetchall()]
    except Exception:
        log.debug("[QUEUE-AUTO] read failed: %s", _exc_brief())
        return
    if _held or not rows:
        return                      # не убедились, что всё разобрано — не запускаем ничего
    ctx = _qw_ctx()
    #  16.10.2026 (R-118): принтеры, на которые автомат вообще может пойти: выключатель + список
    #  автозапуска + отметка «запуск из очереди» + живой жетон «Стол очищен». Раньше подбор шёл по всем
    #  разрешённым и отдавал строку первому свободному — подтверждённый принтер печать не получал, пока
    #  подходил другой, без подтверждения или без права на автомат.
    eligible = set()
    for _pid in sorted(allowed_auto & set(ctx["allowed"])):
        try:
            if _orch.active_clearance(_pid):
                eligible.add(_pid)
        except Exception:
            log.debug("[QUEUE-AUTO] clearance read failed: %s", _exc_brief())
    if not eligible:
        return                      # подтверждённых столов нет — файлы не читаем вовсе
    for r in rows:
        rid = str(r["id"])
        #  Файл читаем через кэш: сам запуск всё равно перечитает его заново (fresh=True).
        info, fdata = _qw_file_info(r["gcode_file"], r["part_name"] or "")
        #  Подобранный принтер автомату не годится (внешняя катушка, цвет не точный…) — смотрим
        #  следующий из подтверждённых: годный, но стоящий в списке позже, тоже должен получить печать.
        #  16.10.2026 (R-008, R-118, разбор пакета): склад спрашивается ВНУТРИ этого перебора, до траты
        #  жетона. Раньше он спрашивался после выбора и только у выбранного: подбор детерминирован, и
        #  принтер, которому по складу не хватает, выигрывал каждый проход, а второй подтверждённый
        #  принтер с полной катушкой печать не получал никогда. Пометка строки пишется, только если не
        #  подошёл НИ ОДИН принтер, — первая встреченная причина.
        pool, m, first_note = set(eligible), None, ""
        while pool:
            m = _qw_match(info, fdata, ctx, only=pool)
            pid = str(m.get("pid") or "")
            if not pid or pid not in pool:
                m = None
                break
            _why = _qw_auto_needs_human(m)
            _note = ("auto_needs_human:" + _why) if _why else _qw_auto_stock(r, pid, m)
            if not _note:
                break
            first_note = first_note or _note
            pool.discard(pid)
            m = None
        if m is None:
            if first_note:
                _qw_auto_note(r, first_note)
            continue
        pid = str(m["pid"])
        #  16.09.2026, состязательная проверка нашла дыру: жетон «Стол очищен» спрашивался
        #  ТОЛЬКО когда программа видела завершение печати. Но на столе может лежать что
        #  угодно, чего программа своей печатью не видела: деталь, напечатанная с флешки при
        #  выключенном сервере, калибровочный отпечаток, оснастка, магнит. Принтер при этом
        #  просто «в покое», и печать уходила поверх без слова человека. Инвариант записан в
        #  самом коде жетонов: IDLE/FINISH/RUNNING не означают пустой стол. Поэтому жетон
        #  нужен ВСЕГДА; подтвердить принтер в покое владелец может — маршрут принимает
        #  первичный вид подтверждения (там требуется safe_idle).
        clr = _orch.active_clearance(pid)
        if not clr:
            continue
        #  16.10.2026 (R-008): склад уже спрошен в переборе выше — ДО траты жетона.
        try:
            with lock_pr:
                _cl = conn_pr.execute("UPDATE queue_wait SET state='starting', updated_at=? "
                                      "WHERE id=? AND state='waiting'", (time.time(), rid))
                conn_pr.commit()
        except Exception:
            log.debug("[QUEUE-AUTO] claim failed: %s", _exc_brief())
            continue
        if _cl.rowcount != 1:
            continue                # строку забрал человек или другой проход
        #  Дальше строка уже ЗАНЯТА. Любая ошибка обязана вернуть её владельцу: иначе строка
        #  застревает навсегда — её не запустить и не удалить (удаление отказывает, пока
        #  состояние 'starting'), и лечится это только перезапуском программы.
        try:
            #  «qw:» — чтобы запись сама себя объясняла: в эту колонку проектный путь пишет
            #  id детали плана, а здесь расходует жетон СТРОКА ОЧЕРЕДИ.
            if not _orch.consume_clearance(clr["id"], "qw:" + rid):
                #  Жетон истратили между проверкой и тратой — печать НЕ уходит.
                _qw_auto_mark(rid, "waiting", "auto_clearance_used")
                continue
            res = _qw_launch_claimed(rid, r, pid, auto=True) or {}
        except Exception:
            log.error("[QUEUE-AUTO] запуск прерван исключением: %s (строка возвращена в очередь)"
                      % _exc_brief())
            _qw_auto_mark(rid, "waiting", "auto_exception")
            return
        if res.get("ok"):
            #  Это ещё НЕ успех печати, а принятая постановка в очередь запусков. Настоящий
            #  исход придёт позже от воркера — там и считается счётчик неудач.
            _qw_auto_inflight.add(rid)
            _qw_auto_last[0] = time.time()
            log.info("[QUEUE-AUTO] автозапуск: %s -> %s" % (r["gcode_file"], res.get("printer_name") or pid))
        else:
            _qw_auto_bump(rid, str(res.get("error") or ""))
        return                      # не больше одного старта за проход


async def _qw_auto_loop():
    """Фоновый проход автозапуска. Fail-open: ошибка прохода печать не трогает."""
    while True:
        await asyncio.sleep(_QW_AUTO_TICK)
        try:
            #  16.09.2026: в отдельный поток. Проход читает файл печати (и делает это дважды —
            #  подбор и проверка склада), а на цикле событий это останавливало ВСЮ программу:
            #  живые состояния принтеров, интерфейс и воркер очереди запусков.
            await asyncio.to_thread(_qw_auto_tick)
        except Exception:
            log.debug("[QUEUE-AUTO] tick error: %s", _exc_brief())


@app.get("/api/queue-wait")
def api_queue_wait_get():
    """Очередь ожидания вместе с ЖИВЫМ подбором принтера для каждой строки. Только чтение:
    ничего не запускает и ничего не резервирует. Материалы файла читаются живыми (с кэшем по
    времени изменения файла) — перенарезанный файл виден без повторного добавления в очередь."""
    try:
        with lock_pr:
            rows = conn_pr.execute("SELECT * FROM queue_wait WHERE state != 'done' "
                                   "ORDER BY created_at").fetchall()
        ctx = _qw_ctx()
        out = []
        for r in rows:
            d = _qw_row(r)
            info, _fdata = _qw_file_info(d["gcode_file"], d.get("part_name") or "")
            out.append(_qw_public(d, info, _qw_match(info, None, ctx)))
        #  16.09.2026: какие принтеры ЖДУТ подтверждения «Стол очищен». Печать закончилась
        #  или была отменена — на столе может лежать деталь, и автозапуск туда не пойдёт,
        #  пока человек не нажмёт кнопку. Датчика занятости стола нет ни у одной марки,
        #  доказательство только одно — слово человека. Отдельного маршрута не заводим:
        #  это та же очередь, тот же опрос.
        wait = []
        for _pid, _p in (ctx.get("fleet") or {}).items():
            if _pid not in ctx["allowed"]:
                continue              # запуск из очереди не разрешён — подтверждать нечего
            _ptype = str(_p.get("type") or "").lower()
            if _qw_busy_verdict(_pid, _ptype, ctx):
                continue              # занят или не на связи — подтверждение всё равно отобьют
            try:
                if _orch.active_clearance(_pid):
                    continue          # уже подтверждено — ждать нечего
            except Exception:
                log.debug("[QUEUE-WAIT] clearance read failed: %s", _exc_brief())
                continue
            #  16.09.2026: ждут подтверждения ВСЕ свободные принтеры очереди без живого жетона,
            #  а не только те, у кого программа видела завершение печати: на столе может лежать
            #  деталь, которую программа своей печатью не видела. finished — только для текста
            #  («была печать» против «подтвердите, что стол пуст»).
            _st = p_states.get(_pid) or {}
            _fin = (str(_st.get("status") or "").upper() == "FINISH"
                    or str(_st.get("status_raw") or "") in _QW_BED_RAW.get(_ptype, ()))
            wait.append({"id": _pid, "name": _p.get("name") or _pid, "finished": bool(_fin)})
        return {"ok": True, "items": out, "allowed": sorted(ctx["allowed"]),
                "plate_wait": sorted(wait, key=lambda x: str(x["name"]))}
    except Exception:
        log.debug("[QUEUE-WAIT] list failed: %s", _exc_brief())
        return {"ok": False, "items": [], "allowed": []}


@app.post("/api/queue-wait/add")
def api_queue_wait_add(data: Dict[str, Any]):
    """Поставить файл в очередь ожидания. Материал файла подбор читает заново при каждом опросе;
    в базу он пишется только для показа на случай, если файла на компьютере не окажется.
    Не нарезанный файл в очередь не ставится: печатать его нечем, а строка висела бы без толку."""
    fname = str((data or {}).get("gcode_file") or "").strip()
    if not fname:
        return {"ok": False, "error": "no_file"}
    part = str((data or {}).get("part_name") or "")
    src = str((data or {}).get("source") or "quick")
    info, _fdata = _qw_file_info(fname, part, fresh=True)
    if info.get("state") == "not_printable":
        return {"ok": False, "error": "not_printable"}
    mats = _qw_mats(info)
    now = time.time()
    rid = _uid("qw_")
    try:
        with lock_pr:
            conn_pr.execute("INSERT INTO queue_wait (id, gcode_file, source, part_name, material, "
                            "state, note, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?)",
                            (rid, fname, src, part, ",".join(mats), "waiting", "", now, now))
            conn_pr.commit()
    except Exception:
        log.debug("[QUEUE-WAIT] add failed: %s", _exc_brief())
        return {"ok": False, "error": "db"}
    m = _qw_match(info)
    return {"ok": True, "id": rid, "material": mats,
            "match_printer_id": m["pid"], "match_printer_name": m["name"],
            "match_reason": m["reason"]}


@app.post("/api/queue-wait/remove")
def api_queue_wait_remove(data: Dict[str, Any]):
    """Убрать строку из очереди ожидания."""
    rid = str((data or {}).get("id") or "")
    if not rid:
        return {"ok": False, "error": "no_id"}
    try:
        with lock_pr:
            #  16.09.2026: строку, которая прямо сейчас запускается, убрать нельзя: запуск от этого
            #  не отменится, а строка исчезла бы — и владелец не узнал бы, чем дело кончилось.
            #  Отменять запуск нужно в очереди запусков, там же строка вернётся в ожидание.
            _r = conn_pr.execute("SELECT state FROM queue_wait WHERE id=?", (rid,)).fetchone()
            if _r and str(_r["state"] or "") in ("starting", "launching"):
                return {"ok": False, "error": "launching"}
            conn_pr.execute("DELETE FROM queue_wait WHERE id=?", (rid,))
            conn_pr.commit()
        return {"ok": True}
    except Exception:
        log.debug("[QUEUE-WAIT] remove failed: %s", _exc_brief())
        return {"ok": False, "error": "db"}


@app.post("/api/queue-wait/start")
def api_queue_wait_start(data: Dict[str, Any]):
    """ПОДТВЕРЖДЁННЫЙ владельцем запуск строки ожидания.

    Подбор перепроверяется ЗАНОВО (между показом и нажатием принтер мог занять кто-то другой),
    и запуск уходит в СУЩЕСТВУЮЩУЮ очередь запусков — со всеми её проверками. Своего пути
    старта печати здесь нет намеренно."""
    rid = str((data or {}).get("id") or "")
    if not rid:
        return {"ok": False, "error": "no_id"}
    try:
        with lock_pr:
            r = conn_pr.execute("SELECT * FROM queue_wait WHERE id=?", (rid,)).fetchone()
    except Exception:
        log.debug("[QUEUE-WAIT] start read failed: %s", _exc_brief())
        return {"ok": False, "error": "db"}
    if not r:
        return {"ok": False, "error": "not_found"}
    #  2.978: строку занимаем АТОМАРНО. Список ожидания виден на всех компьютерах фермы; двое
    #  операторов нажимали «Запустить» почти одновременно, и один и тот же файл уходил на два
    #  принтера (второй запрос читал строку, не глядя на её состояние). Занять может только
    #  один: у остальных rowcount==0.
    try:
        with lock_pr:
            #  16.09.2026: запустить можно и строку, помеченную «требует внимания» (прошлый запуск
            #  оборвался неясно) — решает владелец, окно подтверждения его предупредит. Занять
            #  строку по-прежнему может только один: у остальных rowcount==0.
            _cl = conn_pr.execute("UPDATE queue_wait SET state='starting', updated_at=? "
                                  "WHERE id=? AND state IN ('waiting','attention')", (time.time(), rid))
            conn_pr.commit()
        if _cl.rowcount != 1:
            return {"ok": False, "error": "already_started"}
    except Exception:
        log.debug("[QUEUE-WAIT] claim failed: %s", _exc_brief())
        return {"ok": False, "error": "db"}

    #  16.10.2026 (R-008): {skip_filament: true} — владелец выбрал «Печатать всё равно» в окне
    #  «Материал закончился» (остаток катушки окно уже списало). Только явное true, и только у кнопки:
    #  автомат так не умеет.
    return _qw_launch_claimed(rid, r, str((data or {}).get("printer_id") or ""),
                              skip_filament=((data or {}).get("skip_filament") is True))


def _qw_launch_claimed(rid, r, want_pid="", auto=False, skip_filament=False):
    """Общий путь запуска ПОСЛЕ атомарного захвата строки: перечитать файл, пересчитать подбор,
    поставить в очередь запусков, вернуть исход.

    Вынесено 16.09.2026 из api_queue_wait_start, чтобы автозапуск пользовался ТЕМ ЖЕ кодом, что и
    запуск по кнопке владельца: второго пути старта печати в программе нет, и заводить его нельзя.
    Поведение не изменено — это перенос как есть. Захват строки (атомарный UPDATE) остаётся
    у вызывающего: он решает, из какого состояния строку брать."""
    def _qw_release(why=""):
        """Вернуть строку в ожидание: запуск не состоялся, она снова доступна владельцу.
        16.10.2026 (R-117): вместе с причиной КОДОМ («not_started:<код>»). Раньше в строке оставалось
        «запускается на X» от прошлой попытки, и владелец не видел, почему запуска не было."""
        try:
            with lock_pr:
                conn_pr.execute("UPDATE queue_wait SET state='waiting', note=?, updated_at=? WHERE id=?",
                                ("not_started:" + str(why or ""), time.time(), rid))
                conn_pr.commit()
        except Exception:
            log.debug("[QUEUE-WAIT] release failed: %s", _exc_brief())

    #  15.09.2026: файл перечитывается перед подбором, материалы из базы не используются — между
    #  добавлением и запуском файл могли перенарезать. Раскладка по AMS проверяется самим подбором
    #  запуска по байтам файла, а не зеркалом из опроса.
    info, fdata = _qw_file_info(r["gcode_file"], r["part_name"] or "", fresh=True)
    m = _qw_match(info, fdata, None, prefer=want_pid)
    if not m["pid"]:
        _qw_release(m["reason"])
        return {"ok": False, "error": m["reason"], "candidates": m["candidates"]}
    pid = m["pid"]
    if want_pid and pid != want_pid:
        #  Владелец подтверждал запуск на конкретном принтере, а тот за это время занялся или
        #  перестал подходить. На другой принтер без его подтверждения печать не отправляется.
        _qw_release("printer_changed")
        return {"ok": False, "error": "printer_changed", "printer_name": m["name"]}
    if m.get("unverified") and not (want_pid and pid == want_pid):
        #  16.10.2026 (R-141): запасной выбор (FlashForge — материал проверяет человек; двухсопельный без
        #  сопел в файле) уходит только на принтер, который владелец подтвердил в окне сам.
        _qw_release("printer_changed")
        return {"ok": False, "error": "printer_changed", "printer_name": m["name"]}
    if auto:
        #  16.10.2026 (R-118, R-115): автомат перепроверяет по свежему файлу то же, что проход: только
        #  доказанная подача и точный цвет. Иначе строка ждёт человека.
        _why = _qw_auto_needs_human(m)
        if _why:
            _qw_release("auto_needs_human:" + _why)
            return {"ok": False, "error": ("dual_nozzle_unverified" if _why == "dual_nozzle"
                                           else "auto_needs_human:" + _why)}
    feed = (m.get("feed") or {}).get("kind") or ""
    item = _qw_item(rid, r, pid, m["name"], feed, skip_filament=(skip_filament and not auto))
    now = time.time()
    try:
        with lock_pr:
            #  16.09.2026: строка НЕ закрывается здесь. Она ждёт исхода очереди запусков: не дошло
            #  до отправки — вернётся в ожидание с причиной; отправка ушла — закроется; неясный
            #  исход — «требует внимания» (см. _qw_launch_outcome).
            #  Пометка ставится ДО постановки в очередь: воркер очереди живёт в своём потоке и может
            #  вернуть исход раньше, чем сюда дошла бы запись, — тогда исход писать было бы некуда,
            #  и строка осталась бы «запускается» навсегда. Не удалась постановка — _qw_release
            #  возвращает строку в ожидание.
            #  16.10.2026 (R-137): сторона внешней катушки двухсопельного — в пометке строки. Запуск идёт
            #  с ams_slot=-1: сторону запуск заново читает из байтов файла (_bambu_ext_choice).
            _xe = (m.get("feed") or {}).get("ext")
            #  16.10.2026 (R-141, разбор пакета): у FlashForge (подача «unverified») запасной выбор — не
            #  двухсопельный: у него одно сопло, а материал проверяет человек. Пометка — по виду подачи.
            _side_note = (" (левая внешняя катушка)" if _xe == 254 else
                          " (правая внешняя катушка)" if _xe == 255 else
                          " (материал проверил человек)" if feed == "unverified" else
                          " (двухсопельный: сопло не проверено)" if m.get("unverified") else "")
            conn_pr.execute("UPDATE queue_wait SET state='launching', note=?, updated_at=? WHERE id=?",
                            ("запускается на " + str(item["printer_name"]) + _side_note, now, rid))
            conn_pr.commit()
    except Exception:
        log.debug("[QUEUE-WAIT] start mark failed: %s", _exc_brief())
    resp = api_print_queue_enqueue({"items": [item], "interval": 1})
    queued = (resp or {}).get("queued") or []
    if not queued:
        _blk = [b for b in ((resp or {}).get("blocked") or []) if isinstance(b, dict)]
        _qw_release(str((_blk[0].get("status") if _blk else "") or "enqueue_rejected"))
        return {"ok": False, "error": "enqueue_rejected", "enqueue": resp}
    return {"ok": True, "printer_id": pid, "printer_name": item["printer_name"], "feed": feed,
            "finished": bool(m.get("finished")), "enqueue": resp}


@app.post("/api/printer/queue-allowed")
def api_printer_queue_allowed(data: Dict[str, Any]):
    """Разрешить или запретить конкретному принтеру запуск из очереди. По умолчанию запрещено."""
    pid = str((data or {}).get("printer_id") or "")
    val = 1 if (data or {}).get("allowed") else 0
    if not pid:
        return {"ok": False, "error": "no_id"}
    try:
        with lock_pr:
            conn_pr.execute("UPDATE printers SET queue_allowed=? WHERE id=?", (val, pid))
            conn_pr.commit()
        return {"ok": True, "printer_id": pid, "allowed": bool(val)}
    except Exception:
        log.debug("[QUEUE-WAIT] flag failed: %s", _exc_brief())
        return {"ok": False, "error": "db"}


#  16.09.2026: подтверждение «Стол очищен» ВНЕ проектного запуска — для очереди ожидания и
#  автозапуска. Раньше эта кнопка жила только внутри «Печатать весь проект»: и маршрут, и вызов из
#  интерфейса требовали активного проекта, поэтому в очереди вместо запрета стоял текст «убедитесь,
#  что стол пуст». Механизм подтверждения НЕ дублируется: это тот же одноразовый жетон, та же
#  единственная точка создания (_orch.create_clearance), тот же сторож гашения.
@app.post("/api/printer/{printer_id}/plate-clear")
async def api_printer_plate_clear(printer_id: str, req: Request):
    """Подтверждение «Стол очищен» для принтера. ТОЛЬКО по явному действию человека: телеметрия
    жетон не создаёт никогда, покой и завершение печати пустой стол не доказывают.

    Вид подтверждения здесь — «после печати»: safe_idle не требуется (закончивший принтер им и не
    бывает), но требуется ДОКАЗАННОЕ завершение по сырому статусу прошивки. Список таких статусов
    по маркам один на всю программу — _QW_BED_RAW, тот же, по которому очередь помечает принтер
    «проверьте стол»."""
    d = await _json_body(req)
    with lock_pr:
        _p = conn_pr.execute("SELECT id FROM printers WHERE id=?", (printer_id,)).fetchone()
    if not _p:
        return JSONResponse(status_code=404, content={"status": "error", "reason": "printer_not_found"})
    #  16.09.2026: вид подтверждения выбирается по состоянию принтера. Закончил печать —
    #  постпечатный (safe_idle не требуется, но требуется доказанное завершение). В покое —
    #  ПЕРВИЧНЫЙ, и там ядро требует safe_idle. Так владелец может подтвердить и тот принтер,
    #  на столе которого лежит деталь, о которой программа не знает.
    _raw = _QW_BED_RAW.get(_printer_transport(printer_id), ())
    _pst = p_states.get(printer_id) or {}
    _fin = (str(_pst.get("status") or "").upper() == "FINISH"
            or str(_pst.get("status_raw") or "") in _raw)
    r = _orch.create_clearance(printer_id, confirmed=(d.get("confirmed") is True),
                               confirmed_by=_feed_approved_by(req), post_print=_fin,
                               finished_raw=_raw)
    return r if r.get("status") == "ok" else JSONResponse(status_code=409, content=r)


@app.post("/api/printer/{printer_id}/plate-clear/revoke")
def api_printer_plate_clear_revoke(printer_id: str):
    """Снять своё подтверждение. Движение в БЕЗОПАСНУЮ сторону (жетон исчезает), поэтому без
    барьеров: автозапуск после этого на принтер не пойдёт."""
    r = _orch.revoke_clearance(printer_id)
    return r if r.get("status") == "ok" else JSONResponse(status_code=409, content=r)


#  Пометки принтера «сопло / материал / группа» (2.927) удалены 12.09.2026 по решению владельца:
#  блок ушёл из пульта принтера вместе с маршрутом записи и полями в ответе со списком принтеров.
#  Колонки mark_* в таблице printers оставлены как были — схема не меняется, прежние значения
#  ничем не читаются и никуда не отдаются.


#  Настройки фермы: одно значение на всю ферму, с какого компьютера ни зайди (2.927).
#  Только перечисленные ключи: интервал поэтапного запуска раньше жил в браузере каждого
#  компьютера, и на разных машинах вёл себя по-разному — владелец попросил единые данные.
#  low_pct (2.965): порог «скоро кончится» для остатка катушки. Здесь, а не в браузере,
#  потому что порог общий для всей фермы: подсветка и предупреждения должны совпадать
#  на всех компьютерах. Схема базы не меняется — ключ ложится в существующую app_settings.
#  16.09.2026: queue_auto_start — выключатель автозапуска очереди ожидания на ВСЮ ферму
#  («1» — включён). Отдельно от отметки принтера queue_allowed намеренно: та отметка давалась
#  под обещание в интерфейсе «Печать начинается по вашему подтверждению», и считать её
#  согласием на автомат нельзя.
#  R-131 (29.09.2026): update_check — выключатель «Проверять обновления» («0» — не ходить на сайт
#  за новой версией). Нет записи — проверка включена, как было до выключателя.
_FARM_SETTINGS_KEYS = ("stagger_on", "stagger_sec", "low_pct", "queue_auto_start", "update_check")
#  R-103 (2.984): пресеты прогрева — тоже настройка ФЕРМЫ, а не компьютера: оператор правит их
#  на одном месте, а видят все. Ключ отдельный (JSON, а не строка до 32 знаков), форма
#  проверяется целиком — это данные из браузера, и в базу они ложатся только правильными.
#  3.000: какие модули показывать кнопками на баре «Проекты / Задачи / Очередь / Филамент».
#  Настройка ФЕРМЫ (как пресеты прогрева): выбирают один раз, видят все компьютеры. Храним
#  СПИСОК id, а не строку до 32 знаков, поэтому ключ отдельный и проверяется целиком.
#  Пустой список — законное значение: «не показывать ни одного».
_FARM_BAR_MODULES_KEY = "farm_bar_modules"
_BAR_MODULES_MAX = 24
_BAR_ID_MAX = 64


def _farm_bar_modules_validate(raw):
    """Список id модулей из запроса -> (чистый список, причина отказа или '').
    id модуля — то же, что в module.json: буквы, цифры, подчёркивание, дефис."""
    if not isinstance(raw, list):
        return None, "bad_bar_modules"
    if len(raw) > _BAR_MODULES_MAX:
        return None, "too_many_bar_modules"
    out, seen = [], set()
    for it in raw:
        mid = str(it or "").strip()[:_BAR_ID_MAX]
        if not mid or not re.fullmatch(r"[A-Za-z0-9_-]+", mid):
            return None, "bad_bar_module_id"
        if mid in seen:
            continue
        seen.add(mid)
        out.append(mid)
    return out, ""


def _farm_bar_modules_read():
    """-> список id или None, если владелец ещё ничего не выбирал (значит, показываем все)."""
    try:
        with lock_p:
            row = conn_p.execute("SELECT value FROM app_settings WHERE key=?",
                                 (_FARM_BAR_MODULES_KEY,)).fetchone()
        if row is None:
            return None
        raw = row["value"] if not isinstance(row, tuple) else row[0]
        data = json.loads(raw or "null")
        clean, _why = _farm_bar_modules_validate(data)
        return clean
    except Exception:
        log.debug("[FARM-SET] bar modules read failed: %s", _exc_brief())
        return None


#  16.09.2026: каким принтерам разрешён АВТОЗАПУСК. Храним СПИСОК id, поэтому ключ отдельный
#  (JSON), как у модулей панели. Пустой список — законное значение: «никому». Правило допуска
#  двойное: принтер обязан быть и здесь, и с отметкой queue_allowed.
_FARM_AUTO_START_KEY = "farm_auto_start_printers"
_AUTO_START_MAX = 512
_AUTO_START_ID_MAX = 64


def _farm_auto_start_validate(raw):
    """Список id принтеров из запроса -> (чистый список, причина отказа или '').
    Набор знаков id не выдумываем (у принтеров он задан генератором ядра): отвергаем только
    пустое, слишком длинное и управляющие символы."""
    if not isinstance(raw, list):
        return None, "bad_auto_start"
    if len(raw) > _AUTO_START_MAX:
        return None, "too_many_auto_start"
    out, seen = [], set()
    for it in raw:
        #  16.09.2026: не-строка и слишком длинный id — ОТКАЗ, а не молчаливая подмена.
        #  Раньше число, словарь и обрезанный до 64 знаков id ложились в базу как «id».
        if not isinstance(it, str):
            return None, "bad_auto_start_id"
        pid = it.strip()
        if len(pid) > _AUTO_START_ID_MAX:
            return None, "bad_auto_start_id"
        if not pid or any(ord(ch) < 32 for ch in pid):
            return None, "bad_auto_start_id"
        if pid in seen:
            continue
        seen.add(pid)
        out.append(pid)
    return out, ""


def _farm_auto_start_read():
    """-> список id или None, если владелец ещё ничего не выбирал (значит, никому)."""
    try:
        with lock_p:
            row = conn_p.execute("SELECT value FROM app_settings WHERE key=?",
                                 (_FARM_AUTO_START_KEY,)).fetchone()
        if row is None:
            return None
        raw = row["value"] if not isinstance(row, tuple) else row[0]
        data = json.loads(raw or "null")
        clean, _why = _farm_auto_start_validate(data)
        return clean
    except Exception:
        log.debug("[FARM-SET] auto-start read failed: %s", _exc_brief())
        return None


_FARM_PRESETS_KEY = "farm_preheat_presets"
_PRESET_NAME_MAX = 12
_PRESETS_MAX = 24
_PRESET_LIMITS = {"n": (0, 350), "b": (0, 120), "c": (0, 65)}   # сопло, стол, камера — как в политике команд


def _farm_presets_validate(raw):
    """Список пресетов из запроса -> (список чистых пресетов, причина отказа или '').
    Пресет: {name, n, b, c?}. Имя — до 12 знаков без управляющих символов; температуры —
    целые в пределах, камера необязательна (None = у пресета камеры нет)."""
    if not isinstance(raw, list):
        return None, "bad_presets"
    if len(raw) > _PRESETS_MAX:
        return None, "too_many_presets"
    out, names = [], set()
    for it in raw:
        if not isinstance(it, dict):
            return None, "bad_presets"
        name = " ".join(str(it.get("name") or "").split())[:_PRESET_NAME_MAX]
        if not name or any(ord(ch) < 32 for ch in name):
            return None, "bad_preset_name"
        if name.casefold() in names:
            return None, "duplicate_preset_name"
        names.add(name.casefold())
        clean = {"name": name}
        for key in ("n", "b", "c"):
            v = it.get(key)
            if key == "c" and v in (None, ""):
                clean["c"] = None
                continue
            if isinstance(v, bool) or v is None or isinstance(v, float) and not float(v).is_integer():
                return None, "bad_preset_value"
            try:
                iv = int(v)
            except Exception:
                return None, "bad_preset_value"
            lo, hi = _PRESET_LIMITS[key]
            if iv < lo or iv > hi:
                return None, "preset_value_out_of_range"
            clean[key] = iv
        out.append(clean)
    return out, ""


def _farm_presets_read():
    """Пресеты прогрева с сервера или None, если владелец их ещё не правил (тогда интерфейс
    показывает встроенные)."""
    with lock_p:
        row = conn_p.execute("SELECT value FROM app_settings WHERE key=?", (_FARM_PRESETS_KEY,)).fetchone()
    if row is None:
        return None
    try:
        val = json.loads(row["value"] if not isinstance(row, tuple) else row[0])
    except Exception:
        return None
    clean, _why = _farm_presets_validate(val)
    return clean


#  16.10.2026 (R-151, аудит data-safety-17): настройки интерфейса модулей, общие для всех
#  компьютеров (например, адреса IP-камер видеостены). Раньше они жили только в памяти браузера
#  и пропадали при смене порта или компьютера. Хранятся в app_settings под 'farm_module_ui.<id>',
#  по одному JSON на модуль, не больше 256 КБ; null удаляет запись. Новых маршрутов нет — тот же
#  /api/farm-settings (право записи прежнее).
_FARM_MODULE_UI_PREFIX = "farm_module_ui."
_FARM_MODULE_UI_MAX = 256 * 1024


def _farm_module_ui_validate(raw):
    """{id модуля: dict | None} -> ({id: json-строка | None}, '') или (None, причина)."""
    if not isinstance(raw, dict):
        return None, "bad_module_ui"
    out = {}
    for mid, val in raw.items():
        if not _module_id_ok(mid):
            return None, "bad_module_ui_id"
        if val is None:
            out[str(mid)] = None
            continue
        if not isinstance(val, dict):
            return None, "bad_module_ui_value"
        try:
            s = json.dumps(val, ensure_ascii=False, separators=(",", ":"))
        except Exception:
            return None, "bad_module_ui_value"
        if len(s.encode("utf-8")) > _FARM_MODULE_UI_MAX:
            return None, "module_ui_too_large"
        out[str(mid)] = s
    return out, ""


def _farm_module_ui_read():
    """{id модуля: dict} из app_settings (испорченная запись пропускается)."""
    out = {}
    with lock_p:
        rows = conn_p.execute("SELECT key, value FROM app_settings WHERE key LIKE ?",
                              (_FARM_MODULE_UI_PREFIX + "%",)).fetchall()
    for row in rows:
        k = str(row["key"] if not isinstance(row, tuple) else row[0])
        v = row["value"] if not isinstance(row, tuple) else row[1]
        mid = k[len(_FARM_MODULE_UI_PREFIX):]
        if not k.startswith(_FARM_MODULE_UI_PREFIX) or not _module_id_ok(mid):
            continue
        try:
            val = json.loads(v)
        except Exception:
            continue
        if isinstance(val, dict):
            out[mid] = val
    return out


def _farm_settings_read():
    """Прочитать настройки фермы из app_settings. Только известные ключи."""
    out = {}
    with lock_p:
        for k in _FARM_SETTINGS_KEYS:
            row = conn_p.execute("SELECT value FROM app_settings WHERE key=?",
                                 ("farm_" + k,)).fetchone()
            if row is not None:
                out[k] = str(row["value"] if not isinstance(row, tuple) else row[0])
    _presets = _farm_presets_read()
    if _presets is not None:
        out["preheat_presets"] = _presets
    _bar = _farm_bar_modules_read()
    if _bar is not None:
        out["bar_modules"] = _bar
    _auto = _farm_auto_start_read()
    if _auto is not None:
        out["auto_start_printers"] = _auto
    _mui = _farm_module_ui_read()      # 16.10.2026 (R-151): настройки интерфейса модулей
    if _mui:
        out["module_ui"] = _mui
    return out


def _farm_settings_write(data):
    """Записать настройки фермы. Неизвестные ключи молча отбрасываются, значения — строки
    с пределом длины: это настройки, а не свалка."""
    vals = {}
    for k in _FARM_SETTINGS_KEYS:
        if k in (data or {}):
            vals[k] = str((data or {}).get(k))[:32]
    presets = None
    if "preheat_presets" in (data or {}):
        presets, why = _farm_presets_validate((data or {}).get("preheat_presets"))
        if presets is None:
            return {"ok": False, "error": why}
    bar = None
    if "bar_modules" in (data or {}):
        bar, why = _farm_bar_modules_validate((data or {}).get("bar_modules"))
        if bar is None:
            return {"ok": False, "error": why}
    #  16.09.2026: выключатель автозапуска — только «0» или «1». Тело {"queue_auto_start": true}
    #  ложилось строкой "True" и молча означало «выключено».
    if "queue_auto_start" in vals and vals["queue_auto_start"] not in ("0", "1"):
        return {"ok": False, "error": "bad_queue_auto_start"}
    #  R-131: выключатель проверки обновлений — тоже только «0» или «1».
    if "update_check" in vals and vals["update_check"] not in ("0", "1"):
        return {"ok": False, "error": "bad_update_check"}
    auto = None
    if "auto_start_printers" in (data or {}):
        auto, why = _farm_auto_start_validate((data or {}).get("auto_start_printers"))
        if auto is None:
            return {"ok": False, "error": why}
    mui = None
    if "module_ui" in (data or {}):     # 16.10.2026 (R-151): {id модуля: {...} | null}
        mui, why = _farm_module_ui_validate((data or {}).get("module_ui"))
        if mui is None:
            return {"ok": False, "error": why}
    if not vals and presets is None and bar is None and auto is None and not mui:
        return {"ok": False, "error": "no_fields"}
    with lock_p:
        for k, v in vals.items():
            conn_p.execute("INSERT INTO app_settings (key, value) VALUES (?, ?) "
                           "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                           ("farm_" + k, v))
        if presets is not None:
            conn_p.execute("INSERT INTO app_settings (key, value) VALUES (?, ?) "
                           "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                           (_FARM_PRESETS_KEY, json.dumps(presets, ensure_ascii=False)))
        if bar is not None:
            conn_p.execute("INSERT INTO app_settings (key, value) VALUES (?, ?) "
                           "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                           (_FARM_BAR_MODULES_KEY, json.dumps(bar, ensure_ascii=False)))
        if auto is not None:
            conn_p.execute("INSERT INTO app_settings (key, value) VALUES (?, ?) "
                           "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                           (_FARM_AUTO_START_KEY, json.dumps(auto, ensure_ascii=False)))
        for _mid, _js in (mui or {}).items():
            if _js is None:
                conn_p.execute("DELETE FROM app_settings WHERE key=?", (_FARM_MODULE_UI_PREFIX + _mid,))
            else:
                conn_p.execute("INSERT INTO app_settings (key, value) VALUES (?, ?) "
                               "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                               (_FARM_MODULE_UI_PREFIX + _mid, _js))
        conn_p.commit()
    res = {"ok": True, **vals}
    if presets is not None:
        res["preheat_presets"] = presets
    if bar is not None:
        res["bar_modules"] = bar
    if auto is not None:
        res["auto_start_printers"] = auto
    if mui:
        res["module_ui"] = {k: (json.loads(v) if v is not None else None) for k, v in mui.items()}
    return res


@app.get("/api/farm-settings")
def api_farm_settings_get():
    """Настройки фермы — единые для всех компьютеров (2.927)."""
    try:
        _s = _farm_settings_read()
        #  16.10.2026 (R-151): настройки интерфейса модулей — и в settings, и на верхнем уровне ответа.
        return {"ok": True, "settings": _s, "module_ui": dict(_s.get("module_ui") or {})}
    except Exception:
        log.debug("[FARM-SET] read failed: %s", _exc_brief())
        return {"ok": False, "settings": {}}


@app.post("/api/farm-settings")
def api_farm_settings_set(data: Dict[str, Any], req: Request = None):
    """Записать настройки фермы (2.927).
    16.10.2026 (R-145, решение c): при включённой защите смена настроек фермы (в том числе
    пресетов прогрева) пишется в журнал аудита — кто, с какого телефона, какие настройки и итог."""
    try:
        res = _farm_settings_write(data or {})
    except Exception:
        log.debug("[FARM-SET] write failed: %s", _exc_brief())
        res = {"ok": False, "error": "db"}
    if req is not None and _SECURITY_ENABLED:
        try:
            _d = data if isinstance(data, dict) else {}
            #  В запись — только ИЗВЕСТНЫЕ имена настроек: ключи запроса присылает клиент.
            _keys = [k for k in _FARM_SETTINGS_KEYS + ("preheat_presets", "bar_modules", "auto_start_printers")
                     if k in _d]
            u = _session_user(req) or {}
            _audit(u.get("username", ""), "farm.settings", ", ".join(_keys),
                   "ok" if isinstance(res, dict) and res.get("ok") else str((res or {}).get("error") or "error"), req)
        except Exception:
            log.debug("[FARM-SET] запись аудита не удалась: %s", _exc_brief())
    return res


@app.get("/api/print-queue/durable")
def api_print_queue_durable():
    """Alpha 2.627 — READ-ONLY снимок durable-очереди print_launch_queue для интерфейса.
    СТРОГО ТОЛЬКО ЧТЕНИЕ: единственный SELECT, без INSERT/UPDATE/DELETE. НЕ влияет на воркер,
    восстановление (_print_queue_recover) и запуск печати — просто отдаёт последние строки, чтобы
    показать их статусы (pending/launching/sent/failed/canceled/stale/recovery_attention). При ошибке
    чтения возвращаем {'ok': False} (интерфейс покажет состояние ошибки); сервер не роняем."""
    try:
        with lock_pr:
            rows = [dict(r) for r in conn_pr.execute(
                "SELECT id, batch_id, printer_id, printer_name, flow, job_ref, due_ts, status, "
                "attempts, last_error, COALESCE(recovery_eligible,0) AS recovery_eligible, "
                "created_at, updated_at FROM print_launch_queue "
                "ORDER BY created_at DESC, due_ts DESC LIMIT 200").fetchall()]
        return {"ok": True, "rows": rows, "now": time.time()}
    except Exception:
        log.error("[PRINT-QUEUE] durable read (UI) failed: %s" % _exc_brief())
        return {"ok": False, "rows": [], "error": "read failed", "now": time.time()}

def _print_queue_persist(batch_id, rows):
    """ФАЗА 1 (Alpha 2.623) — durable-«тень» in-memory print_queue в таблице print_launch_queue.
    Пишет строки со статусом 'pending' при постановке пачки в очередь (dual-write из
    api_print_queue_enqueue). Воркер эту таблицу пока НЕ читает; переходы статусов
    (launching/sent/failed/canceled) и восстановление после рестарта — в следующих Alpha.
    rows — список dict-элементов, ТОЧЬ-В-ТОЧЬ как положены в print_queue (payload сохраняем целиком)."""
    ts = time.time()
    with lock_pr:
        for q in rows:
            if q.get("flow") == "project":
                job_ref = "project:%s/file:%s" % (q.get("project_id") or "", q.get("file_id") or "")
            else:
                job_ref = str(q.get("gcode_file") or q.get("part_name") or "")
            conn_pr.execute(
                "INSERT INTO print_launch_queue (id, batch_id, printer_id, printer_name, flow, job_ref, due_ts, status, attempts, last_error, payload, created_at, updated_at, recovery_eligible) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (str(q.get("durable_id") or _uid("plq_")), str(batch_id), str(q.get("printer_id") or ""), str(q.get("printer_name") or ""),
                 str(q.get("flow") or "quick"), job_ref[:500], float(q.get("due_ts") or ts),
                 "pending", 0, "", _jsonmod.dumps(q, ensure_ascii=False), ts, ts, 1))   # ФАЗА 3 (Alpha 2.625): новые строки — recovery_eligible=1
        conn_pr.commit()

def _enqueue_item_bytes(it):
    """Содержимое файла элемента очереди (bytes) или None. Оба потока разрешаются так же, как при
    самом запуске: quick — через _staging_path, project — через stored_path/src_path из project_files."""
    try:
        if str(it.get("flow") or "") == "project":
            with lock_p:
                fr = conn_p.execute("SELECT stored_path, src_path FROM project_files WHERE id=? AND project_id=?",
                                    (it.get("file_id"), it.get("project_id"))).fetchone()
            path = (fr["stored_path"] or fr["src_path"]) if fr else None
        else:
            path = _staging_path(os.path.basename(str(it.get("gcode_file") or "")),
                                 str(it.get("part_name") or "") or None)
        if not path or not os.path.isfile(path):
            return None
        with open(path, "rb") as fh:
            return fh.read()
    except Exception:
        return None


def _enqueue_preflight(items):
    """Alpha 2.848 — проверка ДО постановки в очередь, в момент нажатия «запустить».

    ЗАЧЕМ ЗДЕСЬ, А НЕ ПРИ СТАРТЕ. Отложенный элемент стартует через минуты; отказ в тот момент
    владелец не видит — 17.08.2026 из-за этого девятый принтер просто не напечатал. Проверка на
    нажатии даёт ответ, пока человек у экрана.

    → (allowed, blocked, notes)
      allowed — элементы, которые ставим в очередь как раньше;
      blocked — по ним запуск не ставится, причина уходит в интерфейс (он покажет окно решения);
      notes   — НЕблокирующие уведомления хуков (склад решил вопрос сам).

    FAIL-OPEN: файл не прочитан или хук упал — элемент считается разрешённым. Проверка не вправе
    отменить печать из-за собственных трудностей."""
    allowed, blocked, notes = [], [], []
    _cache = {}
    _ptypes = {}                 # тип принтера по pid: один запрос к базе на всю пачку
    for it in (items or []):
        pid = str(it.get("printer_id") or "")
        if not pid:
            continue
        # Alpha 2.850: элемент пришёл из окна «Материал закончился», вариант «Печатать всё равно».
        # Решение владелец уже принял и учёт при этом поправлен (остаток списан) — спрашивать склад
        # заново нельзя: он вернул бы ту же блокировку, и цепочка запусков оборвалась бы снова.
        if it.get("skip_filament"):
            allowed.append(it)
            log.info("[PRINT-QUEUE] preflight: %s — запуск по решению владельца, склад не проверяется"
                     % str(it.get("printer_name") or pid))
            continue
        key = (str(it.get("flow") or "quick"), str(it.get("gcode_file") or ""), str(it.get("part_name") or ""),
               str(it.get("project_id") or ""), str(it.get("file_id") or ""))
        if key not in _cache:
            _cache[key] = _enqueue_item_bytes(it)
        fdata = _cache[key]
        if not fdata:
            allowed.append(it)                      # нечего проверять — не наше дело мешать запуску
            continue
        fname = os.path.basename(str(it.get("gcode_file") or it.get("part_name") or ""))
        _adv = []
        #  16.09.2026: склад обязан сверять ТОТ слот, из которого пойдёт печать. У элемента очереди
        #  слот не задан, поэтому план подачи считается здесь. Это снимок: до старта пройдут минуты,
        #  состояние подачи может измениться — так и помечаем, а решает всё равно сам транспорт.
        if pid not in _ptypes:
            _ptypes[pid] = _printer_transport(pid)
        _plan = _launch_feed_plan(pid, _ptypes[pid], it.get("ams_slot"), fdata, it.get("print_opts"))
        if _plan.get("confidence") == "resolved":
            _plan["confidence"] = "snapshot"
        try:
            blk = _run_pre_print_hooks(pid, fdata, it.get("ams_slot"), fname, advice_out=_adv, plan=_plan)
        except Exception:
            log.debug("[PRINT-QUEUE] preflight hook error: %s", _exc_brief())
            blk = None
        for a in _adv:
            notes.append(dict(a, printer_id=pid, printer_name=str(it.get("printer_name") or pid)))
        if blk:
            blocked.append(dict(blk, printer_id=pid, printer_name=str(it.get("printer_name") or pid)))
            log.info("[PRINT-QUEUE] preflight: %s не поставлен в очередь — %s"
                     % (str(it.get("printer_name") or pid), str(blk.get("status") or "block")))
        else:
            allowed.append(it)
    return allowed, blocked, notes


def _project_file_name(project_id, file_id):
    """Имя файла проекта по id — подпись отправки в очереди (15.09.2026). Fail-open: нет записи
    или ошибка чтения -> '' (постановка в очередь от подписи не зависит)."""
    if not project_id or not file_id:
        return ""
    try:
        with lock_p:
            r = conn_p.execute("SELECT filename FROM project_files WHERE id=? AND project_id=?",
                               (str(file_id), str(project_id))).fetchone()
        return str(r["filename"] or "") if r else ""
    except Exception:
        log.debug("[PRINT-QUEUE] имя файла проекта не прочитано: %s", _exc_brief())
        return ""


@app.post("/api/print-queue/enqueue")
def api_print_queue_enqueue(data: Dict[str, Any]):
    """Поставить пачку запусков в очередь с интервалом. Старты разносятся так, чтобы между любыми
    двумя выдерживался interval секунд (в т.ч. относительно уже стоящих в очереди). Дубли по принтеру не ставятся."""
    global _print_queue_seq
    items = data.get("items") or []
    try:
        interval = float(data.get("interval") or 60)
    except Exception:
        interval = 60.0
    interval = max(1.0, min(3600.0, interval))
    now = time.time()
    added = []
    _held = []                  # Alpha 2.741: принтеры, отклонённые удержанием (аддитивно в ответе)
    # Alpha 2.848: склад проверяется ЗДЕСЬ — пока владелец у экрана, а не через минуты при старте.
    # Заблокированные в очередь не ставятся (и принтер под них не резервируется), их причина уходит
    # в интерфейс; уведомления — то, что склад решил сам (см. _enqueue_preflight).
    items, _blocked, _notes = _enqueue_preflight(items)
    #  15.09.2026: имя файла для reservation очереди. У проектного элемента нет gcode_file — раньше
    #  панель отправок показывала пустое имя, а строка проекта не могла узнать «свой» файл и сразу
    #  показать «Отправка». Имя читается ДО print_queue_lock — порядок замков не меняется.
    _pf_names = {}
    for it in items:
        if it.get("flow") == "project" and not (it.get("gcode_file") or it.get("part_name")):
            _k = (str(it.get("project_id") or ""), str(it.get("file_id") or ""))
            if _k not in _pf_names:
                _pf_names[_k] = _project_file_name(*_k)
    def _resv_name(it):
        n = str(it.get("gcode_file") or it.get("part_name") or "")
        if not n and it.get("flow") == "project":
            n = _pf_names.get((str(it.get("project_id") or ""), str(it.get("file_id") or "")), "")
        return n
    batch_id = _uid("batch_")   # ФАЗА 1 (Alpha 2.623): одна операция enqueue = один батч (для durable-тени)
    _db_rows = []               # ФАЗА 1: элементы для дублирующей записи в print_launch_queue
    with print_queue_lock:
        queued_pids = {q["printer_id"] for q in print_queue}
        last_due = max([q["due_ts"] for q in print_queue], default=now - interval)
        slot = max(now, last_due + interval)   # первый — сразу (если очередь пуста), дальше через interval
        for it in items:
            pid = str(it.get("printer_id") or "")
            if not pid or pid in queued_pids:
                continue
            # Alpha 2.728: атомарно занять принтер УЖЕ на enqueue — с этого момента он недоступен для другой печати.
            _rok, _sjid, _rreason = _send_mgr.reserve(pid, str(it.get("printer_name") or pid), _resv_name(it), "queue")
            if not _rok:
                # Alpha 2.741: удержанный принтер в очередь не ставим и НЕ прячем причину — пакетный роут
                # не может ответить одним 409 на всю пачку, поэтому отдаём удержания аддитивным полем held
                # (успешный ответ и поле queued не меняются).
                if _rreason == "printer_held":
                    _held.append({"printer_id": pid, "hold": _hold_public(_send_mgr.get_hold(pid))})
                continue   # принтер уже занят другой отправкой/очередью/удержанием — элемент не ставим
            queued_pids.add(pid)
            _print_queue_seq += 1
            _qitem = {
                "id": str(_print_queue_seq),
                "durable_id": _uid("plq_"),   # ФАЗА 2 (Alpha 2.624): связь in-memory элемента со строкой print_launch_queue
                "send_job_id": _sjid,         # Alpha 2.728: reservation, взятая на enqueue (worker её адоптирует)
                "printer_id": pid,
                "printer_name": str(it.get("printer_name") or pid),
                "flow": "project" if it.get("flow") == "project" else "quick",
                "due_ts": slot,
                "gcode_file": it.get("gcode_file"),
                "source": it.get("source") or "quick",
                "part_name": it.get("part_name"),
                "project_id": it.get("project_id"),
                "file_id": it.get("file_id"),
                "ams_slot": it.get("ams_slot"),
                #  16.09.2026: номер строки очереди ожидания. Едет и в память, и в durable-payload,
                #  поэтому исход находит свою строку даже после перезапуска программы.
                "qw_id": str(it.get("qw_id") or ""),
                # Alpha 2.850: решение владельца «печатать всё равно» едет с элементом до самого
                # старта — иначе quick-поток переспросил бы склад через минуту и снова упёрся.
                "skip_filament": bool(it.get("skip_filament")),
                # Alpha 2.723: опции запуска переживают очередь/рестарт БЕЗ миграции схемы — элемент целиком
                # сериализуется в существующую JSON-колонку payload (durable-тень); recovery реконструирует
                # из неё. Элементы без ключа (старые/пакетные) → None → дефолтный payload, как раньше.
                "print_opts": (it.get("print_opts") if isinstance(it.get("print_opts"), dict) else None),
            }
            print_queue.append(_qitem)      # ПОВЕДЕНИЕ КАК ПРЕЖДЕ: in-memory очередь ВЕДЁТ запуск печати
            _db_rows.append(_qitem)         # ФАЗА 1: та же запись — в durable-тень (см. _print_queue_persist)
            added.append(pid)
            slot += interval
    # ФАЗА 1 (Alpha 2.623) — durable-запись: дублируем поставленные элементы в print_launch_queue.
    # Best-effort, но НЕ молча: при ошибке пишем ERROR. In-memory очередь УЖЕ заполнена и ведёт запуск
    # как раньше — сбой записи в БД НЕ создаёт дублей и НЕ меняет текущую печать (просто эта пачка не будет
    # восстанавливаема после рестарта). Воркер print_launch_queue пока НЕ читает.
    if _db_rows:
        try:
            _print_queue_persist(batch_id, _db_rows)
        except Exception:
            log.error("[PRINT-QUEUE] durable-запись НЕ удалась (батч %s, %d элем.): %s — очередь работает из памяти (дублей нет), восстановление этой пачки после рестарта недоступно"
                      % (batch_id, len(_db_rows), _exc_brief()))
    log.info("[PRINT-QUEUE] enqueued %d printer(s), interval=%ss, held=%d, blocked=%d, notes=%d"
             % (len(added), int(interval), len(_held), len(_blocked), len(_notes)))
    # blocked/notes — аддитивные поля (как held в 2.741): прежние поля и их смысл не меняются.
    return {"status": "ok", "queued": added, "held": _held, "blocked": _blocked, "notes": _notes,
            "queue": _print_queue_public()}

@app.post("/api/print-queue/cancel")
def api_print_queue_cancel(data: Dict[str, Any]):
    """Убрать из очереди выбранные элементы (по id элемента или по printer_id) до их старта."""
    ids = {str(x) for x in (data.get("ids") or [])}
    pids = {str(x) for x in (data.get("printer_ids") or [])}
    _cancelled_dids = []   # ФАЗА 2 (Alpha 2.624): durable_id снятых элементов — пометим строки как canceled
    _cancelled_sjids = []  # Alpha 2.728: send_job_id снятых элементов — снимем reservation
    _cancelled_qw = []     # 16.09.2026: строки очереди ожидания снятых элементов — вернём в ожидание
    with print_queue_lock:
        before = len(print_queue)
        _keep = []
        for q in print_queue:
            if q["id"] in ids or q["printer_id"] in pids:
                if q.get("durable_id"):
                    _cancelled_dids.append(q["durable_id"])
                if q.get("send_job_id"):
                    _cancelled_sjids.append(q["send_job_id"])
                if q.get("qw_id"):
                    _cancelled_qw.append(str(q["qw_id"]))
            else:
                _keep.append(q)
        print_queue[:] = _keep
        removed = before - len(print_queue)
    for _sj in _cancelled_sjids:
        _send_mgr.cancel_reserved(_sj, "queue canceled")   # освобождаем принтер (worker ещё не стартовал)
    # ФАЗА 2 (Alpha 2.624): зеркалим отмену в print_launch_queue — только строки, ещё стоящие в 'pending'
    # (если воркер уже увёл элемент в launching/sent — не перетираем). Поведение отмены очереди НЕ изменено.
    for _did in _cancelled_dids:
        _plq_set_status(_did, "canceled", only_if="pending")
    for _qw in _cancelled_qw:
        #  Отмена ДО старта — доказанно не отправляли: строка возвращается владельцу в очередь.
        _qw_finish(_qw, "waiting", "запуск отменён в очереди запусков")
    if removed:
        log.info("[PRINT-QUEUE] cancelled %d queued start(s)" % removed)
    return {"status": "ok", "removed": removed, "queue": _print_queue_public()}

@app.post("/api/print-queue/durable/cancel")
def api_print_queue_durable_cancel(data: Dict[str, Any]):
    """Alpha 2.628 — отмена ТОЛЬКО ожидающих (status='pending') отложенных запусков durable-очереди из UI.
    Вход: {'id': <id строки>} — одна строка, ИЛИ {'batch_id': <batch>} — все pending этой пачки.
    Делает РОВНО две вещи, обе безопасные:
      (1) убирает ещё ждущие элементы из in-memory print_queue (совпадение по durable_id) — ДО апдейта БД,
          чтобы воркер их не запустил; элементы, которые воркер УЖЕ забрал на старт, не трогаются (их там нет);
      (2) UPDATE print_launch_queue SET status='canceled', updated_at=?, last_error='' WHERE status='pending'
          (по id или batch_id). Строки НЕ удаляются; НЕ-pending (launching/sent/failed/canceled/stale/
          recovery_attention) НЕ трогаются (guard WHERE status='pending'). Печать НЕ запускается, схема БД не меняется.
    Идемпотентно: повторная отмена той же строки обновляет 0 строк. `_print_queue_recover` уже читает только
    'pending' → отменённые строки после рестарта не возобновятся (доп. правок восстановления не требуется)."""
    row_id = str(data.get("id") or "").strip()
    batch_id = str(data.get("batch_id") or "").strip()
    if not row_id and not batch_id:
        return {"ok": False, "error": "no id/batch_id", "canceled": 0, "skipped": 0}
    # (0) читаем целевые строки, чтобы знать durable_id ещё-pending (для чистки памяти) и число не-pending (skipped)
    try:
        with lock_pr:
            if row_id:
                rows = conn_pr.execute("SELECT id, status FROM print_launch_queue WHERE id=?", (row_id,)).fetchall()
            else:
                rows = conn_pr.execute("SELECT id, status FROM print_launch_queue WHERE batch_id=?", (batch_id,)).fetchall()
    except Exception:
        log.error("[PRINT-QUEUE] durable-cancel read failed (%s=%s): %s" % ("id" if row_id else "batch", row_id or batch_id, _exc_brief()))
        return {"ok": False, "error": "read failed", "canceled": 0, "skipped": 0}
    if not rows:
        return {"ok": True, "canceled": 0, "skipped": 0, "removed_from_memory": 0}   # нет такой строки/пачки — идемпотентный no-op
    pending_ids = {str(r["id"]) for r in rows if r["status"] == "pending"}
    non_pending = sum(1 for r in rows if r["status"] != "pending")
    # (1) убрать ещё ждущие элементы из in-memory print_queue ДО апдейта БД (иначе воркер может стартовать между шагами)
    removed_mem = 0
    _rel_sjids = []   # Alpha 2.728: send_job_id снятых из памяти элементов — освободим reservation
    _rel_qw = []      # 16.09.2026: строки очереди ожидания снятых элементов — вернём в ожидание
    if pending_ids:
        with print_queue_lock:
            _keep = []
            for q in print_queue:
                if str(q.get("durable_id") or "") in pending_ids:
                    if q.get("send_job_id"):
                        _rel_sjids.append(q["send_job_id"])
                    if q.get("qw_id"):
                        _rel_qw.append(str(q["qw_id"]))
                else:
                    _keep.append(q)
            removed_mem = len(print_queue) - len(_keep)
            print_queue[:] = _keep
    for _sj in _rel_sjids:
        _send_mgr.cancel_reserved(_sj, "queue canceled")
    for _qw in _rel_qw:
        _qw_finish(_qw, "waiting", "запуск отменён в очереди запусков")
    # (2) durable: ТОЛЬКО pending → canceled (без DELETE; не-pending защищены guard-ом WHERE status='pending')
    canceled = 0
    try:
        ts = time.time()
        with lock_pr:
            # Alpha 2.772 (A-4): за вызов выполняется ОДНА запись (ветки if/else взаимоисключающие),
            # но сбой самого commit оставил бы её в незавершённой транзакции общего соединения —
            # пользователь получил бы «отмена не удалась», а следующий чужой commit молча зафиксировал
            # бы отмену. Откат под тем же lock закрывает это расхождение.
            try:
                if row_id:
                    cur = conn_pr.execute("UPDATE print_launch_queue SET status='canceled', updated_at=?, last_error='' "
                                          "WHERE id=? AND status='pending'", (ts, row_id))
                else:
                    cur = conn_pr.execute("UPDATE print_launch_queue SET status='canceled', updated_at=?, last_error='' "
                                          "WHERE batch_id=? AND status='pending'", (ts, batch_id))
                canceled = cur.rowcount if (cur.rowcount and cur.rowcount > 0) else 0
                conn_pr.commit()
            except Exception:
                try:
                    conn_pr.rollback()
                except Exception:
                    log.error("[PRINT-QUEUE] SQLite rollback failed (durable-cancel): %s" % _exc_brief())
                raise
    except Exception:
        log.error("[PRINT-QUEUE] durable-cancel update failed (%s=%s): %s" % ("id" if row_id else "batch", row_id or batch_id, _exc_brief()))
        return {"ok": False, "error": "update failed", "canceled": 0, "skipped": non_pending, "removed_from_memory": removed_mem}
    log.info("[PRINT-QUEUE] durable-cancel: canceled=%d, mem_removed=%d, non_pending_skipped=%d (%s=%s)"
             % (canceled, removed_mem, non_pending, "id" if row_id else "batch", row_id or batch_id))
    return {"ok": True, "canceled": canceled, "skipped": non_pending, "removed_from_memory": removed_mem}

@app.get("/api/print-queue/recovery-notice")
def api_print_queue_recovery_notice():
    """Alpha 2.629 — сводка удержанного восстановления для модалки. READ-ONLY (только SELECT).
    active=True, если есть строки status='recovery_hold' (ждут решения после прерывания очереди перезапуском).
    Не влияет на воркер/печать; ничего не пишет."""
    try:
        with lock_pr:
            held = [dict(r) for r in conn_pr.execute(
                "SELECT batch_id, printer_name, printer_id, due_ts FROM print_launch_queue "
                "WHERE status='recovery_hold' ORDER BY due_ts").fetchall()]
            att = conn_pr.execute("SELECT COUNT(*) AS c FROM print_launch_queue WHERE status='recovery_attention'").fetchone()["c"]
    except Exception:
        log.error("[PRINT-QUEUE] recovery-notice read failed: %s" % _exc_brief())
        return {"ok": False, "active": False, "held": 0, "attention": 0, "batch_ids": []}
    batch_ids = sorted({str(r["batch_id"]) for r in held if r.get("batch_id")})
    return {"ok": True, "active": len(held) > 0, "held": len(held), "attention": int(att or 0),
            "batch_ids": batch_ids, "now": time.time()}

@app.post("/api/print-queue/recovery/continue")
def api_print_queue_recovery_continue():
    """Alpha 2.629 — подтверждение продолжения удержанной очереди (recovery_hold).
    Переводит recovery_hold → pending и вкладывает элементы в in-memory print_queue (ЕДИНЫЙ путь запуска — тот же
    воркер; сверка живого статуса IDLE перед стартом СОХРАНЯЕТСЯ через _recovered_launch_ok). Прошедшие due_ts
    пере-планируем от now+GRACE с сохранением интервалов; дедуп по durable_id/printer_id (конфликт с уже стоящей
    в очереди пачкой → recovery_attention, дубль запуска не создаём). Идемпотентно: повторный вызов найдёт
    0 recovery_hold. Схему БД не трогаем; строки не удаляем; печать напрямую не запускаем."""
    global _print_queue_seq
    now = time.time()
    try:
        with lock_pr:
            rows = [dict(r) for r in conn_pr.execute(
                "SELECT id, printer_id, due_ts, payload FROM print_launch_queue "
                "WHERE status='recovery_hold' ORDER BY due_ts").fetchall()]
    except Exception:
        log.error("[PRINT-QUEUE] recovery-continue read failed: %s" % _exc_brief())
        return {"ok": False, "error": "read failed", "continued": 0}
    if not rows:
        return {"ok": True, "continued": 0, "attention": 0}   # уже решено/пусто — идемпотентно
    past = [r for r in rows if float(r.get("due_ts") or 0) <= now]
    future = [r for r in rows if float(r.get("due_ts") or 0) > now]
    plan = []   # (row, new_due)
    if past:
        base = float(past[0].get("due_ts") or now)
        for r in past:
            offset = max(0.0, float(r.get("due_ts") or now) - base)   # исходный интервал между прошлыми — сохраняем
            plan.append((r, now + _PLQ_RECOVERY_GRACE + offset))
    for r in future:
        plan.append((r, float(r.get("due_ts") or now)))
    _to_pending = []; _to_attention = []   # dids: реально вложенные в очередь / отведённые «на внимание»
    with print_queue_lock:
        existing_dids = {x.get("durable_id") for x in print_queue}
        existing_pids = {x.get("printer_id") for x in print_queue}
        for r, new_due in plan:
            did = r.get("id"); pid = str(r.get("printer_id") or "")
            if did in existing_dids or (pid and pid in existing_pids):
                _to_attention.append((did, "recovery skipped: printer already has a queued launch — verify before re-launch")); continue
            try:
                item = _jsonmod.loads(r.get("payload") or "{}")
                if not isinstance(item, dict) or not pid:
                    raise ValueError("bad payload")
            except Exception:
                _to_attention.append((did, "recovery skipped: unusable payload")); continue
            _print_queue_seq += 1
            item["id"] = str(_print_queue_seq)   # свежий in-memory id
            item["durable_id"] = did             # связь со строкой БД (== r.id)
            item["printer_id"] = pid
            item["due_ts"] = new_due
            item["recovered"] = True             # воркер применит IDLE-сверку перед стартом
            # Alpha 2.728: in-memory registry после рестарта пуст → создаём СВЕЖУЮ reservation для восстановленного
            # элемента (busy на пустом реестре не бывает; если вдруг — worker возьмёт свежую при старте по fallback).
            _rrok, _rsjid, _rrreason = _send_mgr.reserve(pid, str(item.get("printer_name") or pid), str(item.get("gcode_file") or item.get("part_name") or ""), "queue")
            # Alpha 2.741: принтером владеет кто-то ещё (напр. восстановленный проектный план: детали на
            # столе). Восстановленный элемент в очередь НЕ вкладываем — он бы крутился до отказа воркера;
            # отводим «на внимание» тем же механизмом, что и прочие конфликты recovery.
            if not _rrok and _rrreason == "printer_held":
                _to_attention.append((did, "recovery skipped: printer is held by another owner — verify before re-launch"))
                continue
            item["send_job_id"] = _rsjid if _rrok else None
            print_queue.append(item)
            existing_dids.add(did); existing_pids.add(pid)
            _to_pending.append(did)
    # durable: вложенные recovery_hold → pending (чтобы воркер+IDLE-сверка их запускали); конфликтные/битые → attention.
    # Guard 'status=recovery_hold' делает вызов идемпотентным (повторный клик ничего не перетрёт).
    try:
        with lock_pr:
            # Alpha 2.772 (A-4): два цикла связанных записей + один commit. Сбой на середине оставлял
            # часть строк переведёнными в 'pending' внутри незавершённой транзакции — следующий чужой
            # commit зафиксировал бы их, и воркер запустил бы печать по элементам, которые «Продолжить»
            # обработало лишь частично. Откат под тем же lock, исходное исключение перевыбрасывается.
            try:
                for did in _to_pending:
                    conn_pr.execute("UPDATE print_launch_queue SET status='pending', updated_at=? "
                                    "WHERE id=? AND status='recovery_hold'", (now, str(did)))
                for did, reason in _to_attention:
                    conn_pr.execute("UPDATE print_launch_queue SET status='recovery_attention', updated_at=?, last_error=? "
                                    "WHERE id=? AND status='recovery_hold'", (now, str(reason)[:500], str(did)))
                conn_pr.commit()
            except Exception:
                try:
                    conn_pr.rollback()
                except Exception:
                    log.error("[PRINT-QUEUE] SQLite rollback failed (recovery-continue): %s" % _exc_brief())
                raise
    except Exception:
        log.error("[PRINT-QUEUE] recovery-continue status update failed: %s" % _exc_brief())
    log.info("[PRINT-QUEUE] recovery-continue: в очередь=%d, →внимание=%d" % (len(_to_pending), len(_to_attention)))
    return {"ok": True, "continued": len(_to_pending), "attention": len(_to_attention), "queue": _print_queue_public()}

@app.post("/api/print-queue/recovery/cancel")
def api_print_queue_recovery_cancel():
    """Alpha 2.629 — отмена удержанной очереди. ТОЛЬКО recovery_hold → canceled (без удаления строк).
    НЕ трогает pending/launching/sent/failed/stale/recovery_attention/canceled (guard WHERE status='recovery_hold').
    recovery_hold-строк в in-memory print_queue НЕТ (их туда не клали) → чистить память не нужно. Идемпотентно."""
    now = time.time()
    canceled = 0
    _qws = []          # 16.09.2026: строки очереди ожидания отменённых запусков — вернём в ожидание
    try:
        with lock_pr:
            for _r in conn_pr.execute("SELECT payload FROM print_launch_queue "
                                      "WHERE status='recovery_hold'").fetchall():
                try:
                    _it = _jsonmod.loads(_r["payload"] or "{}")
                except Exception:
                    continue
                if isinstance(_it, dict) and _it.get("qw_id"):
                    _qws.append(str(_it["qw_id"]))
            cur = conn_pr.execute("UPDATE print_launch_queue SET status='canceled', updated_at=?, last_error='' "
                                  "WHERE status='recovery_hold'", (now,))
            canceled = cur.rowcount if (cur.rowcount and cur.rowcount > 0) else 0
            conn_pr.commit()
    except Exception:
        log.error("[PRINT-QUEUE] recovery-cancel failed: %s" % _exc_brief())
        return {"ok": False, "error": "update failed", "canceled": 0}
    for _qw in _qws:
        _qw_finish(_qw, "waiting", "восстановление запуска отменено")
    log.info("[PRINT-QUEUE] recovery-cancel: canceled=%d (только recovery_hold)" % canceled)
    return {"ok": True, "canceled": canceled}

def _moonraker_weight_stub(p, fname):
    """2.977 (R-095): вес филамента файла из метаданных Moonraker — в виде строки комментария
    слайсера, которую понимает разбор весов склада. Файл лежит на принтере, скачивать его ради
    одного числа незачем. -> bytes или b"" (метаданных нет / принтер не ответил)."""
    try:
        base = f"http://{p['ip']}:{p['port'] or 7125}"
        url = f"{base}/server/files/metadata?filename={urllib.parse.quote(fname)}"
        meta = json.loads(urllib.request.urlopen(url, timeout=6.0).read().decode("utf-8", "replace"))
        w = (meta.get("result") or {}).get("filament_weight_total")
        if w is None:
            return b""
        return ("; filament used [g] = %.2f\n" % float(w)).encode("utf-8")
    except Exception:
        log.debug("[HOOKS] метаданные Moonraker не получены: %s", _exc_brief())
        return b""


def _c1_after_dispatch(pid, p, data, fdata):
    """2.977 (R-095): списание филамента и учёт назначения материала для печати файла, УЖЕ
    лежащего на принтере. Раньше этот путь хуки не звал вовсе: остаток на привязанной катушке не
    менялся, записи «печать (авто)» в складском журнале не появлялось — владелец увидел это на
    ферме. Данные файла: у Bambu — плита, уже скачанная для проверки совместимости; у Klipper —
    вес из метаданных Moonraker; у остальных веса взять неоткуда, и это честно пишется в журнал.
    Fail-open: любая ошибка здесь не трогает уже принятую печать."""
    fname = os.path.basename(str(data.val or ""))
    try:
        _slot = getattr(data, "ams_slot", None)
        if p["type"] == "bambu":
            _bsp = int(_slot) if (_slot is not None and int(_slot) >= 0) else -1
            if _bsp == -1:
                #  16.10.2026 (R-137): какая внешняя катушка — тем же правилом и по тому же файлу, что у
                #  команды (_bambu_start_print): левая у H2D — позиция -2, хуки без ext_left её не видят.
                _xc = _bambu_ext_choice(pid, fdata, explicit=False)
                if _xc.get("ok"):
                    _xs = int(_xc.get("slot") or -1)
                    _run_after_dispatch_hooks(pid, [_xs], fdata or b"", fname)
                    _stash_run_assignments(pid, [], fdata or b"", True, ext_slot=_xs)
                else:
                    #  Какая катушка — не понять (у двухсопельного нет файла): списывать нельзя ни с одной.
                    log.info("[HOOKS] %s: файл на принтере — внешняя катушка не определена, списание пропущено (%s)",
                             pid, fname)
            else:
                _use, _map, _ = _bambu_resolve_ams(pid, _bsp, None)
                _run_after_dispatch_hooks(pid, _map if _use else [], fdata or b"", fname)
                _stash_run_assignments(pid, _map if _use else [], fdata or b"", not _use)
        elif p["type"] == "klipper":
            _fd = fdata or _moonraker_weight_stub(p, fname)
            _chosen = int(_slot) if (_slot is not None and int(_slot) >= 0) else None
            _ks, _kext = _klipper_dispatch_slots(pid, _chosen, fdata)
            _run_after_dispatch_hooks(pid, _ks, _fd, fname)
            _stash_run_assignments(pid, _ks, _fd, _kext)
        elif p["type"] == "demo":
            #  Виртуальный принтер: вес берётся из запомненного при отправке куска файла,
            #  катушка — внешняя (слот 0), как у принтера без системы подачи.
            _fd = fdata or _demo.file_data(pid, fname)
            _run_after_dispatch_hooks(pid, [0], _fd, fname)
            _stash_run_assignments(pid, [0], _fd, True)
        else:
            log.info("[HOOKS] %s: файл уже на принтере, вес филамента узнать неоткуда — списание пропущено (%s)", pid, fname)
    except Exception:
        log.debug("[HOOKS] after_dispatch для файла на принтере не выполнен: %s", _exc_brief())


def _cmd_start_print_send(p, pid, data, _preload=None):
    """C1 (Alpha 2.728): печать файла, УЖЕ находящегося на принтере (БЕЗ передачи файла). send_callable для
    менеджера. 2.977 (R-095): после принятой команды зовётся _c1_after_dispatch — списание филамента и учёт
    назначения, как при обычной отправке;
    прогресса байтов нет — только стадии «Отправка команды» → «Ожидание подтверждения».
    _preload=(data3mf, plate_path) для Bambu — файл уже загружен и проверен на совместимость СИНХРОННО в
    p_cmd (C1 confirm-precheck), фоновый _bambu_start_print только публикует команду (без повторной загрузки)."""
    ptype = p["type"]; pip = p["ip"]; pport = p["port"]; ptoken = p["token"]
    def _send(progress):
        progress(stage="sending_command")
        try:
            if ptype == "klipper":
                bs = f"http://{pip}:{pport or 7125}/printer"
                urllib.request.urlopen(urllib.request.Request(f"{bs}/print/start?filename={urllib.parse.quote(data.val)}", method="POST", headers={"User-Agent": "FM"}), timeout=15.0)
                progress(command_ok=True); _c1_after_dispatch(pid, p, data, None); return {"status": "ok"}
            if ptype == "flashforge":
                #  2.978: ответ принтера теперь читается. Прошивка отвечает code!=0 (занят, файла
                #  нет, ошибка) или запрос падает по таймауту — _flashforge_print гасит исключение
                #  внутри себя и возвращает (False, текст). Раньше это значение не проверялось:
                #  отправка помечалась успешной, а со склада списывались граммы за печать,
                #  которая не начиналась. Путь загрузки файла проверял его давно.
                _ff_ok, _ff_msg = _flashforge_print(pip, pport, ptoken, data.val.lstrip("/"))
                if not _ff_ok:
                    return {"status": "error", "reason": _ff_msg or "printer refused to start"}
                progress(command_ok=True); _c1_after_dispatch(pid, p, data, None); return {"status": "ok"}
            if ptype == "bambu":
                c = mqtt_cls.get(pid)
                if not c:
                    return {"status": "error", "reason": "no connection to the printer"}
                r = _bambu_start_print(c, pid, p, data, _preload)
                if isinstance(r, dict) and r.get("status") not in (None, "ok"):
                    return r    # incompatible/ошибка — как есть (job станет failed с причиной)
                progress(command_ok=True); _c1_after_dispatch(pid, p, data, (_preload[0] if _preload else None)); return {"status": "ok"}
        except Exception as e:
            return {"status": "error", "reason": _send_sanitize_err(e)}
        if p["type"] == "demo":
            #  2.970: файл уже «на принтере» — просто начинаем печать.
            _bed, _noz, _src = _demo.start(pid, data.val, None, time.monotonic())
            log.info("[DEMO] %s: старт печати %r (файл уже на принтере), цели: стол %d, сопло %d (%s)",
                     pid, data.val, _bed, _noz, _src)
            progress(command_ok=True); _c1_after_dispatch(pid, p, data, None); return {"status": "ok"}
        return {"status": "error", "reason": "unsupported printer type"}
    return _send

def _printer_cmd_audit(req, p, act, val, res):
    """16.10.2026 (R-145): команда принтеру или запуск печати файла с принтера — в журнал аудита:
    кто (пользователь; имя телефона _audit добавляет сам), какому принтеру, что и с каким итогом.
    Только при включённой защите: без входа «кто» неизвестен. Возвращает res без изменений."""
    if req is None or not _SECURITY_ENABLED:
        return res
    try:
        if isinstance(res, dict):
            _st, _why = res.get("status"), (res.get("reason") or res.get("error"))
        else:
            _b = json.loads(bytes(getattr(res, "body", b"") or b"{}").decode("utf-8") or "{}")
            _st, _why = _b.get("status"), (_b.get("reason") or _b.get("error"))
        u = _session_user(req) or {}
        _what = str(act) + ((" %s°C" % val) if isinstance(val, int) and not isinstance(val, bool)
                            else ((" " + str(val)) if val else ""))
        _audit(u.get("username", ""), "print.start" if act == "start_print" else "printer.cmd",
               "%s: %s" % (p["name"] if p else "", _what), "ok" if _st == "ok" else str(_why or "error"), req)
    except Exception:
        log.debug("[CMD] запись аудита не удалась: %s", _exc_brief())
    return res


@app.post("/api/printer/{pid}/cmd")
def p_cmd(pid: str, data: PCmd, req: Request = None):
    """Роут: команда принтеру (pause/resume/stop/…). start_print (печать файла на принтере) — Alpha 2.728 —
    идёт через единый менеджер фоновой отправки (reservation + панель); прочие команды синхронны как раньше.
    16.10.2026 (R-145): req — только для журнала аудита (кто послал команду)."""
    with lock_pr:
        p = conn_pr.execute("SELECT * FROM printers WHERE id=?", (pid,)).fetchone()
        if not p: return {"status": "error"}
    if data.cmd == "start_print":
        # Alpha 2.728: C1 — печать файла уже на принтере через менеджер (reservation + панель, фон).
        # server_print/маркеры ставим ТОЛЬКО при успешном захвате reservation (на 409 состояние не трогаем).
        if getattr(data, "file_ref", None):
            # Alpha 2.825: печать из файлового менеджера — ссылка резолвится и файл
            # ПЕРЕПРОВЕРЯЕТСЯ на устройстве прямо в момент старта; val клиента заменяется
            # серверным print_name. Отказ -> безопасный reason, никаких команд принтеру.
            _rt = _pf_resolve_print_target(pid, data.file_ref)
            if not isinstance(_rt, dict) or _rt.get("status") != "ok":
                _rr = _rt.get("reason") if isinstance(_rt, dict) else None
                return {"status": "error", "reason": _rr or _pf_models.REASON_STALE_REFERENCE}
            data.val = _rt["print_name"]
        _fname = os.path.basename(str(data.val or ""))
        # C1 confirm restore: для Bambu совместимость нарезки проверяем СИНХРОННО ДО создания job и reservation.
        # Несовместимый файл без force → прежний confirm-required ответ (frontend показывает подтверждение);
        # ни reservation, ни job, ни команда принтеру при этом НЕ создаются. Отмена пользователем = ничего не запущено.
        # Подтверждённый повтор приходит с force=true → compat пропускается, создаётся ровно одна reservation + фоновый job;
        # если принтер за время диалога заняла другая вкладка — begin_direct вернёт 409 (printer_send_busy).
        # Alpha 2.741: удержание принтера — отказ ДО FTP-скачивания плиты и compat (C1 иначе полез бы
        # в сеть ради заведомого отказа). Атомарная проверка повторится в begin_direct ниже.
        _hb = _hold_block(pid)
        if _hb:
            return _printer_cmd_audit(req, p, "start_print", _fname, JSONResponse(_hb, status_code=409))
        _preload = None
        if p["type"] == "bambu":
            _d3, _pp, _blk = _c1_load_plate_compat(pid, p, data)
            if _blk:
                return _blk    # {"status":"incompatible","reason":...} — прежний контракт; никаких команд принтеру
            #  16.10.2026 (R-137): внешняя катушка у двухсопельного — по соплу в файле. Не понять, какая, —
            #  отказ сразу, до задания в панели отправок и до любой команды принтеру.
            if data.ams_slot is None or int(data.ams_slot) < 0:
                _xc1 = _bambu_ext_choice(pid, _d3, explicit=False)
                if not _xc1.get("ok"):
                    return {"status": "error", "reason": _xc1.get("why")}
            _preload = (_d3, _pp)
        _ok, _job_id, _reason = _send_mgr.begin_direct(pid, p["name"], _fname, "printer_file", _cmd_start_print_send(p, pid, data, _preload))
        if _ok:
            server_print[pid] = _fname; _server_print_ts[pid] = time.monotonic(); print_source.pop(pid, None); _user_stopped.pop(pid, None)
        return _printer_cmd_audit(req, p, "start_print", _fname, _send_accept_response(_ok, _job_id, _reason, pid))
    # ── Alpha 2.782: разбор запроса ДО любого обращения к принтеру ────────────────
    # Клиент называет ЛОГИЧЕСКОЕ действие из закрытого списка; значение разбирается по
    # своему типу и диапазону, а строка команды собирается сервером заново. Раньше `val`
    # подставлялась прямо в G-code (param = f"M104 S{val}\n"), и значение "100<LF>M112"
    # превращало один разрешённый запрос в ДВЕ команды, вторая — аварийная остановка.
    # Отказ происходит до сети, до MQTT и до изменения runtime-состояния; само значение
    # не журналируется и не отражается в ответе.
    _ok, _norm, _why = _printer_cmd_policy.parse_command(data.cmd, data.val, p["type"])
    if not _ok:
        log.warning("[CMD] %s: команда отклонена (%s)", pid, _why)
        return JSONResponse({"status": "error", "reason": _why}, status_code=400)
    _act, _tc = _norm["action"], _norm["temp_c"]
    #  16.10.2026 (R-145): выключить нагрев сопла или стола посреди печати — значит сорвать её.
    #  Bambu Studio такое позволяет; у нас это более строгое правило фермы: без force:true команда
    #  не уходит, ответ 409 просит подтверждения (окно программы спрашивает и повторяет с force;
    #  телефон force не шлёт и просто получает отказ). Пауза печатью не считается — остудить можно.
    if (_act in ("nozzle", "nozzle_l", "nozzle_r", "bed") and _tc == 0 and not getattr(data, "force", False)
            and str((p_states.get(pid) or {}).get("status") or "").upper() in ("RUNNING", "PREPARE")):
        log.info("[CMD] %s: выключение нагрева во время печати отклонено (нужно подтверждение)", pid)
        return _printer_cmd_audit(req, p, _act, _tc, JSONResponse(
            {"status": "error", "reason": "heater_off_while_printing"}, status_code=409))

    def _canon_gcode():
        """Канонические строки G-code для разобранного действия (или None).
        Количество строк определяет ЖЕЛЕЗО (двухсопельная модель), а не запрос."""
        _g_ok, _lines, _ = _printer_cmd_policy.gcode_lines(
            _norm, p_states.get(pid, {}).get("nozzle_count", 1))
        return _lines if _g_ok else None

    #  2.978: пометка «остановлено владельцем» ставится ТОЛЬКО после того, как команда принята
    #  транспортом. Раньше она ставилась ДО обращения к принтеру и не откатывалась при отказе:
    #  Bambu без живой связи, Klipper с упавшим запросом и FlashForge с проигнорированным
    #  ответом получали {"status":"ok"}, принтер продолжал печатать, а телеметрия при этом
    #  маскировалась в IDLE — карточка показывала свободный принтер до конца печати, задание
    #  помечалось отменённым, а снять маску было уже нечем (она снимается переходом в RUNNING,
    #  которого не будет: печать уже шла).
    _stop_prev = None
    _cmd_sent = None          # None — транспорт ответа не даёт; True/False — даёт
    #  16.10.2026: принтер ответил отказом (Moonraker: «Klippy not ready», ошибка макроса) — команда
    #  дошла, но не выполнена. Это «не подтвердил», а не «не дошла — проверьте связь».
    _cmd_refused = False
    if _act == "stop":
        _stop_prev = (server_print.get(pid), _server_print_ts.get(pid))
        server_print.pop(pid, None); _server_print_ts.pop(pid, None)
    if p["type"] == "demo":
        #  2.970: те же действия, что у настоящих принтеров, только исполняет их часовой
        #  автомат, а не железо. Ни одного сетевого обращения.
        _n = time.monotonic()
        if _act == "pause":
            _demo.pause(pid, True, _n)
        elif _act == "resume":
            _demo.pause(pid, False, _n)
        elif _act == "stop":
            _demo.stop(pid, _n)
            _cmd_sent = True
        elif _act in ("nozzle", "nozzle_l", "nozzle_r"):
            _demo.set_target(pid, "nozzle", _tc)
        elif _act == "bed":
            _demo.set_target(pid, "bed", _tc)
        elif _act == "chamber":
            _demo.set_target(pid, "chamber", _tc)
        log.info("[DEMO] %s: команда %s", pid, _act)
    elif p["type"] == "klipper":
        bs = f"http://{p['ip']}:{p['port'] or 7125}/printer"
        _ip = p["ip"]
        try:
            if _act in ("pause", "resume", "stop"):
                # Creality K1/K2/K2 Plus управляют печатью по родному WS :9999.
                # На таких прошивках обычный Moonraker cancel/pause конфликтует с
                # фирменной службой и вешает принтер — поэтому сперва пробуем WS,
                # а на обычный Klipper (Voron и т.п., где :9999 нет) откатываемся.
                _cwmap = {"pause": {"pause": 1}, "resume": {"pause": 0}, "stop": {"stop": 1}}
                if not _creality_ws_send(_ip, {"method": "set", "params": _cwmap[_act]}):
                    _mr = "cancel" if _act == "stop" else _act
                    #  16.10.2026 (R-145): Moonraker отвечает на pause/resume/cancel только когда Klipper
                    #  доработал макрос PAUSE/CANCEL_PRINT (pause_resume.py: gcode.run_script) — медленный
                    #  макрос дольше прежних 2 с давал ложное «не доставлено». Ждём до 10 с, а тишина ПОСЛЕ
                    #  отправки запроса — «отправлено, выполняется» (ниже), не «не дошло».
                    try:
                        urllib.request.urlopen(urllib.request.Request(f"{bs}/print/{_mr}", method="POST", headers={"User-Agent": "FM"}), timeout=10.0)
                    except urllib.error.HTTPError:
                        _cmd_refused = True
                        raise   # Moonraker ответил ошибкой — команда дошла, но не выполнена
                    except urllib.error.URLError:
                        raise   # соединения не было — команда не дошла
                    except TimeoutError:
                        log.info("[KLIPPER] %s: команда %s отправлена, принтер ещё выполняет макрос", pid, _act)
                _cmd_sent = True
            else:
                # Alpha 2.782: в Moonraker уходит КАНОНИЧЕСКАЯ строка от форматтера, а не
                # склейка с пользовательским фрагментом. quote() здесь — транспортное
                # экранирование, а не защита: она сама по себе инъекцию не остановила бы,
                # потому что Moonraker декодирует %0A обратно в перевод строки.
                _lines = _canon_gcode()
                if _lines:
                    try:
                        urllib.request.urlopen(urllib.request.Request(f"{bs}/gcode/script?script={urllib.parse.quote(_lines[0])}", method="POST", headers={"User-Agent": "FM"}), timeout=2.0)
                    except urllib.error.HTTPError:
                        _cmd_refused = True
                        raise   # Moonraker ответил ошибкой — команда дошла, но не выполнена
                    except urllib.error.URLError:
                        raise   # соединения не было — команда не дошла
                    except TimeoutError:
                        log.info("[KLIPPER] %s: команда %s отправлена, ответа ещё нет", pid, _act)
                    _cmd_sent = True
        except Exception as _e:
            #  16.10.2026 (R-145): соединения нет или принтер отказал — команда не дошла (502 ниже).
            _cmd_sent = False
            log.warning(f"[KLIPPER] {pid}: command '{data.cmd}' failed: {type(_e).__name__}: {_e}")
    elif p["type"] == "creality":
        #  12.10.2026: родная служба Creality — те же команды, что у Creality Print (app/creality_native.py).
        #  Пауза, продолжение и стоп засчитываются, только когда принтер подтвердил их своим состоянием
        #  (иначе «стоп» мог бы закрыть задание в программе, пока принтер продолжает печатать).
        _cobj = {"pause": _cn.cmd_pause, "resume": _cn.cmd_resume, "stop": _cn.cmd_stop}.get(_act)
        _cobj = _cobj() if _cobj else (_cn.cmd_nozzle_temp(_tc) if _act == "nozzle" else
                                       _cn.cmd_bed_temp(_tc) if _act == "bed" else None)
        if _cobj is None:
            return _printer_cmd_audit(req, p, _act, _tc, JSONResponse(
                {"status": "error", "reason": _printer_cmd_policy.R_UNSUPPORTED}, status_code=400))
        _confirm = {"pause": {5, 6, 102}, "resume": {1, 9, 103}, "stop": {7, 4, 101}}.get(_act)
        #  16.10.2026 (R-146): у K2, K2 Pro, K2 Plus и Hi после стопа состояние сразу 0 («свободен»),
        #  без 7/4 (ha_creality_ws, stop_style 'state0'). Ноль засчитываем как подтверждение, только если
        #  ДО команды принтер печатал (1, 9), стоял на паузе (5) или вставал на неё (6): иначе «свободен»
        #  ничего не доказывает — он мог быть таким и до команды.
        if _act == "stop" and _cn._int((_creality_snap.get(pid) or {}).get("state")) in (1, 5, 6, 9):
            _confirm = _confirm | {0}
        _cmd_sent = bool(_creality_command(p["ip"], p["port"], _cobj, pid=pid, confirm=_confirm))
        if not _cmd_sent and _act != "stop":
            return _printer_cmd_audit(req, p, _act, _tc, JSONResponse(
                {"status": "error", "reason": "command_not_confirmed"}, status_code=502))
    elif p["type"] == "flashforge":
        ip, port, token = p["ip"], p["port"], p["token"]
        #  16.10.2026 (R-145, R-147): ответ принтера читается у ВСЕХ команд, а не только у «стоп».
        #  Отказ (code != 0) или тишина — «принтер не подтвердил команду» (502 ниже), как у Creality.
        if _act == "pause":
            _cmd_sent = bool(_flashforge_control(ip, port, token, {"cmd": "jobCtl_cmd", "args": {"jobID": "", "action": "pause"}})[0])
        elif _act == "resume":
            _cmd_sent = bool(_flashforge_control(ip, port, token, {"cmd": "jobCtl_cmd", "args": {"jobID": "", "action": "continue"}})[0])
        elif _act == "stop":
            _cmd_sent = bool(_flashforge_control(ip, port, token, {"cmd": "jobCtl_cmd", "args": {"jobID": "", "action": "cancel"}})[0])
        elif _act == "nozzle":
            # Alpha 2.782: температура уже разобрана и проверена политикой. Прежний int(data.val)
            # на мусорном значении выбрасывал ValueError, то есть отвечал 500 вместо отказа.
            _cmd_sent = bool(_flashforge_control(ip, port, token, {"cmd": "temperatureCtl_cmd", "args": {"rightNozzle": _tc, "platform": -200, "leftNozzle": -200, "chamber": -200}})[0])
        elif _act == "bed":
            _cmd_sent = bool(_flashforge_control(ip, port, token, {"cmd": "temperatureCtl_cmd", "args": {"platform": _tc, "rightNozzle": -200, "leftNozzle": -200, "chamber": -200}})[0])
        elif data.cmd == "start_print":
            _flashforge_print(ip, port, token, data.val.lstrip("/"))
    elif p["type"] == "bambu" and (c := mqtt_cls.get(pid)):
        pl = {}
        _qos = 0
        _pls = None
        if _act in ("pause", "resume", "stop"):
            pl = {"print": {"sequence_id": "0", "command": _act}}
            _qos = 1   # 16.10.2026 (R-145): как Bambu Studio — подтверждение приёма (PUBACK) = доставка
        elif data.cmd == "start_print":
            return _bambu_start_print(c, pid, p, data)
        elif _act == "chamber":
            #  R-104 (2.983): температуру камеры Bambu задаёт НЕ G-code, а отдельная команда
            #  протокола — ровно та, что шлёт слайсер (OrcaSlicer, DeviceManager.cpp,
            #  MachineObject::command_set_chamber): {"print": {"command": "set_ctt", "ctt_val": N}}.
            #  Число уже проверено политикой (0…65) и подставляется целым, не строкой запроса.
            pl = {"print": {"sequence_id": "0", "command": "set_ctt", "ctt_val": int(_tc)}}
        else:
            #  16.10.2026 (R-145): двухсопельная модель (H2D) — команда протокола set_nozzle_temp с
            #  номером сопла, как у Bambu Studio: левое — 1, правое — 0 (политика команд).
            _b_ok, _b_cmds, _ = _printer_cmd_policy.bambu_nozzle_commands(
                _norm, p_states.get(pid, {}).get("nozzle_count", 1))
            if _b_ok:
                _pls = _b_cmds
            else:
                # Alpha 2.782: строки собирает форматтер из уже проверенного числа. Двухсопельные
                # модели получают две строки — это решает ЖЕЛЕЗО (nozzle_count), а не запрос.
                # Завершающий перевод строки добавляет ДОВЕРЕННЫЙ адаптер, а не пользователь.
                _lines = _canon_gcode()
                if _lines:
                    pl = {"print": {"sequence_id": "0", "command": "gcode_line",
                                    "param": "\n".join(_lines) + "\n"}}
        if _pls:
            _cmd_sent = all([_bambu_publish(pid, f"device/{bambu_serials.get(pid, pid)}/request", json.dumps(_x), qos=1)
                             for _x in _pls])
            log.debug(f"[BAMBU] Command '{_act}' x{len(_pls)} -> {bambu_serials.get(pid, pid)} (доставлено: {_cmd_sent})")
        elif pl:
            _cmd_sent = _bambu_publish(pid, f"device/{bambu_serials.get(pid, pid)}/request", json.dumps(pl), qos=_qos)
            log.debug(f"[BAMBU] Command '{_act}' -> {bambu_serials.get(pid, pid)} (доставлено: {_cmd_sent})")
    elif p["type"] == "bambu":
        #  16.10.2026 (R-145): связи MQTT нет — команда никуда не ушла. Прежде пауза и температура
        #  отвечали «ок», а принтер ничего не получал.
        _cmd_sent = False
    #  16.10.2026 (R-145): доставка проверяется у ВСЕХ действий, а не только у «стоп». False —
    #  транспорта нет или он отказал: команда не дошла (FlashForge ответил отказом или молчит —
    #  «не подтвердил»). None — транспорт ответа не даёт (виртуальный принтер), как раньше «ок».
    if _act != "stop" and _cmd_sent is False:
        log.warning("[CMD] %s: команда «%s» не доставлена принтеру", pid, _act)
        return _printer_cmd_audit(req, p, _act, _tc, JSONResponse(
            {"status": "error", "reason": ("command_not_confirmed" if (p["type"] == "flashforge" or _cmd_refused)
                                           else "command_not_delivered")}, status_code=502))
    if _act == "stop":
        if _cmd_sent:
            _user_stopped[pid] = time.monotonic()
        else:
            #  Команда не ушла: печать продолжается, значит и состояние программы менять нельзя.
            if _stop_prev and _stop_prev[0] is not None:
                server_print[pid] = _stop_prev[0]
            if _stop_prev and _stop_prev[1] is not None:
                _server_print_ts[pid] = _stop_prev[1]
            log.warning("[CMD] %s: команда «стоп» не доставлена принтеру — печать не остановлена", pid)
            return _printer_cmd_audit(req, p, _act, _tc, JSONResponse(
                {"status": "error", "reason": "stop_not_delivered"}, status_code=502))
    return _printer_cmd_audit(req, p, _act, _tc, {"status": "ok"})

@app.post("/api/slicer-hook")
async def s_hook(request: Request):
    """Роут: приём манифеста плиты от хука слайсера (детали на плите)."""
    _deny = _require_slicer_callback(request)   # Alpha 2.781: ДО чтения тела и записи манифеста
    if _deny is not None:
        return _deny
    # Alpha 2.781: тело разбираем ВРУЧНУЮ, а не объявлением SData в сигнатуре. Объявленная
    # модель заставила бы фреймворк прочитать и провалидировать тело ДО входа в обработчик,
    # то есть ДО проверки ключа — а именно этого требование и запрещает. Формат запроса и
    # ответа не изменился: те же поля filename/parts, та же запись 'latest_slice'.
    try:
        body = await request.json()
    except Exception:
        body = {}
    parts = (body or {}).get("parts")
    if not isinstance(parts, dict):
        return JSONResponse({"error": "bad payload"}, status_code=400)
    with lock_p:
        conn_p.execute("INSERT OR REPLACE INTO plate_manifests (filename, parts_json) VALUES (?, ?)", ("latest_slice", json.dumps(parts)))
        conn_p.commit()
    return {"status": "ok"}

@app.get("/api/parts")
def g_parts():
    """Роут: отдать склад деталей (parts_catalog) клиенту."""
    with lock_p:
        cur = conn_p.cursor()
        parts = [dict(r) for r in cur.execute("SELECT * FROM parts_catalog ORDER BY project_name ASC, order_idx ASC").fetchall()]
    # Пост-обработка ВНЕ блокировки БД: "cb" лезет на диск (mtime файла). Какие принтеры печатают
    # деталь, фронтенд определяет сам по живым статусам (единый механизм с Quick Tasks) — поэтому
    # список active_jobs в ответе больше не нужен. Таблица active_jobs по-прежнему ведётся в
    # handle_state ради счётчика напечатанного и статуса детали в БД (это другая её роль).
    _fleet = _fleet_for_compat()
    for p in parts:
        gf = p.get("gcode_file") or ""
        cbm = 0
        fp = None
        if gf:
            sp = (p.get("src_path") or "")
            fp = sp if (sp and os.path.isfile(sp)) else None
            if not fp:
                for d in (TEMP_FILES_DIR, UPLOAD_DIR):
                    cand = os.path.join(d, gf)
                    if os.path.isfile(cand):
                        fp = cand; break
            if fp:
                try: cbm = int(os.path.getmtime(fp))
                except Exception: cbm = 0
        p["cb"] = f"{cbm}-{_BOOT}"
        if gf and fp:
            _t = _local_file_target(fp)
            p["target_model"] = (_t.get("model_raw") or _t.get("model") or "")
            p["compatible_pids"] = _compatible_pids_for(_t, _t.get("extruders"), _fleet)
        else:
            p["target_model"] = ""
            p["compatible_pids"] = _compatible_pids_for(None, None, _fleet)
    return parts

@app.post("/api/parts/save")
def s_parts(parts: List[PUpdate]):
    """Роут: сохранить склад деталей из интерфейса."""
    with lock_p, _rollback_sqlite_on_error(conn_p, "s_parts"):
        names = [p.part_name for p in parts]
        if names: 
            conn_p.execute(f"UPDATE parts_catalog SET is_deleted=1 WHERE part_name NOT IN ({','.join('?'*len(names))})", names)
        else: 
            conn_p.execute("UPDATE parts_catalog SET is_deleted=1")
            
        for p in parts: 
            conn_p.execute("INSERT INTO parts_catalog (part_name, required_qty, printed_qty, status, project_name, due_date, is_deleted, order_idx, preview_base64, notes, gcode_file, src_path) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(part_name) DO UPDATE SET required_qty=excluded.required_qty, printed_qty=excluded.printed_qty, status=excluded.status, project_name=excluded.project_name, due_date=excluded.due_date, is_deleted=excluded.is_deleted, order_idx=excluded.order_idx, preview_base64=excluded.preview_base64, notes=excluded.notes, gcode_file=excluded.gcode_file, src_path=excluded.src_path", (p.part_name, p.required_qty, p.printed_qty, p.status, p.project_name, p.due_date, p.is_deleted, p.order_idx, p.preview_base64, p.notes, p.gcode_file, getattr(p, 'src_path', '') or ''))
        conn_p.commit()
    return {"status": "success"}

COVER_DIR_CANDIDATES = ["printer_covers", "covers", "printers"]
def _covers_dir():
    """Путь к папке обложек моделей принтеров. Сначала ищем рядом с .exe (можно подложить свою папку
    printer_covers), затем — вшитую в сборку (_MEIPASS), чтобы собранный .exe был самодостаточным."""
    bases = [BASE_DIR]
    _mei = getattr(sys, '_MEIPASS', None)
    if _mei: bases.append(_mei)
    for base in bases:
        for d in COVER_DIR_CANDIDATES:
            p = os.path.join(base, d)
            if os.path.isdir(p): return p
    return os.path.join(BASE_DIR, COVER_DIR_CANDIDATES[0])

# ── Alpha 2.733: единый canonical-resolver обложек моделей. Источник истины — реальные файлы
# printer_covers/*_cover.png (allowlist). Путь из СЫРОГО пользовательского model НЕ строим — только точное
# совпадение нормализованного ключа с allowlisted-именем. Нормализация lookup: trim + схлопывание пробелов +
# casefold; отображаемое имя берём ТОЧНЫМ из файла. Неоднозначный ключ (2 разных файла → 1 нормализованный
# ключ) → fail-safe без cover. Неизвестный/пустой model → model_key=None, cover_url=''. Один и тот же реестр
# питает /api/printer-models и cover-поля /api/printers, поэтому Add Printer и «Склад» получают ОДИН cover_url.
def _norm_model_key(s):
    """Нормализация имени модели ТОЛЬКО для сопоставления (trim + схлопывание пробелов + casefold)."""
    if not s:
        return ""
    try:
        return " ".join(str(s).split()).casefold()
    except Exception:
        return ""

_cover_reg = {"dir": None, "sig": None, "by_key": {}}
#  ══ R-092: программа сама находит принтеры, объявившиеся в сети (2.980) ═════════════════
#  Слушаем то, что принтеры рассылают о себе сами, и по кнопке владельца один раз спрашиваем
#  «представься» стандартными запросами. Перебора адресов и сканирования портов НЕТ — это
#  прямой запрет владельца в пункте карты. Код доступа по сети не приходит и вводится руками.
_discovery = _pdisc.DiscoverySession(log)
_net_capture = _pdisc.NetCaptureSession(log)


def _discovery_cover_names():
    """Имена моделей из реестра обложек: модель подставляем в форму, только если она совпала
    с обложкой ТОЧНО — иначе обложки не будет, а подбор совместимого g-code начнёт врать."""
    try:
        return tuple(sorted({(v or {}).get("name") or "" for v in (_cover_registry() or {}).values()} - {""}))
    except Exception:
        return ()


def _discovery_printers():
    """Заведённые принтеры для сверки: только те поля, которые нужны сверке.

    16.10.2026 (R-092): у FlashForge серийный номер хранится не в столбце serial, а в коде доступа
    «серийник:код проверки». Для сверки берётся ТОЛЬКО часть до двоеточия; код проверки (секрет)
    дальше этой функции не уходит никогда, как и сам токен."""
    try:
        with lock_pr:
            rows = conn_pr.execute("SELECT id, name, type, ip, port, serial, token FROM printers").fetchall()
        out = []
        for r in rows:
            d = dict(r)
            tok = str(d.pop("token", None) or "")
            if (str(d.get("type") or "").lower() == "flashforge" and not str(d.get("serial") or "").strip()
                    and ":" in tok):
                d["serial"] = tok.split(":", 1)[0].strip()
            out.append(d)
        return out
    except Exception:
        log.debug("[DISCOVERY] список принтеров не прочитан: %s", _exc_brief())
        return []


def _discovery_identities():
    """Вечные признаки заведённых принтеров: {pid: {kind, value, ...}}. Живут в config.json
    (ключ printer_identity) — ни новой таблицы, ни изменения схемы базы это не требует, и
    запись попадает в резервную копию вместе с остальными настройками."""
    try:
        v = (_read_config() or {}).get("printer_identity")
        return v if isinstance(v, dict) else {}
    except Exception:
        return {}


def _discovery_learn_identity(pid, kind, value, family="", ip=""):
    """Запомнить вечный признак принтера. Пишем только когда он пришёл с адреса, по которому
    принтер и записан: иначе можно запомнить чужое устройство."""
    if not pid or not kind or not value:
        return False
    try:
        cfg = _read_config() or {}
        book = cfg.get("printer_identity")
        if not isinstance(book, dict):
            book = {}
        cur = book.get(str(pid)) or {}
        if cur.get("kind") == kind and cur.get("value") == value and cur.get("last_ip") == ip:
            return True
        book[str(pid)] = {"kind": kind, "value": str(value)[:80], "family": str(family)[:20],
                          "last_ip": str(ip)[:64], "learned_ts": time.time(), "source": "discovery"}
        cfg["printer_identity"] = book
        return bool(_write_config_atomic(cfg))
    except Exception:
        log.debug("[DISCOVERY] признак принтера не записан: %s", _exc_brief())
        return False


def _discovery_snapshot():
    printers = _discovery_printers()
    identities = _discovery_identities()
    snap = _discovery.snapshot(printers, identities, _discovery_cover_names())
    _discovery_learn_known(snap, identities)
    return snap


def _discovery_learn_known(snap, identities):
    """16.10.2026 (R-092): принтер найден ПО СВОЕМУ ЖЕ адресу («уже заведён»), а его вечный
    признак программе ещё не известен (Klipper и Creality серийного номера в базе не держат) —
    запоминаем признак сейчас. Только так «сменил адрес» вообще может сработать для этих марок:
    раньше признак запоминался лишь при смене адреса, которой без признака не бывает.
    Пишем, только когда у принтера признака ещё нет — повторный опрос снимка ничего не пишет."""
    try:
        for d in (snap.get("devices") or []):
            pid = str(d.get("printer_id") or "")
            if d.get("state") != "known" or not pid:
                continue
            cur = (identities or {}).get(pid) or {}
            if cur.get("kind") and cur.get("value"):
                continue
            ik = _pdisc.identity_key(d)
            if ik and _discovery_learn_identity(pid, ik[0], ik[1], d.get("family") or "", d.get("ip") or ""):
                log.info("[DISCOVERY] принтер %s: запомнен постоянный признак (%s) по его адресу %s",
                         pid[:8], ik[0], d.get("ip") or "")
    except Exception:
        log.debug("[DISCOVERY] признаки найденных принтеров не записаны: %s", _exc_brief())


@app.post("/api/printer-discovery/start")
def api_discovery_start(data: Dict[str, Any] = None):
    """Начать окно поиска принтеров в сети (по умолчанию 25 секунд).

    ask=false — чисто пассивный режим: слушаем и не отправляем НИ ОДНОГО байта.
    ask=true (по умолчанию) — плюс один стандартный запрос «представься» на каждую сетевую
    карту: mDNS PTR, SSDP M-SEARCH и пустая датаграмма FlashForge. Это один-два пакета, а не
    перебор сети; ровно такие же запросы в той же сети постоянно шлёт сам Windows."""
    d = data or {}
    try:
        secs = int(d.get("seconds") or 25)
    except Exception:
        secs = 25
    ok, why = _discovery.start(secs, ask=bool(d.get("ask", True)))
    if not ok:
        return {"status": "error", "reason": why}
    log.info("[DISCOVERY] поиск принтеров запущен на %d с (запросы: %s)",
             max(10, min(90, secs)), "да" if d.get("ask", True) else "нет")
    return {"status": "ok", **_discovery_snapshot()}


@app.get("/api/printer-discovery")
def api_discovery_state():
    """Снимок поиска: список найденного пополняется ПО МЕРЕ прихода пакетов, а не в конце."""
    return {"status": "ok", **_discovery_snapshot()}


@app.post("/api/printer-discovery/stop")
def api_discovery_stop():
    """Прекратить поиск досрочно и освободить сокеты. Повторный вызов безвреден."""
    _discovery.stop()
    return {"status": "ok", **_discovery_snapshot()}


@app.post("/api/printer-discovery/rebind")
def api_discovery_rebind(data: Dict[str, Any]):
    """Обновить адрес УЖЕ заведённого принтера, который переехал.

    Меняется ТОЛЬКО ip. Имя, порт, код доступа, серийный номер, модель и порядок не трогаются.
    Делается это ТОЛЬКО по нажатию владельца: адрес — это то, куда уйдёт файл и команда старта,
    и менять его молча нельзя. Устройство должно быть в текущем снимке поиска и числиться
    «сменившим адрес» — иначе отказ."""
    d = data or {}
    pid = str(d.get("printer_id") or "")
    key = str(d.get("device_key") or "")
    if not pid or not key:
        return {"status": "error", "reason": "no_id"}
    snap = _discovery_snapshot()
    dev = None
    for x in (snap.get("devices") or []):
        if x.get("key") == key:
            dev = x
            break
    if not dev:
        return {"status": "error", "reason": "device_gone"}
    if dev.get("state") != "moved" or dev.get("printer_id") != pid:
        return {"status": "error", "reason": "not_moved"}
    new_ip = str(dev.get("ip") or "")
    if not new_ip:
        return {"status": "error", "reason": "no_address"}
    #  16.10.2026 (R-020): адрес из объявления проходит ту же проверку, что адрес из формы. Разбор
    #  объявления пропускает, например, «010.0.0.5» (так его понимает inet_aton), а такой адрес
    #  сохранение принтеров не приняло бы — и связь по нему потом не запустилась бы.
    _av, _ = _paddr.check_printer_address(new_ip)
    if _paddr.is_blocking(_av):
        log.warning("[DISCOVERY] адрес принтера не обновлён: %s", _paddr.describe(_av, new_ip))
        return {"status": "error", "reason": "bad_address", "problem": _av}
    try:
        with lock_pr:
            row = conn_pr.execute("SELECT ip, port FROM printers WHERE id=?", (pid,)).fetchone()
            if not row:
                return {"status": "error", "reason": "printer_gone"}
            old_ip = row["ip"]
            conn_pr.execute("UPDATE printers SET ip=? WHERE id=?", (new_ip, pid))
            conn_pr.commit()
    except Exception:
        log.debug("[DISCOVERY] адрес принтера не обновлён: %s", _exc_brief())
        return {"status": "error", "reason": "db"}
    #  16.10.2026 (R-092): тот же порядок признаков, что у сверки (серийник, MAC, uuid Moonraker).
    _k = _pdisc.identity_key(dev)
    if _k:
        _discovery_learn_identity(pid, _k[0], _k[1], dev.get("family") or "", new_ip)
    #  16.10.2026 (R-092): связь с принтером перезапускается по НОВОМУ адресу. Воркеры берут адрес
    #  один раз при старте, и без перезапуска принтер оставался «не в сети» до перезапуска
    #  программы, хотя адрес в базе уже новый. Так же делает сохранение принтеров.
    restart_workers()
    log.info("[DISCOVERY] принтер %s: адрес обновлён %s -> %s (по нажатию владельца), связь перезапущена",
             str(pid)[:8], old_ip, new_ip)
    return {"status": "ok", "printer_id": pid, "old_ip": old_ip, "ip": new_ip}


@app.post("/api/diagnostics/net-capture/start")
def api_net_capture_start(data: Dict[str, Any] = None):
    """Записать сырьём всё, что принтеры шлют в сеть, — чтобы снять настоящий контракт фермы.

    По умолчанию НЕ ОТПРАВЛЯЕТ НИ ОДНОГО байта: только слушает. Файл кладётся в папку logs
    рядом с данными фермы; она не хранится в git, поэтому дамп никуда сам не уедет."""
    d = data or {}
    try:
        secs = max(10, min(3600, int(d.get("seconds") or 600)))
    except Exception:
        secs = 600
    out_dir = os.path.join(DATA_DIR, "logs")
    ok, why = _net_capture.start(out_dir, secs, (), bool(d.get("say_hello")))
    if not ok:
        return {"status": "error", "reason": why}
    log.info("[DISCOVERY] запись сетевых объявлений начата на %d с", secs)
    return {"status": "ok", **_net_capture.snapshot()}


@app.post("/api/diagnostics/net-capture/stop")
def api_net_capture_stop():
    """Остановить запись. Повторный вызов безвреден."""
    _net_capture.stop()
    return {"status": "ok", **_net_capture.snapshot()}


@app.get("/api/diagnostics/net-capture")
def api_net_capture_state():
    """Что записано: сколько пакетов, с каких адресов, куда лёг файл."""
    return {"status": "ok", **_net_capture.snapshot()}


def _cover_registry():
    """Canonical-реестр обложек из allowlisted printer_covers/*_cover.png: {norm_key: {model_key,name,cover_url}}.
    Кэш инвалидируется по (папка, mtime, число файлов). Неоднозначные нормализованные ключи ИСКЛЮЧАЮТСЯ
    (fail-safe без cover). Имена файлов не переименовываем/не удаляем — только читаем."""
    d = _covers_dir()
    try:
        sig = (os.path.getmtime(d), len(os.listdir(d)))
    except Exception:
        sig = None
    if sig is not None and _cover_reg["dir"] == d and _cover_reg["sig"] == sig:
        return _cover_reg["by_key"]
    by_key = {}; owner = {}; ambiguous = set()
    try:
        for f in sorted(os.listdir(d)):
            if not f.lower().endswith("_cover.png"):
                continue
            name = f[:-len("_cover.png")].replace("_", " ")
            key = _norm_model_key(name)
            if not key:
                continue
            if key in owner and owner[key] != f:
                ambiguous.add(key)      # два разных файла → один нормализованный ключ: fail-safe без cover
                continue
            owner[key] = f
            by_key[key] = {"model_key": key, "name": name, "cover_url": "/covers/" + urllib.parse.quote(f)}
    except Exception:
        log.debug("[cover_registry] exception suppressed: %s", _exc_brief())
    for k in ambiguous:
        by_key.pop(k, None)
    if sig is not None:
        _cover_reg.update({"dir": d, "sig": sig, "by_key": by_key})
    return by_key

def _resolve_cover(model):
    """Сырое имя модели → {'model_key': <canonical|None>, 'cover_url': <str>} через allowlisted registry.
    Никакого построения пути из сырого model: только точное совпадение нормализованного ключа (иначе fail-safe)."""
    key = _norm_model_key(model)
    if key:
        e = _cover_registry().get(key)
        if e:
            return {"model_key": e["model_key"], "cover_url": e["cover_url"]}
    return {"model_key": None, "cover_url": ""}

@app.get("/api/printer-models")
def printer_models():
    """Роут: canonical-список моделей (тот же registry/resolver, что питает cover-поля /api/printers).
    Поля: name (точное из файла), model_key (нормализованный canonical), cover (=cover_url)."""
    out = [{"name": e["name"], "model_key": e["model_key"], "cover": e["cover_url"]}
           for e in _cover_registry().values()]
    out.sort(key=lambda x: x["name"])
    return out

@app.get("/covers/{filename}")
def serve_cover(filename: str):
    """Роут: отдать PNG-обложку модели принтера."""
    safe = os.path.basename(filename)
    if not safe.lower().endswith(".png"): return Response(status_code=404)
    fp = os.path.join(_covers_dir(), safe)
    if os.path.isfile(fp): return FileResponse(fp, media_type="image/png")
    return Response(status_code=404)

#  R-104 (2.983): у каких моделей есть АКТИВНЫЙ нагрев камеры (а не только датчик).
#  Bambu — по перечню интеграции ha-bambulab (ACTIVE_CHAMBER_HEATER: X1E, серия H2, X2D) и
#  характеристикам H2S/H2D; датчик без нагревателя (X1C, P1S, P2S) сюда не входит. Creality —
#  K2 Plus и K2 Pro (руководство Creality по температуре камеры K2 Pro/Plus; у K2 Plus
#  нагреватель виден и в извлечённой прошивке). У Creality решает ещё и телеметрия: если
#  Moonraker отдал объект heater_generic chamber_heater, камера точно есть.
_CHAMBER_HEATER_MODEL_KEYS = frozenset((
    "bambulabx1e", "bambulabh2d", "bambulabh2dpro", "bambulabh2s", "bambulabh2c", "bambulabx2d",
    "crealityk2plus", "crealityk2pro",
))


def _chamber_heater_by_model(row):
    """Есть ли у принтера активный нагрев камеры — по типу и модели. У виртуального принтера
    камера есть намеренно: так функцию можно проверить без настоящего принтера."""
    t = str((row or {}).get("type") or "")
    if t == "demo":
        return True
    if t in ("bambu", "klipper"):
        #  Ключ — только буквы и цифры: «Bambu Lab H2D Pro», «bambu-lab h2d pro» и «H2D Pro»
        #  с пробелами/дефисами в любом виде сводятся к одному и тому же.
        _k = re.sub(r"[^a-z0-9]", "", _norm_model_key((row or {}).get("model") or ""))
        return _k in _CHAMBER_HEATER_MODEL_KEYS
    return False


@app.get("/api/printers")
def g_printers():
    """Роут: список принтеров. Alpha 2.733: аддитивно добавлены canonical model_key/cover_url из allowlisted
    registry (по сохранённому model). Старые поля не тронуты; cover_url='' и model_key=None для неизвестной/
    пустой/custom модели (напр. MT500) — потребитель показывает свой fallback."""
    with lock_pr:
        rows = [dict(r) for r in conn_pr.execute("SELECT * FROM printers ORDER BY order_idx ASC").fetchall()]
    # Alpha 2.777: наружу уходит ЯВНЫЙ allowlist (app/printer_dto.py), а не строка БД целиком.
    # Раньше SELECT * отдавал в браузер поле token — access code Bambu, serial:checkcode
    # FlashForge, API key Klipper. Теперь вместо секрета только признак credential_configured;
    # адаптеры печати читают token напрямую из БД и этой границы не касаются.
    out = []
    for r in rows:                      # резолв ВНЕ блокировки БД (registry кэширован, обращений к БД нет)
        rc = _resolve_cover(r.get("model"))
        out.append(_printer_dto.printer_public_dto(
            r, {"model_key": rc["model_key"], "cover_url": rc["cover_url"],
                "chamber_heater": _chamber_heater_by_model(r)}))
    return out

def _printer_gen(pid):
    """Ручная настройка поколения: 'new'|'old'|'auto'. По умолчанию 'auto'."""
    try:
        with lock_pr:
            r = conn_pr.execute("SELECT gen FROM printers WHERE id=?", (pid,)).fetchone()
        return (r["gen"] if r and r["gen"] else "auto")
    except Exception:
        return "auto"

def _merge_printer_secret(incoming, stored):
    """Alpha 2.776: пустое поле формы означает «оставить сохранённое», а НЕ «стереть».

    Контракт: ключ отсутствует (None) -> сохранить; пустая строка или одни пробелы ->
    сохранить; непустое значение -> заменить. Явной очистки нет намеренно: в интерфейсе
    нет кнопки «очистить токен», и придумывать её здесь незачем — чтобы убрать
    учётные данные, принтер удаляют. Значение не нормализуем (не strip): токен
    отдаётся адаптеру ровно таким, каким его ввёл человек."""
    if incoming is None:
        return stored or ""
    if not str(incoming).strip():
        return stored or ""
    return str(incoming)

@app.post("/api/printers/save")
def s_printers(printers: List[PrUpdate], req: Request):
    """Роут: сохранить список/настройки принтеров и перезапустить воркеры."""
    role = _req_role(req)
    if role is not None and not _has_perm(role, "printer_delete"):
        with lock_pr:
            existing = [r["id"] for r in conn_pr.execute("SELECT id FROM printers").fetchall()]
        incoming = set(p.id for p in printers)
        if [pid for pid in existing if pid not in incoming]:
            return JSONResponse({"status": "error", "error": "delete_forbidden"}, status_code=403)
    with lock_pr, _rollback_sqlite_on_error(conn_pr, "s_printers"):
        ids = [p.id for p in printers]
        # Alpha 2.776: действующие учётные данные читаем ВНУТРИ той же транзакции — merge
        # обязан опираться на актуальное состояние БД, а НЕ на то, что фронт видел при
        # открытии формы. Иначе устаревшая вкладка вернула бы старый токен поверх нового.
        # Ключ merge — printer id (PRIMARY KEY), поэтому payload одного принтера физически
        # не может забрать или изменить учётные данные другого.
        _rows = conn_pr.execute("SELECT id, token, serial, ip FROM printers").fetchall()
        _stored = {r["id"]: (r["token"], r["serial"]) for r in _rows}
        #  16.10.2026 (R-020): неполный или неверный адрес не принимается у НОВОГО принтера и при
        #  СМЕНЕ адреса — до любой записи. «198.68.104» Windows достраивает до публичного
        #  198.68.0.104, и связь с принтером ушла бы в интернет. Уже записанный адрес, который не
        #  меняется, сохранению не мешает: форма шлёт весь список, и старая битая запись иначе
        #  не дала бы сохранить ни один другой принтер.
        _stored_ip = {r["id"]: str(r["ip"] or "").strip() for r in _rows}
        for p in printers:
            if str(p.type or "").strip().lower() == "demo":
                continue
            if p.id in _stored_ip and _stored_ip[p.id] == str(p.ip or "").strip():
                continue
            _av, _ = _paddr.check_printer_address(p.ip)
            if _paddr.is_blocking(_av):
                log.warning("[PRINTERS] сохранение отклонено: %s", _paddr.describe(_av, p.ip))
                return JSONResponse({"status": "error", "error": "bad_address", "printer_id": p.id,
                                     "problem": _av, "ip": str(p.ip or "")[:64]}, status_code=400)
        if ids:
            conn_pr.execute(f"DELETE FROM printers WHERE id NOT IN ({','.join('?'*len(ids))})", ids)
        else:
            conn_pr.execute("DELETE FROM printers")

        for i, p in enumerate(printers):
            # Alpha 2.776: token и serial больше НЕ перезаписываются безусловно. Фронт при
            # любом сохранении отправляет весь массив принтеров, поэтому пустое или
            # потерянное поле формы прежде стирало учётные данные — причём у всего парка.
            _prev_tok, _prev_ser = _stored.get(p.id, (None, None))
            _tok = _merge_printer_secret(getattr(p, 'token', None), _prev_tok)
            _ser = _merge_printer_secret(getattr(p, 'serial', None), _prev_ser)
            conn_pr.execute("INSERT INTO printers (id, name, type, ip, port, token, gen, serial, model, order_idx) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET name=excluded.name, type=excluded.type, ip=excluded.ip, port=excluded.port, token=excluded.token, gen=excluded.gen, serial=excluded.serial, model=excluded.model, order_idx=excluded.order_idx", (p.id, p.name, p.type, p.ip, p.port, _tok, getattr(p, 'gen', 'auto') or 'auto', _ser, getattr(p, 'model', '') or '', i))
        conn_pr.commit()
    restart_workers()
    # Alpha 2.757: если печать проектов из приложения включена — обновить allowlist под новый
    # состав принтеров (добавленный принтер тоже должен стать допущенным).
    try:
        _apply_project_print_fuses()
    except Exception:
        pass
    return {"status": "success"}

@app.post("/api/printer/verify")
def verify_printer(body: PrVerify):
    """Проба адреса при добавлении: отвечает ли принтер на порте ВЫБРАННОГО типа,
    либо реально на порте другого типа (поймать «выбрал Bambu, а по адресу Klipper» и наоборот).
    Точную модель внутри типа (X1C/P1S) определить нельзя — Bambu её по сети не отдаёт.
    Возвращает {reachable, match, detected}: match=True если тип совпал, False+detected если отвечает другой тип."""
    ip = (body.ip or "").strip()
    if not ip:
        return {"status": "ok", "reachable": False, "match": None, "detected": None}
    #  16.10.2026 (R-020): неполный адрес не пробуем вовсе — Windows достроила бы «198.68.104» до
    #  публичного 198.68.0.104, и проба ушла бы в интернет. Форма показывает ошибку под полем.
    _av, _ = _paddr.check_printer_address(ip)
    if _paddr.is_blocking(_av):
        return {"status": "ok", "reachable": False, "match": None, "detected": None,
                "bad_address": True, "address_problem": _av}
    #  Адрес из интернета — только предупреждение: бывают фермы за VPN. Пробу делаем как обычно.
    _warn = {"address_warning": _paddr.GLOBAL} if _av == _paddr.GLOBAL else {}
    ptype = (body.type or "bambu").lower()
    #  12.10.2026: «creality» — родная служба Creality на заводской прошивке (порт 9999, без Moonraker).
    #  Стоит раньше flashforge: выбран Klipper, Moonraker молчит, а служба Creality отвечает — это и есть
    #  заводская прошивка, и форма предложит подключить принтер через неё.
    defaults = {"bambu": 8883, "klipper": 7125, "creality": 9999, "flashforge": 8898}
    sel_port = int(body.port) if body.port else defaults.get(ptype, 8883)
    # 1) Порт выбранного типа: открыт → тип совпал (быстрый путь для корректной настройки).
    if _tcp_probe(ip, sel_port, timeout=1.5).get("reachable"):
        return {"status": "ok", "reachable": True, "match": True, "detected": ptype, **_warn}
    # 2) Иначе пробуем дефолтные порты ДРУГИХ типов — что реально отвечает по адресу.
    detected = None
    for t, dport in defaults.items():
        if t == ptype:
            continue
        if _tcp_probe(ip, dport, timeout=1.1).get("reachable"):
            detected = t
            break
    if detected:
        return {"status": "ok", "reachable": True, "match": False, "detected": detected, **_warn}
    return {"status": "ok", "reachable": False, "match": False, "detected": None, **_warn}

def _import_plan_text(text):
    """Импорт ПЛАНА печати (CSV: имя,кол-во[,превью]) из текста.
    Общий код для загрузки файла и импорта по пути."""
    try: dialect = csv.Sniffer().sniff(text[:1024], delimiters=',;\t') if text else csv.excel()
    except Exception: dialect = csv.excel()
    with lock_p:
        for row in csv.reader(io.StringIO(text), dialect=dialect):
            if len(row) >= 2:
                preview_b64 = row[2].strip() if len(row) >= 3 else ""
                try: conn_p.execute("INSERT INTO parts_catalog (part_name, required_qty, printed_qty, status, project_name, due_date, is_deleted, order_idx, preview_base64, notes) VALUES (?, ?, 0, 'pending', 'Импортированный план', '', 0, 0, ?, '') ON CONFLICT(part_name) DO UPDATE SET required_qty=excluded.required_qty, is_deleted=0, preview_base64=excluded.preview_base64", (row[0].strip(), int(row[1].strip()), preview_b64))
                except Exception as _e: log.debug(f"[IMPORT] plan row skipped {row[:2]}: {_e}")
        conn_p.commit()
    return {"status": "success"}

@app.post("/api/upload-plan")
async def u_plan(file: UploadFile = File(...)):
    """Роут: импорт плана печати (CSV/архив) загрузкой файла."""
    text = (await file.read()).decode("utf-8")
    return _import_plan_text(text)

async def _ws_drain(ws):
    """Читает и ОТБРАСЫВАЕТ входящие сообщения сокета.

    Команд «клиент -> сервер» у WebSocket нет и в Alpha 2.786 не появляется: текст клиента
    ничего не выполняет и никакого состояния не меняет. Отдельная задача нужна лишь чтобы
    цикл перепроверки доступа мог идти по таймеру, не отменяя чтение на каждой итерации.
    Любая ошибка чтения означает конец соединения и гасится здесь; отмена (CancelledError)
    наследуется от BaseException и намеренно проходит наружу.
    """
    try:
        while True:
            await ws.receive_text()
    except Exception:
        return


@app.websocket("/ws")
async def ws_ep(ws: WebSocket):
    """WebSocket-эндпоинт: регистрация клиента для live-обновлений и его снятие при разрыве.
    При включённом режиме доступа требует валидную сессию (cookie приходит с WS-рукопожатием) — иначе отказ."""
    # Alpha 2.775: сначала ДЕШЁВАЯ проверка Origin — обычный CORS рукопожатие WebSocket
    # не защищает вовсе, поэтому без неё любая чужая страница в браузере оператора могла
    # открыть сокет к ферме и читать телеметрию. Отсутствующий Origin допускаем (нативные
    # клиенты), чужой и 'null' — закрываем ДО accept(), не запуская цикл рассылки и ничего
    # не сообщая о допустимых источниках. Причину отказа не логируем: реконнект идёт раз в
    # 3 секунды и залил бы журнал.
    try:
        if not _security_policy.ws_origin_allowed(ws.headers.get("origin"),
                                                  ws.headers.get("host"), ws.url.scheme):
            await ws.close(code=1008)
            return
    except Exception:
        log.debug("[ws_ep] origin check error: %s", _exc_brief())
        #  16.10.2026 (аудит arch-auth-18): сбой проверки источника — соединение закрывается, а не пропускается.
        try:
            await ws.close(code=1008)
        except Exception:
            pass
        return
    # Alpha 2.786: авторизация рукопожатия. Сессия берётся ИЗ ТОЙ ЖЕ cookie, что у HTTP —
    # ни query, ни заголовков, ни отдельного WebSocket-токена. Решение принимает чистый
    # движок app/websocket_access_control.py по нормализованному состоянию.
    _tok = ""
    try:
        _tok = ws.cookies.get(_SESSION_COOKIE, "") or ""
    except Exception:
        _tok = ""
    _state = _ws_auth_state(_tok)
    _verdict = _ws_access.evaluate(_state, handshake=True)
    if not _verdict.allowed:
        # Отказ ДО accept(): телеметрия не читается, задачи не создаются, к принтерам
        # обращений нет. Прикладной код проставляем, хотя при отказе на рукопожатии
        # ASGI-сервер отклоняет соединение HTTP-ответом и браузер увидит 1006 —
        # код осмыслен для нативных клиентов и журналов. Причину клиенту не поясняем.
        await ws.close(code=(_verdict.close_code or _ws_access.CLOSE_POLICY))
        return
    await ws.accept()
    active_ws.append(ws)
    _recv = asyncio.create_task(_ws_drain(ws))
    try:
        # 16.10.2026 (R-150, аудит arch-auth-15): доступ перепроверяется ВСЕГДА, и при выключенной
        # защите тоже. Прежде сокет, открытый без входа, жил и после включения защиты. При
        # выключенной защите _ws_auth_state отвечает по флагу, без обращения к базе; включили
        # защиту — сокет без входа закрывается кодом 4401 не позже чем через _WS_REVALIDATE_S.
        while True:
            _done, _ = await asyncio.wait({_recv}, timeout=_WS_REVALIDATE_S)
            if _recv in _done:
                break   # клиент отключился
            _v = _ws_access.evaluate(_ws_auth_state(_tok), handshake=False)
            if not _v.allowed:
                # Снимаем с рассылки ДО close(): иначе цикл вещания успел бы отправить
                # ещё один пакет телеметрии уже после решения об отказе.
                if ws in active_ws:
                    active_ws.remove(ws)
                log.info("[WS] соединение закрыто: доступ потерян (%s)", _v.reason)
                try:
                    await ws.close(code=(_v.close_code or _ws_access.CLOSE_POLICY))
                except Exception:
                    pass
                break
    except Exception:
        log.debug("[ws_ep] exception suppressed: %s", _exc_brief())
    finally:
        if ws in active_ws: active_ws.remove(ws)
        _recv.cancel()

