def _port_in_use(port):
    """True, если на этом компьютере на порту уже кто-то слушает."""
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(0.4)
    try:
        s.connect(("127.0.0.1", port))
        return True
    except Exception:
        return False
    finally:
        try: s.close()
        except Exception:
            log.debug("[_port_in_use] exception suppressed: %s", _exc_brief())

def _port_available(port):
    """Свободен ли порт для запуска сервера. НИКОГО НЕ ЗАВЕРШАЕТ — только проверяет.

    Alpha 2.770: прежняя версия (_free_port_if_ours) искала процесс на порту через netstat и
    ПРИНУДИТЕЛЬНО закрывала его через `taskkill /F /T`. Именно так второй запуск убивал
    работающую копию — причём уже ПОСЛЕ того, как успевал испортить её базы стартовой уборкой.
    Теперь единственный сторож одиночного запуска — ранний named mutex (app/single_instance.py),
    который срабатывает до открытия любых данных. Здесь остаётся честная проверка: порт занят —
    сообщаем и не стартуем. Ни свои, ни чужие процессы не завершаем никогда.
    """
    return not _port_in_use(port)

def _autobake_part_previews(force=False):
    """Для деталей с привязанным файлом (src_path существует) пересобираем предпросмотр ИЗ САМОГО
    ФАЙЛА и сохраняем в деталь, ПЕРЕКРЫВАЯ устаревшую/импортную картинку. Так предпросмотр всегда
    соответствует g-коду и не зависит от имени файла. Детали без своего файла не трогаем."""
    try:
        with lock_p:
            rows = [dict(r) for r in conn_p.execute(
                "SELECT part_name, src_path, preview_base64 FROM parts_catalog WHERE is_deleted=0").fetchall()]
    except Exception as e:
        log.error(f"[AUTOBAKE] reading parts failed: {e}")
        return 0
    done = 0
    for r in rows:
        try:
            sp = (r.get("src_path") or "")
            if not sp or not os.path.isfile(sp):
                continue  # нет своего файла — оставляем как есть (импортные превью сохраняем)
            png = _extract_local_png(sp, os.path.basename(sp))
            if not png:
                continue
            b64 = base64.b64encode(png).decode("ascii")
            if (not force) and b64 == (r.get("preview_base64") or ""):
                continue  # уже актуально
            with lock_p:
                conn_p.execute("UPDATE parts_catalog SET preview_base64=? WHERE part_name=?", (b64, r["part_name"]))
                conn_p.commit()
            done += 1
        except Exception:
            log.debug("[_autobake_part_previews] exception suppressed: %s", _exc_brief())
            continue
    if done:
        log.debug(f"[AUTOBAKE] previews updated from files: {done}")
    return done

@app.post("/api/parts/rebuild-previews")
def parts_rebuild_previews():
    """Принудительно пересобрать предпросмотры всех привязанных деталей из их файлов + диагностика
    (для каждой детали: есть ли файл по сохранённому пути и какого размера извлечённое превью)."""
    details = []
    updated = 0
    try:
        with lock_p:
            rows = [dict(r) for r in conn_p.execute(
                "SELECT part_name, src_path FROM parts_catalog WHERE is_deleted=0").fetchall()]
    except Exception as e:
        return {"status": "error", "reason": str(e)}
    for r in rows:
        sp = (r.get("src_path") or "")
        d = {"name": r["part_name"], "exists": bool(sp) and os.path.isfile(sp), "kb": 0, "h": "", "z": ""}
        if d["exists"]:
            try:
                png = _extract_local_png(sp, os.path.basename(sp))
                if png:
                    d["kb"] = round(len(png) / 1024.0, 1)
                    d["h"] = hashlib.md5(png).hexdigest()[:6]
                    b64 = base64.b64encode(png).decode("ascii")
                    with lock_p:
                        conn_p.execute("UPDATE parts_catalog SET preview_base64=? WHERE part_name=?", (b64, r["part_name"]))
                        conn_p.commit()
                    updated += 1
            except Exception as e:
                d["err"] = str(e)[:80]
            if sp.lower().endswith(".3mf"):
                try:
                    with zipfile.ZipFile(sp) as _z:
                        _nm = _z.namelist()
                        _g = sorted({m.group(1) for n in _nm for m in [re.match(r"Metadata/plate_(\d+)\.gcode$", n, re.I)] if m}, key=int)
                        _p = sorted({m.group(1) for n in _nm for m in [re.match(r"Metadata/plate_(\d+)\.png$", n, re.I)] if m}, key=int)
                        d["z"] = "g[" + ",".join(_g) + "] png[" + ",".join(_p) + "]"
                except Exception:
                    log.debug("[parts_rebuild_previews] exception suppressed: %s", _exc_brief())
        details.append(d)
    return {"status": "ok", "updated": updated, "details": details}

def _lan_ip():
    """IP этого компьютера в локальной сети (для подключения с других ПК).
    13.10.2026: адрес «по маршруту в интернет» сверяется с физическими сетевыми картами — VPN в режиме
    TUN перехватывает маршрут, и показывался адрес его виртуального адаптера (app/lan_address.py)."""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        try:
            return _lanaddr.best(ip)
        except Exception:
            return ip
    except Exception:
        try:
            return socket.gethostbyname(socket.gethostname())
        except Exception:
            return "127.0.0.1"

def _ensure_firewall_rule(port):
    """Пытается добавить правило брандмауэра Windows для входящих на TCP-порт, чтобы интерфейс
    открывался с других ПК сети. Нужны права администратора — если их нет, тихо пропускаем
    (пользователь добавит правило вручную). Дубликатов не создаём (сначала проверяем наличие)."""
    if not sys.platform.startswith("win"):
        return
    name = "3DIWELL Farm Server"
    try:
        chk = subprocess.run(["netsh", "advfirewall", "firewall", "show", "rule", "name=" + name],
                             capture_output=True, creationflags=_no_window_flags())
        out = (chk.stdout or b"").decode("latin-1", "ignore").lower()
        if ("localport" in out) and (str(port) in out):
            return
        subprocess.run(["netsh", "advfirewall", "firewall", "add", "rule", "name=" + name,
                        "dir=in", "action=allow", "protocol=TCP", "localport=" + str(port)],
                       capture_output=True, creationflags=_no_window_flags())
    except Exception:
        log.debug("[_ensure_firewall_rule] exception suppressed: %s", _exc_brief())

if __name__ == "__main__":
    _mp.freeze_support()   # PyInstaller + multiprocessing: дочерний процесс пула выполнит свою задачу и завершится ЗДЕСЬ, не запуская второй сервер и второй значок трея
    # Alpha 2.805: безопасные флаги запуска из desktop-оболочки. НИЧЕГО не ослабляют и не включают:
    #   --desktop-start — сервер запущен оболочкой с невидимой консолью: не звать input() при
    #                     занятом порте (иначе процесс завис бы навсегда); LAN/AUTH/трей/DATA_DIR
    #                     этот флаг НЕ меняет;
    #   --no-browser    — принят для совместимости; сервер и так НИКОГДА не открывает браузер сам
    #                     (открытие — только вручную из трея), флаг закрепляет этот контракт.
    _DESKTOP_START = "--desktop-start" in sys.argv
    _NO_BROWSER = "--no-browser" in sys.argv   # noqa: F841 — контракт «браузер не открываем» и так выполняется
    try:
        print("Starting 3DIWELL Farm Server...")
        # Читаем LAN-доступ ДО выбора bind-host, чтобы сервер сразу слушал нужный интерфейс (без
        # кратковременного 0.0.0.0). Значение фиксируем как «применённое» — его отдаёт /api/network.
        # Alpha 2.787: bind выбирается по ПРОВЕРЕННОМУ решению, а не по флагу конфигурации.
        _LAN_DECISION = _lan_effective_decision()
        _LAN_ACCESS_APPLIED = _LAN_DECISION.effective_lan_enabled
        _bind_host = _LAN_DECISION.bind_host

        # Alpha 2.806: КОНТРАКТ ПОРТА НА СТАРТЕ. Порядок кандидатов: pending (если запланирован)
        # первым, затем прежний рабочий/active. Порт становится активным ТОЛЬКО после ФАКТИЧЕСКИ
        # успешного bind собственного слушающего сокета (его же отдаём uvicorn — второго bind и
        # гонки нет). Неудача pending -> откат к прежнему порту + восстановление config. Случайный
        # порт не выбирается никогда; LAN/AUTH при откате не меняются; БД/DATA_DIR не трогаются.
        _cfg_boot = _read_config()
        if _E2E is not None and _E2E.port and not _cfg_boot.get(_port_cfg.KEY_ACTIVE):
            # Изолированный тест: стартовый порт задаётся окружением, только если его нет в
            # (тоже временном) config. Контракт pending/previous при этом НЕ меняется — смена
            # порта в тесте проверяется тем же самым механизмом, что и у пользователя.
            _cfg_boot[_port_cfg.KEY_ACTIVE] = int(_E2E.port)
        _pstate = _port_cfg.read_port_state(_cfg_boot)
        _candidates = _port_cfg.startup_plan(_cfg_boot)
        # Штатный перезапуск: дождаться, пока прежняя копия отпустит СВОЙ порт (env со старым портом).
        _wait_port = os.environ.get("FM_RESTART_WAIT_PORT")
        if _wait_port:
            try: _wp = int(_wait_port)
            except Exception: _wp = _pstate["active"]
            print("Restarting: waiting for the previous instance to release port %d..." % _wp)
            for _ in range(100):
                if not _port_in_use(_wp):
                    break
                time.sleep(0.25)

        def _bind_listener(host, port):
            """Собственный слушающий сокет (реальный production bind, БЕЗ reuse-опций — конфликт
            виден честно). -> socket или None."""
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.bind((host, int(port)))
                s.listen(128)
                s.setblocking(False)
                return s
            except Exception:
                return None

        _listen_sock, _bound_port = None, None
        for _cand in _candidates:
            _listen_sock = _bind_listener(_bind_host, _cand)
            if _listen_sock is not None:
                _bound_port = _cand
                break

        if _listen_sock is None:
            # Ни один кандидат не поднялся: config НЕ повреждаем, случайный порт НЕ выбираем.
            _pp = _pstate["active"]
            print("\n" + "="*50)
            print(" PORT %d IS USED BY ANOTHER PROGRAM " % _pp)
            print("="*50)
            print("Порт %d уже используется. Измените порт Farm Manager или закройте программу, "
                  "занимающую этот порт." % _pp)
            if not _DESKTOP_START:   # 2.805: у оболочки консоль невидима — input() повесил бы процесс
                input("\nНажмите ENTER, чтобы закрыть это окно...")
            sys.exit(1)

        # Bind подтверждён: фиксируем активный порт и приводим config к факту.
        _ACTIVE_PORT = _bound_port
        if _pstate["pending"] is not None and _bound_port == _pstate["pending"]:
            _port_cfg.commit_pending(_cfg_boot)                # pending применён -> становится active
            _write_config_atomic(_cfg_boot)
            log.info("[port] pending-порт %d применён и подтверждён bind", _bound_port)
        elif _pstate["pending"] is not None:
            _rb = _port_cfg.rollback_pending(_cfg_boot)         # pending не поднялся -> откат к прежнему
            _write_config_atomic(_cfg_boot)
            log.warning("[port] pending-порт не поднялся, откат к порту %d", _rb)
            print("")
            print(_port_msg("apply_fail", new=_pstate["pending"], old=_bound_port))
        elif _bound_port != _pstate["active"]:
            _cfg_boot[_port_cfg.KEY_ACTIVE] = _bound_port       # active-порт был занят, поднялись на fallback
            _write_config_atomic(_cfg_boot)

        if not _LAN_ACCESS_APPLIED and _lan_access_enabled():
            print("")
            print("  NETWORK ACCESS BLOCKED: %s" % _LAN_DECISION.reason)
            print("  LAN requires authorization enabled AND an active administrator.")
            print("  Open http://localhost:%d -> Settings -> System to configure." % _ACTIVE_PORT)
            log.warning("[LAN] сетевой доступ запрошен, но заблокирован: %s", _LAN_DECISION.reason)
        if _E2E is None:
            threading.Thread(target=_autobake_part_previews, daemon=True).start()
        if _LAN_DECISION.discovery_enabled:
            # Alpha 2.811: изолированный тестовый экземпляр в сеть не объявляется и firewall не
            # трогает. Гейт LAN оставлен ровно в прежней форме (это проверяемый инвариант 2.787),
            # запрет теста — вложенным условием.
            if not (_E2E is not None and _E2E.disable_discovery):
                threading.Thread(target=_discovery_beacon, args=(_ACTIVE_PORT,), daemon=True).start()   # объявление в сети — ТОЛЬКО при LAN-доступе
                _ensure_firewall_rule(_ACTIVE_PORT)                                                     # firewall НЕ трогаем при local-only
            _lan = _lan_ip()
            print("")
            print("  Open the farm interface:")
            print("    - on this computer:          http://localhost:%d" % _ACTIVE_PORT)
            print("    - from another PC on this network:  http://%s:%d" % (_lan, _ACTIVE_PORT))
            print("  (if it does not open from another PC - allow TCP port %d in Windows Firewall)" % _ACTIVE_PORT)
            print("")
            print("Farm Manager network access: LAN enabled (%s:%d)" % (_bind_host, _ACTIVE_PORT))
        else:
            print("")
            print("  Open the farm interface:")
            print("    - on this computer:          http://localhost:%d" % _ACTIVE_PORT)
            print("")
            print("Farm Manager network access: local computer only (127.0.0.1:%d)" % _ACTIVE_PORT)
        if _E2E is not None:
            # Штатное завершение изолированного экземпляра БЕЗ принудительного снятия процесса:
            # тест кладёт файл-просьбу в свою же временную папку, экземпляр её видит и уходит
            # тем же путём, что и по пункту трея «Выход». Заодно это страховка от «осиротевшего»
            # тестового сервера: папка теста удаляется — просьба появиться уже не сможет, но и
            # сам файл живёт только внутри temp-root, наружу ничего не влияет.
            def _e2e_stop_watch(_root=_E2E.root):
                _req = os.path.join(_root, "stop.request")
                while True:
                    try:
                        if os.path.exists(_req):
                            log.info("[E2E] получена просьба остановиться — штатное завершение")
                            _stop_tray()
                            os._exit(0)
                    except Exception:
                        pass
                    time.sleep(0.3)
            threading.Thread(target=_e2e_stop_watch, daemon=True).start()
        if _E2E is not None and _E2E.disable_tray:
            print("E2E isolated instance: tray/console UI disabled")   # тестовый экземпляр значка не создаёт
        elif not _start_tray_detached():   # Windows + pystray: убрать консоль в системный трей (значок у часов)
            _setup_console_window()        # запасной режим: иконка на окне + свернуть консоль в панель задач
        # uvicorn получает УЖЕ ПОДНЯТЫЙ нами сокет: второго bind нет, гонки между проверкой и стартом нет.
        _uv = uvicorn.Server(uvicorn.Config(app, host=_bind_host, port=_ACTIVE_PORT, access_log=False))
        _uv.run(sockets=[_listen_sock])
    except Exception as e:
        import traceback
        print("\n" + "="*50)
        print(" CRITICAL SERVER STARTUP ERROR ")
        print("="*50)
        traceback.print_exc()
        print("\nPossible causes:")
        print("1. Port 8000 is busy. Open Task Manager (Ctrl+Shift+Esc) and end all 'python.exe' processes.")
        print("2. Syntax error during copying (incorrect indentation).")
        input("\nНажми ENTER, чтобы закрыть это окно...")
